            int u = stk.back();
            stk.pop_back();
            order.push_back(u);
            for (int v : adj[u]) {
                if (vis[v]) continue;             // 树里每个点只会被父亲放进栈一次
                vis[v] = 1;
                par[v] = u;
                stk.push_back(v);
            }
        }

        // cnt[u] = 初始时子树 u 里 1 的个数，也就是子树 u 里最终最多能放的 1 的个数
        // 倒着扫 order，保证儿子先于父亲结算，再把自己的结果并进父亲
        vector<int> cnt(n + 1, 0);
        for (int i = n - 1; i >= 0; --i) {
            int u = order[i];
            cnt[u] += a[u];
            if (par[u] != 0) cnt[par[u]] += cnt[u];
        }

        // f[u][j] = 子树 u 内恰好选 j 个位置放 1 的方案数，
        // 且子树 u 内部（含 u 自己）每个节点的「子树 1 个数上界」都已满足
        vector<vector<long long>> f(n + 1);
        for (int i = n - 1; i >= 0; --i) {
            int u = order[i];
            int cap = cnt[u];                 // 节点 u 处的约束：子树 u 里最多放 cap 个 1
            vector<long long> g(1, 1);        // 一个孩子都还没合并时的背包：0 个 1，1 种方案
            for (int v : adj[u]) {
                if (v == par[u]) continue;    // 跳过父亲，只合并儿子
                // 背包合并：g 与 f[v] 做卷积，次数超过 cap 的项直接丢掉（次数只会单调增，丢了不影响答案）
                int lim = min(cap, (int)g.size() - 1 + (int)f[v].size() - 1);
                vector<long long> h(lim + 1, 0);
                for (int x = 0; x < (int)g.size(); ++x) {
                    if (g[x] == 0) continue;              // 0 方案数不用算
                    for (int y = 0; y < (int)f[v].size() && x + y <= lim; ++y) {
                        h[x + y] = (h[x + y] + g[x] * f[v][y]) % MOD;
                    }
                }
                g.swap(h);
                vector<long long>().swap(f[v]);           // 儿子的背包已并入，立刻释放，省内存
            }
            // 再考虑节点 u 自己：s[u] = 1 时可以放 1（多一种选择），s[u] = 0 时只能放 0
            int deg = (int)g.size() - 1 + (s[u] == 1 ? 1 : 0);
            vector<long long> h(min(deg, cap) + 1, 0);
            for (int x = 0; x < (int)g.size() && x <= cap; ++x) {
                h[x] = (h[x] + g[x]) % MOD;               // u 放 0
                if (s[u] == 1 && x + 1 <= cap) {
                    h[x + 1] = (h[x + 1] + g[x]) % MOD;   // u 放 1
                }
            }
            f[u].swap(h);
        }

        // 总 1 的个数必须和初始一样（交换不改变 1 的总数），所以取 j = cnt[1] 这一项
        long long ans = (cnt[1] < (int)f[1].size()) ? f[1][cnt[1]] : 0;
        cout << ans % MOD << "\n";
    }
    return 0;
}
```

### 易错点

只数最终位置集合，不能把不同搬动顺序重复计数。超过子树上限的状态永远不会在向上合并时变小，可以立即截断。

## E. 交换（Hard Version）

### 题意

操作与 D 相同，对每个满足上界的可达终态，计算到它的最少操作数，再把这些最少次数求和。

### 从零讲：子树里 1 的个数，决定了哪些状态走得到

一只能向祖先移动，因此每棵子树最终保留的一数 $B_u$ 不超过初值 $A_u$，差额 $D_u$ 就是必须跨父边送出的数量。总数不变意味着根没有向外送出的量。

非负差额也保证能完成搬动：从最深正差额处向上找可接收的一处零，将相邻的一上移；若一路都为一，差额会传到根，与根差额零矛盾。每一步只减少一条边的待送数量，直到全部为零。因此这些差额既描述可达性，也直接计量最少操作数。

### 思路

对终态定义差额 $D_u=A_u-B_u$。可达条件是所有差额非负、根差额为零，并满足逐点上界。

每次有效上移只让经过那条父边所对应子树的一数减少一，故只让一个 $D_u$ 减一。从初态到目标恰需 $\sum_uD_u$ 次；必要性来自每条边的净流出量，充分性来自基础小节的上移构造，根项为零。

树上背包按向父亲送出的数量 $d$ 维护二元状态 $(W,C)$，分别为终态方案数、这些方案的操作数总和。合并两个孩子状态时，方案数相乘，代价变为 $C_1W_2+W_1C_2$，因为一侧每个方案都要搭配另一侧全部方案。

孩子合计送来 $S$ 后，当前点选择保留 $b_u\in\{0,1\}$ 且 $b_u\le s_u$，向上送出 $d=a_u+S-b_u\ge0$。方案数不变，代价增加 $dW$，计入当前父边的移动次数。根只取 $d=0$ 的代价总和。

时间 $O(n^2)$，及时释放孩子数组后空间 $O(n)$。

### 参考代码

```cpp
// 牛客练习赛 152 E. 交换（Hard Version）
//
// 关键结论（详见题解「从零讲」）：
//   1) 一次交换只有在「父亲是 0、儿子是 1」时才真正改变状态，效果是把那个 1 向上搬一层；
//      所以每个 1 只能往上走，永远不能往下走，也越不过另一个 1。
//   2) 于是状态 b 可达 ⟺ 全树 1 的总数不变，且对每个节点 v：B(v) ≤ A(v)，
//      其中 A(v)/B(v) 分别是初始/最终状态里 v 的子树中 1 的个数。
//   3) 记 D(v) = A(v) - B(v)，它是「从 v 往父亲送上去的 1 的个数」。每次有效交换只让
//      恰好一个子树的 1 个数减 1，所以最少操作次数 = Σ_v D(v)。
//   4) 换个说法：节点 v 收下孩子送来的 Σ_c D(c) 个 1，加上自己原有的 a_v 个，留下 b_v 个
//      （0 或 1，s_v = 0 时只能留 0），剩下的 D(v) 个继续往上送。
//      合法状态 ⟺ 所有 D(v) ≥ 0 且 D(根) = 0；每个状态的代价恰好是 Σ_v D(v)。
//      这两件事都能在树上背包里边算边累加，于是 O(n^2) 解决。

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        vector<vector<int>> g(n + 1);                 // 邻接表（题目给的是无向边）
        for (int i = 0; i < n - 1; i++) {
            int u, v;
            cin >> u >> v;
            g[u].push_back(v);
            g[v].push_back(u);
        }
        vector<int> a(n + 1), s(n + 1);
        for (int i = 1; i <= n; i++) cin >> a[i];     // 初始权值 a_i
        for (int i = 1; i <= n; i++) cin >> s[i];     // 最终权值上界 s_i

        // ---- 以 1 为根，求出每个点的父亲与「父亲先于儿子」的顺序 ----
        vector<int> par(n + 1, 0), order;
        order.reserve(n);
        vector<int> stk;
        stk.push_back(1);
        par[1] = 0;                                   // 根的「父亲」记 0，表示没有
        while (!stk.empty()) {
            int v = stk.back();
            stk.pop_back();
            order.push_back(v);
            for (int to : g[v]) {
                if (to == par[v]) continue;           // 不走回父亲
                par[to] = v;
                stk.push_back(to);
            }
        }
        // A[v] = 初始状态里子树 v 中 1 的个数（逆序处理 = 孩子先于父亲）
        vector<int> A(n + 1, 0);
        for (int i = n - 1; i >= 0; i--) {
            int v = order[i];
            A[v] += a[v];
            if (par[v]) A[par[v]] += A[v];
        }

        // ---- 树上背包：dp_v[d] = (方案数, 方案代价和)，d = D(v) ----
        // 代价 = 该子树内的 Σ D(w)，单位就是操作次数
        vector<vector<ll>> W(n + 1), C(n + 1);
        for (int i = n - 1; i >= 0; i--) {            // 逆序：孩子全部算完才算父亲
            int v = order[i];
            // 先把所有孩子按 S = Σ_c D(c) 卷积起来
            vector<ll> accW(1, 1), accC(1, 0);        // 还没有孩子时：S = 0，方案数 1，代价 0
            for (int to : g[v]) {
                if (to == par[v]) continue;           // 父亲不是孩子
                int lb = (int)W[to].size();           // 孩子的 D 取值范围是 [0, A[to]]
                int lc = min((int)accW.size() - 1 + lb - 1, A[v]) + 1;  // S ≤ Σ_c A(c) ≤ A[v]
                vector<ll> nW(lc, 0), nC(lc, 0);
                for (int x = 0; x < (int)accW.size(); x++) {
                    for (int y = 0; y < lb && x + y < lc; y++) {
                        // 两部分的方案数相乘、代价各自乘对方的方案数再相加
                        ll w = accW[x] * W[to][y] % MOD;
                        nW[x + y] = (nW[x + y] + w) % MOD;
                        nC[x + y] = (nC[x + y] + accC[x] * W[to][y] + accW[x] * C[to][y]) % MOD;
                    }
                }
                accW.swap(nW);
                accC.swap(nC);
                vector<ll>().swap(W[to]);             // 孩子算完就释放，省内存
                vector<ll>().swap(C[to]);
            }
            // 在 v 处决策：留下 b_v 个（b_v ≤ s_v），必须有 D(v) = a_v + S - b_v ≥ 0
            W[v].assign(A[v] + 1, 0);
            C[v].assign(A[v] + 1, 0);
            for (int S = 0; S < (int)accW.size(); S++) {
                if (!accW[S] && !accC[S]) continue;
                for (int b = 0; b <= s[v]; b++) {     // s_v = 0 时只有 b = 0 这一种选择
                    int d = a[v] + S - b;             // d = D(v) = 往父亲送上去的个数
                    if (d < 0 || d > A[v]) continue;  // d < 0 说明手上不够留，非法
                    W[v][d] = (W[v][d] + accW[S]) % MOD;
                    // 代价多出 D(v) 个「跨越边 (父亲, v) 的 1」，每个方案各加一次
                    C[v][d] = (C[v][d] + accC[S] + (ll)d * accW[S]) % MOD;
                }
            }
        }
        // D(根) = 0 表示 1 的总数守恒；它的代价和就是所有合法状态的最小操作次数之和
        cout << C[1][0] % MOD << "\n";
    }
    return 0;
}
```

### 易错点

题目求各终态最短次数的总和，不是操作序列数量。合并费用必须交叉乘另一侧方案数，不能只把两个费用总和相加。

## F. 排列

### 题意

统计长 $n$ 排列中，前 $t$ 项内部正序对数落在 $[l,r]$ 的排列数。查询保证 $r\le2t$，不同 $t$ 的总和受限。

### 从零讲：逆序对分布与欧拉五边形数定理

把最大值插入一个 $t-1$ 元排列，它可以新产生零至 $t-1$ 个逆序对，因此逆序对生成函数为

$$M_t(z)=\prod_{i=1}^t(1+z+\cdots+z^{i-1})=\frac{\prod_{i=1}^t(1-z^i)}{(1-z)^t}.$$

前缀计数再除以 $1-z$。欧拉五边形数定理将无限乘积写为稀疏级数：常数项为一，在 $j(3j-1)/2$ 与 $j(3j+1)/2$ 处系数为 $(-1)^j$，其余为零。

有限乘积与无限乘积相差 $\prod_{i>t}(1-z^i)$。只求不超过 $2t$ 次项时，尾部不能同时选择两个非恒等项，因此它的倒数可截成 $1+z^{t+1}+\cdots+z^{2t}$。与 $(1-z)^{-t-1}$ 相乘，便得到正文的 $h$。NTT 只负责快速算这次卷积，数学公式在三种求值方式中完全相同。

### 思路

前 $t$ 项的相对顺序决定正序对数；选这 $t$ 个值再排列其余值，共有 $\binom nt(n-t)!=n!/t!$ 种补全方式。将相对排名取反，正序对分布与逆序对分布相同。

记 $G_t(x)$ 为 $t$ 元排列逆序对不超过 $x$ 的数量，则答案为 $(n!/t!)(G_t(r)-G_t(l-1))$。负端点取零，超过总对数 $\binom t2$ 时前缀值恒为 $t!$，不要把超界下端截成最后一个有效值。

由基础小节，在所需 $x\le2t$ 范围内，$G_t$ 的系数是稀疏五边形核与

$$h(m)=\binom{m+t}{t}+\binom{m}{t+1}$$

的卷积。第一项来自 $(1-z)^{-t-1}$，第二项是尾部修正 $z^{t+1}(1-z)^{-t-2}$ 的系数。每种 $t$ 先线性生成 $h$，再按查询量选择：少量端点直接累加 $O(\sqrt t)$ 个非零核；小规模整段用移位累加；大规模整段用 NTT 卷积。

阶乘预处理后，同一 $t$ 的计算取 $O(q_t\sqrt t)$、$O(t\sqrt t)$ 与 $O(t\log t)$ 中合适的一种，总规模由不同 $t$ 的和控制。

### 参考代码

```cpp
// F. 排列 —— 牛客练习赛 152 F 正解
//
// 两条关键结论（推导见题解「思路」）：
//   1) 答案 = (n! / t!) * ( G_t(r') - G_t(l'-1) )，
//      其中 G_t(x) = 长度 t 的排列里「逆序对数 <= x」的个数，
//      r' = min(r, C(t,2))，l' = min(l, C(t,2))（超过 C(t,2) 就取满 t!）。
//   2) 五边形数公式：G_t(x) = sum_j (-1)^j * h(x - g_j)，
//      其中 h(m) = C(m+t, t) + C(m, t+1)（m < 0 时记 0），
//      五边形数 g_j = 0, 1, 2, 5, 7, 12, 15, ...（正负两支，符号 (-1)^j）。
//      该公式只在 x <= 2t 时成立，题目恰好保证 r <= 2t。
// 同一个 t 的询问可能很多，于是备了三种求值方式（逐点公式 / 直接移位累加 / NTT 卷积），
// 按代价估计挑最省的那种，保证总运算量可控。
#include <bits/stdc++.h>
using namespace std;

static const int MOD = 998244353;    // 题目模数（同时是 NTT 友好质数）
static const int PROOT = 3;          // MOD 的原根

// 快速幂：a^e mod MOD
static int qpow(long long a, long long e) {
    long long r = 1 % MOD;
    a %= MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;   // 这一位为 1 就乘进结果
        a = a * a % MOD;              // 底数平方
        e >>= 1;                      // 指数右移
    }
    return (int)r;
}

// 迭代式 NTT：a 的长度必须是 2 的幂；inv = true 表示逆变换
static void ntt(vector<int>& a, bool inv) {
    int n = (int)a.size();
    if (n <= 1) return;
    // 第一步：位反转置换，把自然序排成蝶形需要的顺序
    for (int i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;   // 找下一个要翻转的位
        j ^= bit;
        if (i < j) swap(a[i], a[j]);           // 只在 i < j 时交换，避免换两次
    }
    // 把 n/2 个单位根一次算好，内层蝶形就不再重复求根
    vector<int> rt(n >> 1);
    int w = qpow(PROOT, (MOD - 1) / n);        // n 次本原单位根
    if (inv) w = qpow(w, MOD - 2);             // 逆变换用它的逆元
    rt[0] = 1;
    for (int i = 1; i < (n >> 1); i++) rt[i] = (long long)rt[i - 1] * w % MOD;
    // 第二步：逐层蝶形，len 是当前合并区间的长度
    for (int len = 2; len <= n; len <<= 1) {
        int half = len >> 1;
        int step = n / len;                    // 本层取根的步长
        for (int i = 0; i < n; i += len) {     // 每 len 个元素做一组蝶形
            for (int j = 0; j < half; j++) {
                int u = a[i + j];                                  // 左半
                int v = (int)((long long)rt[j * step] * a[i + j + half] % MOD); // 右半乘根
                int s = u + v; if (s >= MOD) s -= MOD;             // 和
                int d = u - v; if (d < 0) d += MOD;                // 差
                a[i + j] = s;
                a[i + j + half] = d;
            }
        }
    }
    // 逆变换最后统一除以 n
    if (inv) {
        int ninv = qpow(n, MOD - 2);
        for (int& x : a) x = (long long)x * ninv % MOD;
    }
}

int main() {
    ios::sync_with_stdio(false);   // 只用 cin/cout，关同步加速
    cin.tie(nullptr);

    int n, q;
    if (!(cin >> n >> q)) return 0;
    vector<int> qt(q), ql(q), qr(q);
    vector<int> head(n + 1, -1), nxt(q, -1);   // 按 t 把询问挂成链表
    int maxT = 1;
    for (int i = 0; i < q; i++) {
        cin >> qt[i] >> ql[i] >> qr[i];
        if (qt[i] > maxT) maxT = qt[i];
        nxt[i] = head[qt[i]];                  // 头插
        head[qt[i]] = i;
    }

    // 阶乘与逆元阶乘：上界要盖住 n!，也要盖住 C(m+t,t) 里的 m+t <= 3t
    int lim = max(n, 3 * maxT) + 5;
    vector<int> fact(lim + 1), ifact(lim + 1);
    fact[0] = 1;
    for (int i = 1; i <= lim; i++) fact[i] = (long long)fact[i - 1] * i % MOD;
    ifact[lim] = qpow(fact[lim], MOD - 2);
    for (int i = lim; i >= 1; i--) ifact[i - 1] = (long long)ifact[i] * i % MOD;
    // 组合数 C(a,b)；越界一律返回 0（正好是 h 里 C(m,t+1) 在 m<t+1 时的取值）
    auto comb = [&](long long a, long long b) -> int {
        if (a < 0 || b < 0 || b > a) return 0;
        return (long long)fact[a] * ifact[b] % MOD * ifact[a - b] % MOD;
    };

    vector<int> ans(q, 0);
    vector<int> pg, ps;   // 五边形数的指数与符号（+1 / -1），每个 t 重算

    for (int t = 1; t <= n; t++) {
        int headI = head[t];
        if (headI == -1) continue;              // 这个 t 没被问过
        int cnt = 0;                            // 本 t 的询问条数
        for (int i = headI; i != -1; i = nxt[i]) cnt++;
        long long c2 = (long long)t * (t - 1) / 2;   // 逆序对总数的上界 C(t,2)
        long long cap = min(2LL * t, c2);            // 需要的最大下标（r <= 2t，且超过 C(t,2) 就是 t!）

        // 五边形数 g_j <= cap：正支 j(3j-1)/2、负支 j(3j+1)/2，符号都是 (-1)^j
        pg.clear(); ps.clear();
        pg.push_back(0); ps.push_back(1);            // j = 0 那一项
        for (int j = 1;; j++) {
            long long g1 = (long long)j * (3 * j - 1) / 2;
            long long g2 = (long long)j * (3 * j + 1) / 2;
            if (g1 > cap && g2 > cap) break;         // 两支都超了就停
            int sg = (j & 1) ? -1 : 1;               // j 奇数取负号
            if (g1 <= cap) { pg.push_back((int)g1); ps.push_back(sg); }
            if (g2 <= cap) { pg.push_back((int)g2); ps.push_back(sg); }
        }

        // h[m] = C(m+t,t) + C(m,t+1)，m 从 0 到 cap
        vector<int> h(cap + 1);
        for (long long m = 0; m <= cap; m++)
            h[m] = (comb(m + t, t) + comb(m, t + 1)) % MOD;

        // 三种做法的代价估计（同一量级下的“基本操作”数），挑最省的
        long long costQ = 2LL * cnt * (long long)pg.size();   // 逐点：每条询问两个端点，各扫一遍五边形项
        long long costN = 0;                                  // 卷积：3 次 NTT，每次 N/2*logN 个蝶形
        {
            long long N = 1, lg = 0;
            while (N < 2 * cap + 1) { N <<= 1; lg++; }        // 线性卷积不混叠的最小长度
            costN = 9LL * N * (lg > 0 ? lg : 1);
        }
        long long costD = 0;                                  // 直接累加：每项覆盖 cap-g+1 个位置
        for (size_t k = 0; k < pg.size(); k++) costD += cap - pg[k] + 1;

        if (costQ <= costD && costQ <= costN) {
            // 模式 A：逐点套公式，只在询问端点上扫五边形项
            for (int i = headI; i != -1; i = nxt[i]) {
                long long xr = min((long long)qr[i], cap);        // 右端点（钳到 cap）
                long long xl = min((long long)ql[i] - 1, cap);    // 左端点减一
                long long sr = 0, sl = 0;                          // 两个前缀和直接用 long long 攒
                for (size_t k = 0; k < pg.size() && pg[k] <= xr; k++)
                    sr += (long long)ps[k] * h[xr - pg[k]];
                if (xl >= 0)
                    for (size_t k = 0; k < pg.size() && pg[k] <= xl; k++)
                        sl += (long long)ps[k] * h[xl - pg[k]];
                long long s = (sr - sl) % MOD;                     // 区间内的排列个数
                if (s < 0) s += MOD;
                ans[i] = (long long)fact[n] * ifact[t] % MOD * s % MOD;   // 乘上 n!/t!
            }
        } else if (costD <= costN) {
            // 模式 B：直接按五边形项移位累加，一次算出 G 的整段 0..cap
            vector<long long> acc(cap + 1, 0);                     // 先攒不取模，项数不多不会溢出
            for (size_t k = 0; k < pg.size(); k++) {
                int g = pg[k], sg = ps[k];
                for (long long x = g; x <= cap; x++) acc[x] += (long long)sg * h[x - g];
            }
            vector<int> G(cap + 1, 0);
            for (long long x = 0; x <= cap; x++) {
                long long v = acc[x] % MOD;
                if (v < 0) v += MOD;
                G[x] = (int)v;
            }
            for (int i = headI; i != -1; i = nxt[i]) {
                long long xr = min((long long)qr[i], cap);
                long long xl = min((long long)ql[i] - 1, cap);
                long long s = G[xr] - (xl >= 0 ? G[xl] : 0);
                s %= MOD;
                if (s < 0) s += MOD;
                ans[i] = (long long)fact[n] * ifact[t] % MOD * s % MOD;
            }
        } else {
            // 模式 C：把 h 与 ±1 核做一次 NTT 卷积，等价于模式 B 但快得多
            int N = 1;
            while (N < 2 * cap + 1) N <<= 1;                       // 长度够到不混叠
            vector<int> fa(N, 0), fb(N, 0);
            for (long long m = 0; m <= cap; m++) fa[m] = h[m];     // 左乘数：h
            for (size_t k = 0; k < pg.size(); k++)                 // 右乘数：五边形核
                fb[pg[k]] = (ps[k] > 0) ? 1 : MOD - 1;
            ntt(fa, false);
            ntt(fb, false);
            for (int i = 0; i < N; i++) fa[i] = (long long)fa[i] * fb[i] % MOD;   // 点值相乘
            ntt(fa, true);                                          // 逆变换回系数
            for (int i = headI; i != -1; i = nxt[i]) {
                long long xr = min((long long)qr[i], cap);
                long long xl = min((long long)ql[i] - 1, cap);
                long long s = fa[xr] - (xl >= 0 ? fa[xl] : 0);      // fa[0..cap] 就是 G
                s %= MOD;
                if (s < 0) s += MOD;
                ans[i] = (long long)fact[n] * ifact[t] % MOD * s % MOD;
            }
        }
    }

    for (int i = 0; i < q; i++) {                 // 一行输出 q 个答案
        if (i) cout << ' ';
        cout << ans[i];
    }
    cout << '\n';
    return 0;
}
```

### 易错点

前 $t$ 项内部的正序对，与这些项同后面元素形成的对无关。五边形系数有正有负，模运算需规范负值。

## G. 美丽

### 题意

给定主串 $s$，对每个询问串 $t$ 的每个非空前缀 $p$，判断它是否存在某个循环移位，恰为 $s$ 的子串。主串总长与所有询问串总长分别不超过 $2\times10^5$，字符均为小写字母。

### 从零讲：后缀自动机的 endpos 与后缀链接链

后缀自动机用 $O(n)$ 个状态表示主串的所有子串。从初始状态沿字符转移，能走出的字符串恰好是主串的子串。它能够压缩状态，靠的是把**出现右端点相同**的子串放到一组。

一个子串的 $\operatorname{endpos}$ 是它在主串中所有出现的右端点集合。例如主串 ababa 中，ba 与 aba 都只在第三、第五位结束，二者可以共用状态 $v$。

![同一个后缀自动机状态，可能包含多个长度](assets/g-state.svg)

状态 $v$ 保存本组的最大长度 $\operatorname{len}(v)$。删去开头字符会得到更短的后缀；只要右端点集合不变，仍留在本组。第一次变为严格更大的右端点集合时，便来到后缀链接 $\operatorname{link}(v)$ 指向的状态。因此本组长度恰是连续区间

$$\bigl(\operatorname{len}(\operatorname{link}(v)),\operatorname{len}(v)\bigr].$$

上图中 $v$ 包含长度二、三，后缀链接指向 $\text{a}$ 所在的长度一状态。沿链接不断走，便依次得到更短后缀所在的组。

扫描其他字符串时，同时维护状态 $u$ 和实际匹配长度 $h$。有字符转移就继续；失配就沿后缀链接缩短，直到能够继续或退回初始状态。这样 $h$ 始终是已读部分在主串中出现的最长后缀长度。每读一个字符最多让 $h$ 增一，每次回退都使它变小，因此总回退次数为线性级别。注意 $h$ 可以小于当前状态的最大长度，上图给出了混用二者会产生的错误。

代码建机时，每加入主串的一个字符就建立新状态，并沿后缀链接补字符转移；若一个旧状态的长度区间需要拆开，就复制其转移建立克隆。每个字符至多新建普通、克隆两个状态。代码还记录每个主串前缀的状态，后面会用它把出现位置的信息汇总到整组。

### 思路

设当前前缀为 baa，主串为 ababa。前缀本身没有出现，但旋转为 aba 后会出现。下面两种方法，都是在寻找这个连续窗口。

![同一循环移位：短询问扫窗口，长询问找切口](assets/g-rotations.svg)

**短询问：每个前缀分别扫描双倍串。** 若前缀 $p$ 长为 $j$，把 $p+p$ 的最后一个字符去掉，其中恰有 $j$ 个长度为 $j$ 的窗口，依次就是全部循环移位。将这条长 $2j-1$ 的串在主串自动机上扫描，只要最长匹配后缀达到 $j$，就找到了一个出现在主串中的旋转。

一个前缀花 $O(j)$，长为 $m$ 的询问合计 $O(m^2)$。这个方法没有扫描主串的开销，特别适合大量短询问。

**长询问：先算主串每个切口右边能匹配多长。** 对固定询问 $t$，令

$$D[p]=\operatorname{LCP}(t,s[p..n]),\qquad D[n+1]=0.$$

这里 $\operatorname{LCP}$ 就是两串从开头起相同的字符数。把 $t$、分隔符和 $s$ 拼起来，求每个位置的 Z 值，即“从这里开始与整串开头匹配多长”，便能一次得到全部 $D$。Z 算法保留当前最靠右的匹配区间：区间内部先复用已有 Z 值，只在超出已知边界时继续比较；右边界总共只向右移动整串长度次，所以总时间为 $O(n+m)$。

对于当前前缀 $t[1..j]$，再设 $E[j][y]$ 为它与 $s[1..y]$ 的最长公共后缀长度。存在旋转子串，当且仅当存在切口 $y\mid y+1$，满足

$$E[j][y]+D[y+1]\ge j.$$

充分性很直接：左边取长 $E[j][y]$ 的前缀末尾部分，右边取剩余的 $j-E[j][y]$ 个前缀开头字符，两段在主串中紧邻，拼起来就是一个旋转。反过来，把任意旋转子串按这两部分切开，就得到满足不等式的切口。空的左段或右段也允许，所以原前缀直接出现的情况不会漏掉。

图中 $t=\text{baa}$，在 $s$ 的第一个 $\text{a}$ 后切开，左边匹配前缀末尾的 $\text{a}$，右边匹配开头的 ba，因此 $1+2=3$。若主串为 abzcd、询问前缀为 abcd，虽然 ab、cd 分别出现过，两段却无法在同一切口拼接，所以答案仍为零。

**利用相同的右端点集合，共享右接长度。** 为每个自动机状态定义

$$M(v)=\max_{y\in\operatorname{endpos}(v)}D[y+1].$$

先把每个 $D[y+1]$ 写到主串前缀 $s[1..y]$ 的状态上。一个子串在 $y$ 结束，当且仅当它是该前缀的后缀，因此沿后缀链接向上取最大值，就把这个位置的权值送到了全部应该接收的状态。按状态长度递减处理，一遍即可求完 $M$；初始状态额外纳入空前缀对应的 $D[1]$。

扫描询问串到第 $j$ 位时，设最长出现后缀长为 $h$、所在状态为 $u$。所有能出现的更短后缀正好分布在 $u$ 及其后缀链接链上。同组共享 $M$，自然选其中最长的后缀：当前组只能取实际长度 $h$，更短的祖先组可以取整组最大长度。

于是先按长度递增预处理

$$B(v)=\max\bigl(\operatorname{len}(v)+M(v),B(\operatorname{link}(v))\bigr).$$

第 $j$ 位要比较的最大值便是

$$\max\bigl(h+M(u),B(\operatorname{link}(u))\bigr).$$

它不小于 $j$ 就输出一。初始状态没有后缀链接，只取第一项。每个长询问求一次 Z 值、做两次状态遍历、扫描一次自身，总时间 $O(n+m)$。

**最后按长度选择方法。** 令阈值 $L=2\lfloor\sqrt n\rfloor$。短询问 $m\le L$ 使用平方算法，长询问使用线性扫描主串的算法。设本组询问总长为 $A$，短询问总开销不超过 $LA$，长询问数少于 $A/L$，总开销不超过 $O(nA/L+A)$。加上建机，得到

$$O(n+LA+nA/L+A)=O(n+A\sqrt n).$$

代码先将超过 $n$ 的前缀答案保留为零，只处理前 $n$ 个字符，不会影响这个上界。空间为 $O(n+\max |t|)$，字母表大小视为常数。不同数据组分别处理，也满足题目的总长度限制。

### 参考代码

```cpp
// G. 美丽：短询问扫描前缀双倍串，长询问用 Z 函数与后缀自动机。
// 总时间 O(n + M*sqrt(n))，M 为询问总长度；不使用字符串哈希。
#include <bits/stdc++.h>
using namespace std;

struct SAM {
    struct Node {
        int next[26], link = -1, len = 0;
        Node() { fill(next, next + 26, -1); }
    };
    vector<Node> st;
    vector<int> prefix, order;
    explicit SAM(const string &s) : prefix(s.size() + 1) {
        st.reserve(2 * s.size());
        st.emplace_back();
        int last = 0;
        for (int i = 0; i < (int)s.size(); ++i) {
            int c = s[i] - 'a', cur = (int)st.size();
            st.emplace_back();
            st[cur].len = st[last].len + 1;
            int p = last;
            while (p != -1 && st[p].next[c] == -1) {
                st[p].next[c] = cur;
                p = st[p].link;
            }
            if (p == -1) st[cur].link = 0;
            else {
                int q = st[p].next[c];
                if (st[p].len + 1 == st[q].len) st[cur].link = q;
                else {
                    // 克隆只拆分长度区间，转移和旧后缀链接均复制。
                    int clone = (int)st.size();
                    st.push_back(st[q]);
                    st[clone].len = st[p].len + 1;
                    while (p != -1 && st[p].next[c] == q) {
                        st[p].next[c] = clone;
                        p = st[p].link;
                    }
                    st[q].link = st[cur].link = clone;
                }
            }
            last = cur;
            prefix[i + 1] = cur;
        }
        vector<int> count(s.size() + 1);
        for (const auto &v : st) count[v.len]++;
        for (int i = 1; i <= (int)s.size(); ++i) count[i] += count[i - 1];
        order.resize(st.size());
        for (int v = (int)st.size() - 1; v >= 0; --v) order[--count[st[v].len]] = v;
    }

    // 扫描一个字符，维护已经读入部分在 s 中出现的最长后缀。
    void advance(int c, int &u, int &length) const {
        while (u != 0 && st[u].next[c] == -1) {
            u = st[u].link;
            length = st[u].len;
        }
        if (st[u].next[c] != -1) { u = st[u].next[c]; ++length; }
        else { u = 0; length = 0; }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        int n, q;
        string s;
        cin >> n >> q >> s;
        SAM sam(s);
        int states = (int)sam.st.size();
        int threshold = max(1, 2 * (int)sqrt(n));
        vector<int> value(states), best(states), z;
        while (q--) {
            string t;
            cin >> t;
            string answer(t.size(), '0');
            // 超过 n 的前缀不可能成为 s 的子串，其答案直接保留为零。
            if ((int)t.size() > n) t.resize(n);
            int m = (int)t.size();
            if (m <= threshold) {
                for (int j = 1; j <= m; ++j) {
                    int u = 0, length = 0;
                    // p+p 去掉末字符，恰好含 p 的全部 j 个循环移位窗口。
                    for (int k = 0; k < 2 * j - 1; ++k) {
                        sam.advance(t[k < j ? k : k - j] - 'a', u, length);
                        if (length >= j) { answer[j - 1] = '1'; break; }
                    }
                }
            } else {
                string combined = t + '#' + s;
                int total = (int)combined.size();
                z.assign(total, 0);
                int left = 0, right = 0;
                for (int i = 1; i < total; ++i) {
                    if (i < right) z[i] = min(right - i, z[i - left]);
                    while (i + z[i] < total && combined[z[i]] == combined[i + z[i]]) ++z[i];
                    if (i + z[i] > right) { left = i; right = i + z[i]; }
                }

                fill(value.begin(), value.end(), 0);
                value[0] = z[m + 1];  // 空后缀在位置 0 结束，右边匹配 s[1..]。
                for (int y = 1; y < n; ++y) {
                    int v = sam.prefix[y];
                    value[v] = max(value[v], z[m + y + 1]);
                }
                // 前缀终点沿后缀链接上传，得到各 endpos 集合上的最大 D。
                for (int i = states - 1; i > 0; --i) {
                    int v = sam.order[i], p = sam.st[v].link;
                    value[p] = max(value[p], value[v]);
                }
                for (int v : sam.order) {
                    int p = sam.st[v].link;
                    best[v] = sam.st[v].len + value[v];
                    if (p != -1) best[v] = max(best[v], best[p]);
                }

                int u = 0, length = 0;
                for (int j = 1; j <= m; ++j) {
                    sam.advance(t[j - 1] - 'a', u, length);
                    int candidate = length + value[u], p = sam.st[u].link;
                    // 当前状态可能只匹配到区间中间；祖先状态才取最大长度。
                    if (p != -1) candidate = max(candidate, best[p]);
                    if (candidate >= j) answer[j - 1] = '1';
                }
            }
            cout << answer << '\n';
        }
    }
}
```

### 易错点

每个前缀都要使用自己的双倍串，不能用整个询问串的双倍串代替。长询问必须保持主串两段相邻；当前状态使用实际匹配长度，不能直接使用状态最大长度。答案不一定连续，例如主串 abc、询问 cab 的答案是 $101$。

## A. 字符插入

### 题意

在数字串中恰好插入一个字符六，最大化子序列 2026 的个数，输出任一最优插入位置。

### 思路

原有的 2026 全部保留，新增的每一个都必须以插入的六结尾，因此新增数量恰为插入点左边的 202 子序列数。前缀越长，这个数量只增不减，所以直接插到末尾一定最优。

保留的代码进一步找最早最优位置：扫描记录二的数量与 20 的数量，只有遇到二且此前已有 20 时，202 的数量才增长。记录最后一次增长后的插入位置；若从未增长，取零。时间 $O(|s|)$，额外空间 $O(1)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关闭 cin/cout 与 stdio 的同步，读入更快
    cin.tie(nullptr);              // 解除 cin 与 cout 的绑定，避免多余的刷新

    int T;                         // T = 测试数据组数
    cin >> T;
    while (T--) {                  // 逐组处理
        string s;                  // 当前组的字符串，只由数字字符组成
        cin >> s;

        long long cnt2 = 0;        // 已扫过的前缀里，子序列 "2" 的个数
        long long cnt20 = 0;       // 已扫过的前缀里，子序列 "20" 的个数
        long long best = 0;        // 答案：能取到最大价值的最小插入位置

        for (int idx = 0; idx < (int)s.size(); ++idx) {
            char ch = s[idx];
            if (ch == '2') {
                // 前缀里已经攒下 "20" 时，这个 2 必然让前缀的 "202" 计数涨一截，
                // 于是最优插入位置可以推到它后面（取最后一次推到的位置）
                if (cnt20 > 0) best = idx + 1;
                cnt2 += 1;         // 它自己也能当 "2" 的收尾字符
            } else if (ch == '0') {
                cnt20 += cnt2;     // 这个 0 能接在前面每个 "2" 后面，凑出新的 "20"
            }
            // 其它数字字符对子序列 202 没有任何贡献，直接跳过
        }

        // best = 前缀 "202" 计数最后一次增长的位置，也就是价值第一次取到最大值的插入位置
        cout << best << "\n";
    }
    return 0;
}
```

### 易错点

子序列不要求连续，不能用字符串查找统计 202。任意最优位置都合法，无需刻意与样例位置一致。

## B. 前缀和

### 题意

删除数组中恰好一项，让剩余数组所有前缀和之和最大，输出删除下标。

### 思路

原位置 $t$ 出现在 $n-t+1$ 个前缀中。删除 $i$ 后，它自身贡献消失，左侧每项少出现一次，右侧项的位置前移与长度减一相互抵消，贡献次数不变。

所以相对于同一个原始总和，删除 $i$ 损失 $\sum_{t<i}a_t+(n-i+1)a_i$。扫描前缀和，选择这个式子最小的位置即可，不必计算可能更大的原始总和。时间 $O(n)$，空间 $O(n)$。

### 参考代码

```cpp
// 牛客练习赛 153 B. 前缀和
// 记 C = 不删任何元素时的前缀和总和 = sum a[t]*(n-t+1)（常数）。
// 删掉第 i 个元素后，只有它自己和它左边的元素各少被数一次：
//   S(i) = C - (a[1]+...+a[i-1]) - a[i]*(n-i+1)
// 于是「最大化 S(i)」等价于「最小化 h(i) = pre[i-1] + a[i]*(n-i+1)」，一趟扫描即可。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关掉 cin/cout 与 stdio 的同步，读入更快
    cin.tie(nullptr);              // 解除 cin 与 cout 的绑定，省一次刷新
    int T;
    cin >> T;                      // 数据组数
    while (T--) {
        int n;
        cin >> n;                              // 本组序列长度
        vector<long long> a(n + 1, 0);         // 存 a[1..n]，多开一位防越界
        for (int i = 1; i <= n; ++i) cin >> a[i];
        int best = 1;                          // 当前最优的删除位置（1 起）
        long long bestVal = LLONG_MAX;         // 对应的 h(best)，要取最小
        long long pre = 0;                     // pre = a[1] + ... + a[i-1]，边扫边维护
        for (int i = 1; i <= n; ++i) {
            long long h = pre + a[i] * (long long)(n - i + 1);
            if (h < bestVal) {                 // 严格小于：并列时保留更小的下标
                bestVal = h;
                best = i;
            }
            pre += a[i];                       // 补上 a[i]，给下一轮当 pre 用
        }
        cout << best << '\n';                  // 输出该删除位置
    }
    return 0;
}
```

### 易错点

元素可为负数，损失也可能为负；初始化最优值为足够大的数，而不是零。乘法用 64 位。

## C. 博弈

### 题意

可选一次区间，对其中元素依次加一、二、三等，也可不操作。判断能否使奇数个数严格超过偶数个数。

### 从零讲：最大子段和

最大子段和可用一个末尾状态求。设当前最优末尾和为 $f$，读入收益 $d$ 后，最优段要么接在之前段后面，要么从当前重新开始；允许空段时写为 $f=\max(0,f+d)$。

再用一个全局最大值记录所有 $f$。负的前缀只会拖累后面，因此归零不损失最优解。本题允许不操作，空段收益零正好有实际含义。两条奇偶下标链分别执行这一过程。

### 思路

区间中只有与左端同奇偶的下标加上奇数、发生奇偶翻转。将下标拆成奇数链和偶数链，一次操作恰好翻转其中一条链的连续段，链上任意连续段也都可用原区间实现。

![区间操作对应一条奇偶下标链上的连续段](assets/c-parity.svg)

给原本偶数记收益一，原本奇数记收益负一，翻转段带来的奇数数量增量就是段收益之和。分别求两条链最大子段和，与不操作的收益零取最大 $G$。若原奇数数目为 $O$，胜利当且仅当 $2(O+G)>n$。

扫描时间 $O(n)$，空间 $O(n)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关闭 cin/cout 与 stdio 的同步，读入更快
    cin.tie(nullptr);              // 解除 cin 与 cout 的绑定，避免多余的刷新

    int T;                         // T = 测试数据组数
    cin >> T;
    while (T--) {                  // 逐组处理
        int n;                     // 当前组的数组长度
        cin >> n;
        vector<long long> a(n + 1); // 1-based 存数组，只关心每个数的奇偶性
        int odd = 0;               // 初始奇数的个数
        for (int i = 1; i <= n; ++i) {
            cin >> a[i];
            if (a[i] % 2 != 0) ++odd;   // 统计初始奇数个数
        }

        // 选区间 [l, r] 时，第 i 位加上的是 i-l+1：i 与 l 同奇偶就加奇数（奇偶性翻转），
        // 否则加偶数（奇偶性不变）。所以一次操作 = 在下标 l, l+2, l+4, ... 这条链上
        // 取一个前缀并全部翻转奇偶性。翻转偶数收益 +1，翻转奇数收益 -1，
        // 于是「收益最大的操作」= 两条链（奇数下标链、偶数下标链）上的最大子段和。
        long long best = 0;        // 最大收益；取 0 表示可以啥也不干（操作是可选的）
        for (int start = 1; start <= min(2, n); ++start) {  // 两条链的起点分别是 1 和 2
            long long cur = 0;     // Kadane：以当前元素结尾的最大子段和
            for (int i = start; i <= n; i += 2) {           // 沿同奇偶的链往后走
                long long d = (a[i] % 2 == 0) ? 1 : -1;     // 这一位被翻转后的收益
                cur = max(cur + d, d);                      // 接着上一段，或从这一位重开一段
                best = max(best, cur);                      // 所有链、所有子段里取最大
            }
        }

        // 最终奇数个数 = odd + best，它要严格多于偶数个数 n - odd - best
        cout << (2 * (odd + best) > n ? "Alice" : "Bob") << "\n";
    }
    return 0;
}
```

### 易错点

链上选的是任意连续段，不只是从链头开始的前缀。平局不算 Alice 获胜，比较必须严格大于。

## D. 异或和I

### 题意

将数组切成异或值非降的连续非空段，求最多段数以及达到最多段数的切法数，计数对给定模数取模。

### 从零讲：前缀异或和

异或满足相同值异或两次抵消。定义 $P_0=0$、$P_i=a_1\oplus\cdots\oplus a_i$，则 $P_r\oplus P_{l-1}$ 中前 $l-1$ 项成对消掉，剩下的正是区间 $[l,r]$ 的异或。

因此任意候选段只需一次异或，不必重新扫描段内元素。输入值小于 $2^{12}$，前缀与区间异或也小于 $2^{12}$，让以异或值作为第二维的动态规划可行。

### 思路

设 $f_i(v)$ 保存前 $i$ 项、末段异或值为 $v$ 时的最大段数和对应方案数。同一状态中较少段的方案对未来不会更有利，可以舍弃。

枚举最后一刀 $j<i$，新段异或 $v=P_i\oplus P_j$；前一段只需异或值不超过 $v$。因此为每个已完成前缀预存 $g_j(v)$：所有末段值不超过 $v$ 的最大段数及其方案数。新状态由 $g_j(v)$ 的段数加一更新，更优则覆盖，相同则累加。

算完一行 $f_i$ 后，沿值域做前缀最优得到 $g_i$，供后续查询。不同最后切点对应不同划分，不会重复。异或值域为 $V=4096$，时间 $O(n^2+nV)$，空间 $O(nV)$。

### 参考代码

```cpp
// D. 异或和I
// 划分数组为若干连续段，段异或和序列单调不减；求最大段数与取到最大段数的方案数。
// 做法：记 pre[i] 为前缀异或和，用 g[j][v] = 「前缀 j 的划分里最后一段异或 <= v 时
//       的最大段数」做 DP，按上一刀位置 j 枚举转移，再把 dp 抹成前缀最值供下一步查询。
#include <bits/stdc++.h>
using namespace std;

// a_i <= 3000 < 4096 = 2^12，所以任意段（以及前缀）的异或值都落在 [0, 4096)
static const int V = 4096;      // 异或值的取值范围（0 .. V-1）
static const int MAXN = 3005;   // n 的上界 3000，多留几个

// gBest[j][v]：前缀 j 的合法划分中，最后一段异或值 <= v 时能取到的最大段数（-1 表示不可达）
// gCnt [j][v]：取到该最大段数的方案数（已对 mod 取模）
static short gBest[MAXN][V];
static unsigned int gCnt[MAXN][V];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long mod;
    if (!(cin >> n >> mod)) return 0;

    vector<int> pre(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        int x;
        cin >> x;
        pre[i] = pre[i - 1] ^ x;      // pre[i] = a_1 ^ ... ^ a_i
    }

    // 边界状态：空前缀（j = 0）。它由 0 段组成、方案数 1，且对任意上界 v 都满足「最后一段异或 <= v」
    for (int v = 0; v < V; ++v) {
        gBest[0][v] = 0;
        gCnt[0][v] = (unsigned int)(1 % mod);
    }

    // 当前前缀的 dp 值：curBest[v] / curCnt[v]，含义是「最后一段异或恰为 v」时的最大段数与方案数
    vector<int> curBest(V, -1);
    vector<unsigned int> curCnt(V, 0);

    for (int i = 1; i <= n; ++i) {
        fill(curBest.begin(), curBest.end(), -1);
        fill(curCnt.begin(), curCnt.end(), 0);

        // 枚举上一刀的位置 j：新加的一段是 [j+1, i]，它的异或值是 pre[i] ^ pre[j]
        for (int j = 0; j < i; ++j) {
            int v = pre[i] ^ pre[j];              // 这一段（也就是划分的最后一段）的异或值
            short b = gBest[j][v];                // 前缀 j 的最后一段异或必须 <= v
            if (b < 0) continue;                  // 前缀 j 无法以 <= v 的异或值收尾
            int cand = b + 1;                     // 段数加一
            unsigned int c = gCnt[j][v];
            if (cand > curBest[v]) {
                curBest[v] = cand;
                curCnt[v] = c;
            } else if (cand == curBest[v]) {
                // 不同的 j 意味着最后一刀的位置不同，划分方案必不相同，直接累加
                curCnt[v] = (unsigned int)((curCnt[v] + c) % mod);
            }
        }

        // 把「恰为 v」抹成「<= v」的前缀最值，供 i 之后的位置查询
        int run = -1;
        unsigned int rc = 0;
        for (int v = 0; v < V; ++v) {
            if (curBest[v] > run) {
                run = curBest[v];
                rc = curCnt[v];
            } else if (curBest[v] == run && run >= 0) {
                rc = (unsigned int)((rc + curCnt[v]) % mod);
            }
            gBest[i][v] = (short)run;             // run = -1 表示 i 处任何上界都不可达
            gCnt[i][v] = (run >= 0 ? rc : 0u);
        }
    }

    // 整个数组都划分完了，最后一段异或值无上界限制，取 v = V-1 即全局最优
    cout << (int)gBest[n][V - 1] << " " << gCnt[n][V - 1] << "\n";
    return 0;
}
```

### 易错点

前缀最优的方案数仅累加达到最大段数的状态，不能把所有计数相加。模数可能为一，此时方案数全部为零，但可达性仍由段数判断。

## E. 异或和II

### 题意

支持单点修改。查询所有长度不超过 $k$ 的非空子序列，对每个求按位或，再把全部结果异或，输出最终值。

### 从零讲：部分二项式和的奇偶

本题只需要组合数前缀和的奇偶。由 Pascal 公式，$m>0$ 时

$$\sum_{j=0}^k\binom mj=\sum_{j=0}^k\left(\binom{m-1}j+\binom{m-1}{j-1}\right)\equiv\binom{m-1}k\pmod2.$$

中间项成对抵消，只留下最后一项。组合数 $\binom uv$ 为奇数，当且仅当 $v$ 是 $u$ 的二进制子掩码：模二下 $(1+x)^{2^b}=1+x^{2^b}$，将 $u$ 按二进制拆开，能选出的次数恰是其子掩码。

所以只需检查 $k\mathbin{\&}\sim(m-1)=0$。这把看似需大量组合数的求和压成几次位运算。

### 思路

各二进制位独立。记第 $b$ 位为零的元素数为 $z_b$，所有长度不超过 $k$ 的子序列数，减去完全从这 $z_b$ 个元素中选的数量，就是该位 OR 为一的次数。

定义 $S(m,k)=\sum_{j=0}^k\binom mj\bmod2$。两边都多算的空子序列相互抵消，答案第 $b$ 位为 $S(n,k)\oplus S(z_b,k)$。

基础小节给出常数时间判据。保留代码用等价位条件实现：$m>0$ 时，$k$ 在 $m$ 最低一位处必须为零，更高一位只能来自 $m$，更低位任意；这正是 $k$ 为 $m-1$ 子掩码。$m=0$ 时始终返回一。

维护各位一的数量，修改只调整旧值与新值不同的位。每次查询扫描三十位，时间 $O(30(n+q))$，空间 $O(n)$。

### 参考代码

```cpp
// 练习赛 153 E. 异或和II
//
// 按位独立。答案的第 b 位 = 「OR 在第 b 位为 1 的子序列个数」的奇偶。
//   · 记 z_b = 当前第 b 位为 0 的元素个数，则那个个数
//       = (Σ_{l=1..k} C(n,l)) - (Σ_{l=1..k} C(z_b,l))
//     （后半是「一个带第 b 位的元素都没选」的那些子序列）。
//   · 记 S(m,k) = Σ_{l=0..k} C(m,l) mod 2，上面两段各减掉的 "1" 在 mod 2 下互相抵消，
//     于是答案第 b 位 = S(n,k) 异或 S(z_b,k)。
//   · 由 Lucas 定理，C(m,l) 为奇数 ⇔ l 是 m 的子掩码，所以 S(m,k) 就是
//     「m 的子掩码里 ≤ k 的个数」的奇偶，有 O(1) 的位运算判据（见 parityS）。
//
// 复杂度：每次修改 O(30)（只动变化的那些位），每次询问 O(30)。
#include <bits/stdc++.h>
using namespace std;

static const int BITS = 30;  // a_i, y <= 1e9 < 2^30，只需看第 0..29 位

// 返回 S(m,k) = Σ_{l=0..k} C(m,l) 的奇偶（= m 的子掩码中 ≤ k 的个数 mod 2）。
// h = (k & ~m) 的最高位（k & ~m == 0 时视作 h = -1），B = 最小的严格大于 (k & ~m) 的 2 的幂：
//   S 为奇数 ⇔ m 的第 h 位及以下全为 0（即 m & (B-1) == 0），且 k 的「m 的最低位」那一位是 0。
static inline int parityS(int m, int k) {
    int r = k & ~m;  // k 为 1 而 m 为 0 的那些位
    // B = 2^(h+1)：r = 0 时 h = -1，B 取 1；否则取比 r 大的最小 2 的幂
    unsigned B = r ? (1u << (32 - __builtin_clz((unsigned)r))) : 1u;
    if (m & (int)(B - 1)) return 0;    // m 在第 h 位以下还有 1 → 贡献项成对出现，偶数个
    return (k & (m & -m)) == 0;        // m = 0 时 m & -m = 0，恒为奇数（S(0,k) = 1）
}

int main() {
    ios::sync_with_stdio(false);  // 关掉 cin 与 stdio 的同步，读入才够快
    cin.tie(nullptr);             // 读之前不必刷新 cout

    int T;
    if (!(cin >> T)) return 0;

    string out;  // 把所有答案攒成一个字符串，最后一次性输出
    out.reserve(1u << 20);

    while (T--) {
        int n, q;
        cin >> n >> q;

        vector<int> a(n + 1);     // 1 下标，方便 op = 1 的 x
        int cnt[BITS] = {0};      // cnt[b] = 当前有多少个元素第 b 位是 1

        for (int i = 1; i <= n; i++) {
            cin >> a[i];
            // 只枚举为 1 的位：v &= v-1 每次抹掉最低的 1
            for (int v = a[i]; v; v &= v - 1) cnt[__builtin_ctz(v)]++;
        }

        while (q--) {
            int op;
            cin >> op;
            if (op == 1) {
                int x, y;
                cin >> x >> y;
                int old = a[x];
                // 只处理值真的变了的那几位
                for (int d = old ^ y; d; d &= d - 1) {
                    int b = __builtin_ctz(d);
                    if ((old >> b) & 1) cnt[b]--;  // old 有、y 没有 → 少一个
                    else cnt[b]++;                 // old 没有、y 有 → 多一个
                }
                a[x] = y;
            } else {
                int k;
                cin >> k;
                int gn = parityS(n, k);  // S(n,k) 与位无关，整个询问只算一次
                int ans = 0;
                for (int b = 0; b < BITS; b++) {
                    int z = n - cnt[b];                   // 第 b 位为 0 的元素个数
                    if (parityS(z, k) != gn) ans |= 1 << b;  // 两个奇偶不同 → 答案该位是 1
                }
                out += to_string(ans);
                out += '\n';
            }
        }
    }

    cout << out;
    return 0;
}
```

### 易错点

子序列按位置区分，相同数值也要按多个元素计数。$z_b=0$ 时不能套 $m-1$ 的非负掩码判据，需要单独返回一。

## F. 下棋

### 题意

黑方得分为被黑子隔绝于边界的白子数，白方对称；空格与对手棋子可四向连通，双方同时计分且不实际提子。输出初态及每次改单格后的胜负。

### 从零讲：线段树分治 + 可撤销并查集

一条动态边在时间区间 $[l,r]$ 内有效，把它放入时间线段树中覆盖该区间的若干节点。遍历线段树时，进入节点就加入这些边；到叶子时，沿途加入的恰好是该时刻全部有效边。

离开节点后，需撤销本层合并，恢复进入前状态。可撤销并查集用栈保存父指针、分量大小、权和与全局答案的旧值，按大小合并，避免路径压缩造成大量隐式改动。

一次进入时记住历史栈长度，退出时回滚到这个长度。这样不同时间分支互不干扰，同时共用整段时间都存在的边。

### 思路

固定颜色 $c$，只保留不等于 $c$ 的格子，敌子权为一、空格权为零。把边界上的保留格连接虚拟外界，所有不连外界分量的总权就是得分。

![围住的白子所在区域不连外界](assets/f-border.svg)

离线把每格颜色随时间切成若干不变段，每段作为一个独立顶点。相邻格子的段用双指针求交，在双方都可通行的交集时间加入边；边界段也在对应时间连外界。

用基础小节的时间线段树和可撤销并查集处理全部有效边。并查集记录分量敌子权和、是否连外界，并维护不连外界分量的权和 $C$。非当前时间的敌子段顶点虽孤立，却仍被计入 $C$，所以时刻 $t$ 的得分为 $C-(W-W_t)$，其中 $W$ 为全部敌子段数量、$W_t$ 为当前棋盘敌子数量。

两端从未改变的边可预先永久合并，其余动态边区间总量为 $O(q)$。两种颜色分别计算再比较。设运行段总数为 $U=O(nm+q)$，按大小合并且不路径压缩时，保守时间界为 $O((nm+q\log q)\log U)$，空间 $O(nm+q\log q)$。

### 参考代码

```cpp
// 牛客练习赛 153 F. 下棋
//
// 得分定义：黑方得分 = 被黑棋「完全围住」的区域里的白子数；
// 把「非黑格」（0 和 2）按四连通分块，某块里一个边界格都没有 => 被黑棋围住。
// 白方对称。
//
// 每次操作只改一个格子的值，但一个点的改动可能让一大片区域「被围住 / 被放出来」，
// 所以在线维护连通性做不了，改用**离线**：
//   · 对每种颜色 c 各建一张图 G_c（顶点 = 值不等于 c 的格子 + 一个「外界」虚拟点）；
//   · 答案 = 每个不含外界的连通块里「值为 3-c 的格子数」之和；
//   · 把每个格子的值随时间的分段（运行段）当作独立顶点，
//     相邻两格的边只在两段都「不属于颜色 c」的时间交集内存在 —— 每条边都是一段存活区间；
//   · 线段树分治时间轴 + 可撤销并查集（按大小合并，不路径压缩）扫一遍，
//     在每个叶子（时刻）读出当前总分。
// 「运行段」顶点在它存活区间之外是孤立点，但权值仍会被计入，
// 所以最后统一减去「此刻已经死掉的敌子段」个数即可（它们必然孤立、不接外界）。
#include <bits/stdc++.h>
using namespace std;

static int n, m, q, nm;
static vector<unsigned char> val0;      // 初始棋盘：0 空 / 1 黑 / 2 白
static vector<int> qcell, qval;         // 每次操作：格子下标、目标值

static vector<int> chCnt, chBase;       // 每格「值真的变了」的次数 / CSR 前缀
static vector<int> chTime;              // 事件时刻 1..q
static vector<unsigned char> chVal;     // 事件之后的值

static vector<int> cellBase;            // 每格第一个运行段的下标（运行段连续存放）
static vector<int> runBeg, runEnd;      // 运行段覆盖的时刻区间 [beg, end]
static vector<unsigned char> runVal;    // 运行段的值
static int totalRuns;                   // 运行段总数 = 顶点数（不含外界）

// ---------------------------------------------------------------- 可撤销并查集
struct RollbackDSU {
    vector<int> par, sz, w;
    vector<unsigned char> conn;         // 该分量是否与「外界」相连
    vector<int> kid, dad;               // 撤销栈：被挂上去的根、挂到的根
    vector<unsigned char> connOld;
    vector<long long> curOld;
    long long cur = 0;                  // 当前所有「不含外界的分量」的权值和

    void init(int N) {
        par.resize(N);
        sz.assign(N, 1);
        w.assign(N, 0);
        conn.assign(N, 0);
        for (int i = 0; i < N; ++i) par[i] = i;
    }
    int find(int x) const {
        while (par[x] != x) x = par[x];
        return x;
    }
    void unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (sz[ra] < sz[rb]) swap(ra, rb);
        kid.push_back(rb); dad.push_back(ra);
        connOld.push_back(conn[ra]); curOld.push_back(cur);
        if (!conn[ra]) cur -= w[ra];
        if (!conn[rb]) cur -= w[rb];
        par[rb] = ra;
        sz[ra] += sz[rb];
        w[ra] += w[rb];
        conn[ra] = (unsigned char)(conn[ra] | conn[rb]);
        if (!conn[ra]) cur += w[ra];
    }
    size_t mark() const { return kid.size(); }
    void rollback(size_t save) {
        while (kid.size() > save) {
            int c = kid.back(); kid.pop_back();
            int p = dad.back(); dad.pop_back();
            cur = curOld.back(); curOld.pop_back();
            conn[p] = connOld.back(); connOld.pop_back();
            par[c] = c;
            sz[p] -= sz[c];
            w[p] -= w[c];
        }
    }
};

// ---------------------------------------------------------------- 单色求解
// c        ：谁在围（1 黑 / 2 白）
// enemyCnt ：每个时刻「颜色 3-c 的格子数」
// score    ：输出每个时刻 c 的得分
static void solveColor(int c, const vector<int> &enemyCnt, vector<int> &score) {
    const int enemy = 3 - c;
    const int NN = totalRuns + 1;
    const int OUT = totalRuns;          // 外界虚拟点

    RollbackDSU dsu;
    dsu.init(NN);
    long long totalW = 0;               // 所有「敌子运行段」的个数（权值 1 的总数）
    for (int r = 0; r < totalRuns; ++r)
        if (runVal[r] == enemy) { dsu.w[r] = 1; ++totalW; }
    dsu.cur = totalW;                   // 初始每个点自成一个分量；外界点权值 0
    dsu.conn[OUT] = 1;

    // 1) 恒定边的静态合并：两端都「从未变过」的相邻格子，或从未变过的边界格连外界
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            int u = i * m + j;
            if (chCnt[u] || val0[u] == (unsigned char)c) continue;
            int nu = cellBase[u];       // 未变过的格子只有一个运行段
            if (j + 1 < m) {
                int v = u + 1;
                if (!chCnt[v] && val0[v] != (unsigned char)c) dsu.unite(nu, cellBase[v]);
            }
            if (i + 1 < n) {
                int v = u + m;
                if (!chCnt[v] && val0[v] != (unsigned char)c) dsu.unite(nu, cellBase[v]);
            }
            if (i == 0 || i == n - 1 || j == 0 || j == m - 1) dsu.unite(nu, OUT);
        }
    }

    // 2) 动态边：至少有一端变过的相邻格子 / 变过的边界格与外界之间
    vector<int> ea, eb, el, er;
    ea.reserve(1 << 16); eb.reserve(1 << 16); el.reserve(1 << 16); er.reserve(1 << 16);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            int u = i * m + j;
            int nc = chCnt[u];
            for (int dir = 0; dir < 2; ++dir) {     // 0: 右, 1: 下
                int v = -1;
                if (dir == 0) { if (j + 1 >= m) continue; v = u + 1; }
                else { if (i + 1 >= n) continue; v = u + m; }
                if (!chCnt[u] && !chCnt[v]) continue;
                int x = cellBase[u], xEnd = x + nc + 1;
                int y = cellBase[v], yEnd = y + chCnt[v] + 1;
                while (x < xEnd && y < yEnd) {      // 两串运行段求交
                    if (runVal[x] != (unsigned char)c && runVal[y] != (unsigned char)c) {
                        int l = max(runBeg[x], runBeg[y]);
                        int r = min(runEnd[x], runEnd[y]);
                        ea.push_back(x); eb.push_back(y); el.push_back(l); er.push_back(r);
                    }
                    if (runEnd[x] <= runEnd[y]) ++x; else ++y;
                }
            }
        }
    }
    // 变过的边界格：每个存活运行段都单独连一次外界
    for (int i = 0; i < n; ++i) {
        if (i != 0 && i != n - 1) continue;
        for (int j = 0; j < m; ++j) {
            int u = i * m + j;
            if (!chCnt[u]) continue;
            for (int k = cellBase[u], ke = cellBase[u] + chCnt[u] + 1; k < ke; ++k)
                if (runVal[k] != (unsigned char)c) {
                    ea.push_back(k); eb.push_back(OUT);
                    el.push_back(runBeg[k]); er.push_back(runEnd[k]);
                }
        }
    }
    for (int j = 0; j < m; ++j) {
        if (j != 0 && j != m - 1) continue;
        for (int i = 0; i < n; ++i) {
            int u = i * m + j;
            if (!chCnt[u]) continue;
            for (int k = cellBase[u], ke = cellBase[u] + chCnt[u] + 1; k < ke; ++k)
                if (runVal[k] != (unsigned char)c) {
                    ea.push_back(k); eb.push_back(OUT);
                    el.push_back(runBeg[k]); er.push_back(runEnd[k]);
                }
        }
    }

    // 3) 时间线段树：把每条边的存活区间塞进 O(log q) 个结点
    const int T = q + 1;                // 时刻 0..q
    int size = 1;
    while (size < T) size <<= 1;
    const int E = (int)ea.size();
    vector<int> cntNode(2 * size, 0);
    for (int e = 0; e < E; ++e) {
        int l = el[e] + size, r = er[e] + 1 + size;
        while (l < r) {
            if (l & 1) ++cntNode[l++];
            if (r & 1) ++cntNode[--r];
            l >>= 1; r >>= 1;
        }
    }
    vector<int> off(2 * size + 1, 0);
    for (int i = 0; i < 2 * size; ++i) off[i + 1] = off[i] + cntNode[i];
    vector<int> entries(off[2 * size]);
    {
        vector<int> ptr(off.begin(), off.end() - 1);
        for (int e = 0; e < E; ++e) {
            int l = el[e] + size, r = er[e] + 1 + size;
            while (l < r) {
                if (l & 1) { entries[ptr[l]++] = e; ++l; }
                if (r & 1) { --r; entries[ptr[r]++] = e; }
                l >>= 1; r >>= 1;
            }
        }
    }
    vector<int>().swap(el); vector<int>().swap(er);   // 区间端点已写进线段树，不再需要

    // 4) 深搜时间线段树，进一个结点合并、出结点回滚
    score.assign(T, 0);
    auto dfs = [&](auto &&self, int node) -> void {
        size_t save = dsu.mark();
        for (int e = off[node], ee = off[node + 1]; e < ee; ++e) {
            int id = entries[e];
            dsu.unite(ea[id], eb[id]);
        }
        if (node >= size) {
            int t = node - size;
            if (t <= q)
                score[t] = (int)(dsu.cur - (totalW - (long long)enemyCnt[t]));
        } else {
            self(self, node << 1);
            self(self, node << 1 | 1);
        }
        dsu.rollback(save);
    };
    dfs(dfs, 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m >> q;
    nm = n * m;
    val0.assign(nm, 0);
    {
        string s;
        for (int i = 0; i < n; ++i) {
            cin >> s;
            for (int j = 0; j < m; ++j) val0[i * m + j] = (unsigned char)(s[j] - '0');
        }
    }
    qcell.assign(q, 0); qval.assign(q, 0);
    for (int t = 0; t < q; ++t) {
        int x, y, c;
        cin >> x >> y >> c;
        qcell[t] = (x - 1) * m + (y - 1);
        qval[t] = c;
    }

    // 每个格子「值真的变了」的事件（改成同值不算事件）
    chCnt.assign(nm, 0);
    {
        vector<unsigned char> cur(val0);
        for (int t = 0; t < q; ++t) {
            int u = qcell[t];
            if (cur[u] != (unsigned char)qval[t]) { ++chCnt[u]; cur[u] = (unsigned char)qval[t]; }
        }
    }
    chBase.assign(nm + 1, 0);
    for (int u = 0; u < nm; ++u) chBase[u + 1] = chBase[u] + chCnt[u];
    chTime.assign(chBase[nm], 0); chVal.assign(chBase[nm], 0);
    {
        vector<int> pos(chBase.begin(), chBase.end() - 1);
        vector<unsigned char> cur(val0);
        for (int t = 1; t <= q; ++t) {
            int u = qcell[t - 1];
            unsigned char nv = (unsigned char)qval[t - 1];
            if (cur[u] != nv) {
                int p = pos[u]++;
                chTime[p] = t; chVal[p] = nv; cur[u] = nv;
            }
        }
    }

    // 运行段：把每个格子的值按时间切成若干段
    cellBase.assign(nm + 1, 0);
    for (int u = 0; u < nm; ++u) cellBase[u + 1] = cellBase[u] + chCnt[u] + 1;
    totalRuns = cellBase[nm];
    runBeg.assign(totalRuns, 0); runEnd.assign(totalRuns, 0); runVal.assign(totalRuns, 0);
    for (int u = 0; u < nm; ++u) {
        int nb = chBase[u], nc = chCnt[u], b = cellBase[u];
        for (int k = 0; k <= nc; ++k) {
            runBeg[b + k] = (k == 0) ? 0 : chTime[nb + k - 1];
            runEnd[b + k] = (k == nc) ? q : chTime[nb + k] - 1;
            runVal[b + k] = (k == 0) ? val0[u] : chVal[nb + k - 1];
        }
    }

    // 每个时刻的黑子数、白子数
    vector<int> c1(q + 1, 0), c2(q + 1, 0);
    {
        int a = 0, b = 0;
        for (int u = 0; u < nm; ++u) {
            if (val0[u] == 1) ++a; else if (val0[u] == 2) ++b;
        }
        c1[0] = a; c2[0] = b;
        vector<unsigned char> cur(val0);
        for (int t = 1; t <= q; ++t) {
            int u = qcell[t - 1];
            unsigned char nv = (unsigned char)qval[t - 1];
            if (cur[u] != nv) {
                if (cur[u] == 1) --a; else if (cur[u] == 2) --b;
                if (nv == 1) ++a; else if (nv == 2) ++b;
                cur[u] = nv;
            }
            c1[t] = a; c2[t] = b;
        }
    }

    vector<int> scoreBlack, scoreWhite;
    solveColor(1, c2, scoreBlack);
    solveColor(2, c1, scoreWhite);

    string out;
    out.reserve((size_t)(q + 1) * 8);
    for (int t = 0; t <= q; ++t) {
        if (scoreBlack[t] > scoreWhite[t]) out += "Black\n";
        else if (scoreWhite[t] > scoreBlack[t]) out += "White\n";
        else out += "Draw\n";
    }
    fwrite(out.data(), 1, out.size(), stdout);
    return 0;
}
```

### 易错点

黑方和白方使用不同可通行图，提子不改变另一方的判定。必须减掉非当前时间的孤立敌子段，否则同一格历史上出现过的棋子会重复计分。

## A. Mizuki and Multiset

### 题意

从单个正整数 $n$ 开始，可把一个数拆成和相同、最大公约数大于一的两个正整数，求最终最多元素数。

### 思路

任何拆出的数都至少为二，且总和不变，所以偶数上界为 $n/2$，奇数上界为 $(n-1)/2$。一和质数无法拆分，答案为一。

偶数可反复拆出二，达到上界。奇合数若被三整除，先拆成三与剩余偶数，再把偶数拆成二。否则取最小质因子 $p\ge5$，先拆成 $3p$ 与 $n-3p$：两者都被 $p$ 整除，且因 $n/p\ge p\ge5$，后者为正偶数。前者再拆成三和偶数，最终仍只有一个三，其余全为二，达到奇数上界。

用试除判断奇数是否合数，时间 $O(\sqrt n)$，空间 $O(1)$。

### 参考代码

```cpp
// 练习赛 154 A. Mizuki and Multiset
// 结论：n 为偶数 → n/2；n 为奇数质数（含 n=1）→ 1；n 为奇数合数 → (n-1)/2。
#include <bits/stdc++.h>
using namespace std;

// 试除法判断质数：只需试到 sqrt(x)
bool isPrime(long long x) {
    if (x < 2) return false;                     // 0 和 1 都不是质数
    for (long long d = 2; d * d <= x; ++d) {     // d 从 2 一路试到 sqrt(x)
        if (x % d == 0) return false;            // 找到因子，说明 x 是合数
    }
    return true;                                 // 一个因子都没找到，x 是质数
}

int main() {
    ios::sync_with_stdio(false);                 // 关掉 cin/cout 与 stdio 的同步，加速读入
    cin.tie(nullptr);                            // 解除 cin 与 cout 的绑定
    int T;
    cin >> T;                                    // 数据组数
    while (T--) {
        long long n;
        cin >> n;                                // 当前这组给定的 n
        long long ans;
        if (n == 1) {
            ans = 1;                             // 1 拆不动，只剩它自己
        } else if (n % 2 == 0) {
            ans = n / 2;                         // 偶数：全拆成 n/2 个 2，这同时是上界
        } else if (isPrime(n)) {
            ans = 1;                             // 奇质数：一次都拆不了
        } else {
            ans = (n - 1) / 2;                   // 奇合数：留下一个 3，其余全是 2
        }
        cout << ans << '\n';                     // 输出该组答案
    }
    return 0;
}
```

### 易错点

一既不是质数也不是合数，但不能拆，单独处理。拆成的两数必须为正，构造 $3p$ 时需要上述最小质因子保证。

## B. Mizuki and Mex

### 题意

可重集中值 $i$ 有 $a_i$ 份。每次将一个非空子多重集换成其 mex，最终只剩一个数，求最大可能值。

### 从零讲：把整场操作看成一棵树

一次操作消耗多个元素并产生一个，可画成一个父节点及它的孩子。最终仅剩一数时，全部操作形成一棵树，叶子是初始元素。

要让父节点 mex 为 $v$，它的孩子至少含零至 $v-1$ 各一个，且不能含 $v$。每个必须孩子要么用原始现货，要么再展开成一棵更小的构造树。

若没有可用高值现货，造二要两片叶子，造三要四片，造四要八片。高值现货能直接替代整棵子树，这解释了为何不能只看元素总数，也说明从高值向低值统计需求能同时处理所有展开。

### 思路

设元素总数为 $N$，尝试构造终值 $v\ge2$。由操作树，自高到低处理所需值 $j=v-1,\ldots,2$，维护已新增构造节点数 $c$；当前值共需 $1+c$ 份。

尽量拿现成的 $a_j$ 填充需求，这些各消耗一个原始元素；不足部分必须再构造，每造一个 $j$，就给之后每个更低值多添一份需求，所以把不足数加到 $c$。最后零、一各需 $1+c$ 个原始元素，任意未使用元素都能经单元素 mex 变成零或一。

累加所有现成高值叶子及最后两类叶子，得最低需求 $L$。若 $L\le N$，剩余元素先变成零，附加在根操作中，根的 mex 不变；否则无解。直接使用现货不比重新生成差：它只用一片叶子，而展开会要求多个更低孩子，反而占用更多资源。

需求随 $v$ 增加不减，可二分。超过输入最高值后的层会让需求翻倍，因此上界取 $n+62$ 足够。需求一旦超过 $N$ 就提前终止。若 $N=1$，保留唯一元素，或把零变成一，单独回答。时间 $O((n+\log N)\log(n+\log N))$，空间 $O(n)$。

### 参考代码

```cpp
// 牛客练习赛 154 B. Mizuki and Mex
// 做法：把整串操作看成一棵树（根 = 最后剩下的元素，叶子 = 最初的 token），
//       于是「能不能造出 v」= 从高到低贪心数一共要多少个 token；
//       需求随层数翻倍，答案最多到 n+62，直接二分。
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int n;              // 可重集里最大初值的下标（初值只到 n）
vector<ll> a;       // a[i] = 初值 i 的个数
ll N;               // token 总数（= 所有 a[i] 之和）

// 判定：能不能让最后剩下的那个元素恰好是 v
bool ok(ll v) {
    ll cum = 0;     // 比当前槽更高的那些层里「需要现场造」的总次数
    // 第一段：层号 j 落在 (n, v-1] 且 j >= 2 —— 手里没有现货，只能现场造，
    //         每造一层都要 1 个，而且下面每一层的需求都跟着 +1（翻倍）
    for (ll j = v - 1; j > n && j >= 2; --j) {
        cum = 2 * cum + 1;          // 这一层的需求量是 1+cum，全部现场造
        if (cum > N) return false;  // 已经超过全部 token，不可能
    }
    ll used = 0;                    // 用现货 token 顶掉的叶子数
    // 第二段：层号 j 落在 [2, min(n, v-1)] —— 有现货就优先用现货顶
    for (ll j = min(v - 1, (ll)n); j >= 2; --j) {
        ll need = 1 + cum;          // 这一层一共需要多少个值 j
        ll use = min(need, a[j]);   // 拿现货顶掉一部分
        used += use;                // 顶掉的部分就是叶子
        cum += need - use;          // 顶不掉的部分现场造，低层需求再加这么多
        if (used > N || cum > N) return false;
    }
    // 最后记得两个低槽：槽 0 和槽 1 只能用 token 顶（任何 token 都能变成 0 或 1）
    return used + 2 * (1 + cum) <= N;
}

int main() {
    ios::sync_with_stdio(false);    // 关掉 cin/cout 与 stdio 的同步，加速
    cin.tie(nullptr);               // 解绑 cin 与 cout
    int T;
    cin >> T;                       // 数据组数
    while (T--) {
        cin >> n;
        a.assign(n + 1, 0);
        N = 0;
        for (int i = 0; i <= n; ++i) {
            cin >> a[i];
            N += a[i];              // 顺手统计 token 总数
        }
        if (N == 1) {               // 特判：原样就是一个单元素集，不出手就是答案
            ll ans = 1;             // 唯一的 token 是 0 的话，做一次操作能变成 1
            for (int i = 0; i <= n; ++i)
                if (a[i]) ans = max((ll)i, 1LL);
            cout << ans << '\n';
            continue;
        }
        // 二分：N >= 2 时 v = 2 一定可行；v >= n+63 时上面纯造的层数已有 62 层，
        //       需求 2^62-1 远超 token 总数，一定不可行，所以上界取 n+62
        ll lo = 2, hi = n + 62;
        while (lo < hi) {
            ll mid = (lo + hi + 1) / 2;
            if (ok(mid)) lo = mid;  // 可行就把下界抬上来
            else hi = mid - 1;      // 不可行就把上界压下去
        }
        cout << lo << '\n';
    }
    return 0;
}
```

### 易错点

总叶子数既包括直接使用的高值现货，也包括最后零、一两类需求。单个高值可以零操作保留，不能套必须从零一向上构造的判定。

## C. Mizuki and (Mod M)

### 题意

每轮将每个数字字符 $c$ 替换成固定串 $P_c$，重复 $K$ 轮后，求最终十进制数模 $M$ 的值。

### 从零讲：串的 (值, 10 的长度次幂) 二元组

十进制拼接 AB 的数值为 $\operatorname{value}(A)10^{|B|}+\operatorname{value}(B)$。所以一段字符串可用 $(v,p)$ 表示，分别记录数值模 $M$ 与 $10^{\text{长度}}\bmod M$。

拼接公式为 $(v_1,p_1)\circ(v_2,p_2)=(v_1p_2+v_2,p_1p_2)$，两项均取模；空串为 $(0,1)$。例如十二与三十四拼接，计算 $12\cdot100+34$。结合律来自真实拼接的结合律，因此无需展开字符串，也能逐段合成。

### 思路

维护每个数字展开若干轮后的二元组。零轮时，数字 $c$ 的值为 $c\bmod M$，长度幂为 $10\bmod M$。

新一轮中，按替换串 $P_c$ 的字符顺序，拼接各字符旧轮的二元组。十个数字全部算进临时数组后再替换旧状态，确保同轮不会串用新结果。最后将原串各字符的第 $K$ 轮结果拼接，输出数值部分。

每轮处理十个替换串，总时间 $O(K\sum_c|P_c|+|S|)$，额外状态只有十个二元组。

### 参考代码

```cpp
// 牛客练习赛 154 C. Mizuki and (Mod M)
//
// 关键抽象：把一段数字串压成二元组 (v, p)
//   v = 这段串当成十进制数的值 mod M
//   p = 10^{这段串的长度} mod M
// 拼接（左串接右串）满足：(v1,p1) ∘ (v2,p2) = (v1*p2 + v2 mod M, p1*p2 mod M)
// 于是「串有多长」永远不用真的算出来，也不会碰到「长度对谁取模」的坑。
//
// 设 f_k(c) = 单个数字字符 c 连续做 k 次操作后展开出的串。
//   f_0(c) = c
//   f_{k+1}(c) = f_k(P_c[0]) 接 f_k(P_c[1]) 接 ...   （即把 P_c 的每个数字各展开 k 次再接起来）
// 答案为把 S 的每个字符换成 f_K(c) 后整串的值 mod M。
// 每一轮只需对 10 个数字各扫一遍它对应的 P，共 O(Σ|P_i|)，总共 O(K·Σ|P_i| + |S|)。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        string S;
        long long K, M;
        cin >> S >> K >> M;
        vector<string> P(10);
        for (int d = 0; d < 10; ++d) cin >> P[d];

        // 当前映射：数字 d 展开出的串的 (值, 10^长度)，初始（还没做操作）就是它自己
        long long val[10], pw[10];
        for (int d = 0; d < 10; ++d) {
            val[d] = d % M;         // 单个数字的值
            pw[d] = 10 % M;         // 长度为 1，10^1 mod M
        }

        long long nval[10], npw[10];
        for (long long step = 0; step < K; ++step) {
            // 用「旧的」映射整体推出「新的」映射，10 个数字一起更新完再替换
            for (int d = 0; d < 10; ++d) {
                long long v = 0, p = 1 % M;             // 空串作为拼接单位元
                for (char ch : P[d]) {
                    int x = ch - '0';
                    v = (v * pw[x] + val[x]) % M;        // 把 x 的展开串接到当前串右边
                    p = p * pw[x] % M;                   // 长度相加 => 幂相乘
                }
                nval[d] = v;
                npw[d] = p;
            }
            for (int d = 0; d < 10; ++d) {               // 整轮结束后统一替换
                val[d] = nval[d];
                pw[d] = npw[d];
            }
        }

        // 最后把 S 的每个字符换成它展开后的串，逐段拼接
        long long ans = 0;
        for (char ch : S) {
            int x = ch - '0';
            ans = (ans * pw[x] + val[x]) % M;
        }
        cout << ans << '\n';
    }
    return 0;
}
```

### 易错点

展开后的真实长度可能极大，只保存十的长度次幂模数。$K=0$ 时直接处理原串，$M=1$ 时所有模值为零。

## D. Mizuki and (Mod 4)

### 题意

每次删除当前串中一个能被四整除的非空连续数字串，两侧自动拼接，判断能否最终删空。

### 从零讲：把「删空」拆成「最后一块 + 若干空隙」

看整段被清空前的最后一次删除。它删除的字符在原串中可能并不相邻，它们之间的空隙已经先被删空；最后保留字符拼成的数必须被四整除。

最后一块只有末两位决定整除性，前面的保留字符可以随意加入。因此一旦找到能拼接的合法末两位，就能把更左侧全部字符一起删除；真正要递归检查的只是这两位之间的空隙。这是合法起点能够压成一个前缀边界的原因。

### 思路

一位可删字符为零、四、八；多位数只看末两位，末位为零四八时前位需偶数，末位为二六时前位需奇数，奇数末位不可能。

设 $D(a,b)$ 表示原子串可删空。按最终删除块的末尾分类：末位能单删且前缀可删；或存在 $j<b$ 与末位组成四的倍数，中间 $(j,b)$ 可删，而 $a$ 到 $j-1$ 的任意字符可直接作为最终块前缀吞掉。

![先删中间，剩余末两位可以拼成四的倍数](assets/d-delete.svg)

固定右端 $b$，所有长度至少二的合法起点形成前缀 $[1,K_b]$；此外若末字符可单删，还有孤立起点 $b$。这里 $K_b$ 专门不包含单字符孤点。配对删除天然允许任意更左起点；单删继承此前起点，若继承出额外孤点，则连续两个可单删字符本身就可配对，仍会填平前缀。

更新 $K_b$ 时，继承可单删情况下的 $K_{b-1}$，再找最大的配对位置：相邻 $b-1$；中间单字符可删时的 $b-2$；以及不超过 $K_{b-1}-1$ 的最近合适奇偶数字。预处理奇偶数字的最近位置，三项均可常数时间查询。

最终 $K_n\ge1$ 或全串仅一位且能单删，就是可删空。时间、空间 $O(|S|)$。

### 参考代码

```cpp
// 牛客练习赛 154 D. Mizuki and (Mod 4)
// 正解：线性 DP，O(|S|)。推导见题解「思路」。
// 记 t[1..n] 为数字串。一次删除操作删掉的块 T：
//   |T| = 1 时要求 t = 0/4/8；|T| >= 2 时只要求 T 的最后两位拼成的数是 4 的倍数。
#include <bits/stdc++.h>
using namespace std;

// 单个字符能否作为「一位的 4 的倍数」被删掉
static inline bool singleOK(char c) { return c == '0' || c == '4' || c == '8'; }

// 以 c 结尾的两位数要好：10*x + c ≡ 0 (mod 4)，即 2*(x mod 2) + (c mod 4) ≡ 0。
// 返回它要求前一个字符 x 的奇偶：0 = 偶数，1 = 奇数，-1 = 无论 x 取什么都不行。
static inline int needParity(char c) {
    if (c == '0' || c == '4' || c == '8') return 0;  // c ≡ 0：要求 x 是偶数
    if (c == '2' || c == '6') return 1;              // c ≡ 2：要求 x 是奇数
    return -1;                                       // c 是奇数：任何两位数都凑不出 4 的倍数
}

int main() {
    ios::sync_with_stdio(false);                     // 数据量到 5e5 / 1e5 组，关同步加速
    cin.tie(nullptr);
    int T;
    if (!(cin >> T)) return 0;
    while (T--) {
        string s;
        cin >> s;
        int n = (int)s.size();

        // K[b] = 最大的起点 a，使得子串 t[a..b] 能被整段删空；不存在这样的 a 时 K[b] = 0。
        vector<int> K(n + 1, 0);
        // prevEven[i] / prevOdd[i] = 最大的 j <= i 且 t[j] 为偶数 / 奇数；没有则 0。
        vector<int> prevEven(n + 1, 0), prevOdd(n + 1, 0);
        for (int i = 1; i <= n; i++) {
            bool odd = ((s[i - 1] - '0') & 1) != 0;
            prevEven[i] = odd ? prevEven[i - 1] : i;
            prevOdd[i] = odd ? i : prevOdd[i - 1];
        }

        for (int b = 1; b <= n; b++) {                // b = 当前考虑的右端点（1 下标）
            int rp = needParity(s[b - 1]);            // 最后一块要在这里收尾，需要的奇偶
            int best = 0;                             // 能用的最大 j（最后一块倒数第二个字符的位置）
            if (rp >= 0) {
                // 情况 A：j = b-1，两个配对字符之间没有别的字符
                if (b >= 2 && (int)((s[b - 2] - '0') & 1) == rp) best = max(best, b - 1);
                // 情况 B：j = b-2，中间夹着的那一个字符自己就是 4 的倍数，可以单独删掉
                if (b >= 3 && singleOK(s[b - 2]) && (int)((s[b - 3] - '0') & 1) == rp)
                    best = max(best, b - 2);
                // 情况 C：j+1 <= K[b-1]，即 t[j+1..b-1] 本身能被整段删空
                int lim = K[b - 1] - 1;               // 需要 j <= lim
                if (lim >= 1) {
                    int j = (rp == 0) ? prevEven[lim] : prevOdd[lim];
                    if (j >= 1) best = max(best, j);
                }
            }
            // 情况 D：t[b] 自己就是 4 的倍数，把它作为最后一块（t[a..b-1] 整段先删空）
            K[b] = best;
            if (singleOK(s[b - 1])) K[b] = max(K[b], K[b - 1]);
        }

        // t[1..n] 可删空 <=> 1 是某段可删区间的起点；只有 n = 1 时例外（单字符自身）
        bool ok = (K[n] >= 1) || (n == 1 && singleOK(s[0]));
        cout << (ok ? "YES" : "NO") << "\n";
    }
    return 0;
}
```

### 易错点

不要将 $K_b$ 定义为全部合法起点的最大值，否则单字符孤点会被误当作整个合法前缀。前位奇偶条件由末位决定，不能只判断末位为偶数。

## E. Mizuki and Mismatch

### 题意

选择无固定点排列 $p$，最大化 $\sum_i\min(a_i,a_{p_i})$；持续单点修改数组，每次输出新的最大值。

### 从零讲：排列 = 若干轮换，一个轮换值多少只看「组内和、组内最大、组内最小」

无固定点排列分成若干长度至少二的轮换。对某一轮换，令组内最小、最大为 $m,M$。其收益等于组内总和减去沿环所有正向下降量，而从最大值最终回到最小值，下降量至少为 $M-m$。

按值单调排列成环，只有跨回最小值时产生总下降 $M-m$，达到上界。因此一组最优收益为组内总和减极差。不同轮换独立，整个排列优化便化为把元素分组，最小化各组极差之和。

### 思路

由基础小节，答案为总和减去分组极差之和的最小值，每组至少两个元素。将值排序为 $b$，间隔 $d_i=b_{i+1}-b_i$。

任意分组的每组极差，都等于它跨过的排序间隔之和。把没有任何组跨过的间隔记为切点集合 $T$；首尾间隔不能被切，相邻两个间隔也不能都切，否则中间元素只能单独成组。原代价至少为 $b_n-b_1-\sum_{i\in T}d_i$；直接按这些切点分成连续组，恰好达到此值。因此只需最大化内部非相邻间隔之和 $W$。

![合法切点之间至少保留两个元素](assets/e-gaps.svg)

修改会改变元素的排序位置，用键为 $(a_i,i)$ 的 Treap 维护有序序列。每个子树维护四种状态：左右外部间隔是否已经切开，记录内部可切间隔的最大权和。合并左子树、当前点、右子树时枚举两条连接间隔，不能同时切；叶子左右外部间隔同时切开的状态设为不可行，防止孤立单元素组。

整树两侧虚拟外部间隔都视作已切，恰好禁止真实首尾间隔被切，得到 $W$。答案为 $\sum a_i-(b_n-b_1)+W$。每次删除旧键、插入新键，期望时间 $O(\log n)$，空间 $O(n)$。

### 参考代码

```cpp
// 牛客练习赛 154 E. Mizuki and Mismatch
//
// 结论（推导见题解）：
//   ans = sum(a) - (max - min) + W
//   其中 W = 在「排序后相邻两个元素之间的 n-1 个间隔」上，切第 2..n-2 个间隔、
//   且任意两个被切的间隔不相邻时的最大权独立集（权 = 间隔长度）。
//
// 做法：把排序后的序列放进一棵 Treap（键 = (值, 下标)），每个子树维护一个
// 「内部间隔最大权独立集」的 4 状态 DP，于是单点改值（删一个元素 + 插一个元素）
// 只要 O(log n)。W = 根的 dp[1][1]（首尾两个间隔被外部标记成「已切」= 不许切）。
#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

static const int MAXN = 200005;      // 元素总数上限（Σn ≤ 2×10^5）
static const ll NEG = -(1LL << 60);  // 「不可行」状态

// ---------------- Treap 节点：一个节点 = 一个元素，中序遍历 = 排序后的序列 ----------------
int lc[MAXN], rc[MAXN];              // 左右儿子
int siz[MAXN];                       // 子树元素个数
int fst[MAXN], lst[MAXN];            // 子树中第一个（最小）/ 最后一个（最大）元素的值
int val[MAXN], idx[MAXN];            // 本元素的值、原下标（下标破除同值平局，保证键唯一）
unsigned pri[MAXN];                  // 随机优先级
ll dp[2][2][MAXN];                   // dp[a][b][u]：子树 u 所有「内部间隔」的最大权独立集，
                                     // a=1 表示 u 左边那个外部间隔被切、b=1 表示右边那个被切；
                                     // 只统计内部间隔的权，外部间隔的权由父节点负责加上

unsigned seed_ = 20261006u;          // Treap 的随机数种子（固定，便于复现）

unsigned rnd() {                     // xorshift32：生成随机优先级
    seed_ ^= seed_ << 13;
    seed_ ^= seed_ >> 17;
    seed_ ^= seed_ << 5;
    return seed_;
}

// ---------------- 维护子树信息 ----------------
void pull(int u) {
    int L = lc[u], R = rc[u];                          // 左右儿子
    siz[u] = 1 + siz[L] + siz[R];                      // 子树大小 = 1 + 两棵子树
    fst[u] = L ? fst[L] : val[u];                      // 最小值：有左儿子就取它，否则是自己
    lst[u] = R ? lst[R] : val[u];                      // 最大值：有右儿子就取它，否则是自己
    dp[0][0][u] = dp[0][1][u] = dp[1][0][u] = 0;       // 单元素：内部没有间隔，权为 0
    dp[1][1][u] = NEG;                                 // 但左右两个外部间隔若同时被切，
                                                       // 这个元素就自成一组（非法）→ 不可行
    if (L && R) {
        // 内部间隔有两段：wM 是 L 末元素 -> u 的间隔，wN 是 u -> R 首元素的间隔
        ll wM = (ll)val[u] - lst[L];
        ll wN = (ll)fst[R] - val[u];
        for (int x = 0; x < 2; ++x)                    // 枚举左外部间隔是否被切
            for (int y = 0; y < 2; ++y) {              // 枚举右外部间隔是否被切
                ll best = NEG;
                for (int s = 0; s < 2; ++s)            // s：wM 是否被切
                    for (int t = 0; t < 2; ++t) {      // t：wN 是否被切
                        if (s + t > 1) continue;       // wM、wN 相邻，不能同时切
                        ll c = dp[x][s][L]             // 左子树内部：左外部 x、右外部 s
                             + (s ? wM : 0)            // 切了 wM 就加上它的权
                             + (t ? wN : 0)            // 切了 wN 就加上它的权
                             + dp[t][y][R];            // 右子树内部：左外部 t、右外部 y
                        best = max(best, c);
                    }
                dp[x][y][u] = best;                    // 记下这个状态的最优值
            }
    } else if (L) {
        // 没有右儿子：u 是子树的最后一个元素，唯一的「边界间隔」wM 在 u 左边
        ll wM = (ll)val[u] - lst[L];                   // L 末元素 -> u 的间隔长度
        for (int x = 0; x < 2; ++x)
            for (int y = 0; y < 2; ++y) {
                ll best = NEG;
                for (int s = 0; s + y <= 1; ++s)       // y=1（u 右边那段被切）时 s 必须为 0
                    best = max(best, dp[x][s][L] + (s ? wM : 0));
                dp[x][y][u] = best;
            }
    } else if (R) {
        // 没有左儿子：u 是子树的第一个元素，边界间隔 wN 在 u 右边
        ll wN = (ll)fst[R] - val[u];                   // u -> R 首元素的间隔长度
        for (int x = 0; x < 2; ++x)
            for (int y = 0; y < 2; ++y) {
                ll best = NEG;
                for (int t = 0; t + x <= 1; ++t)       // x=1（u 左边那段被切）时 t 必须为 0
                    best = max(best, (t ? wN : 0) + dp[t][y][R]);
                dp[x][y][u] = best;
            }
    }
}

// ---------------- 按 (值, 下标) 分裂：A 得键更小的部分，B 得其余 ----------------
void split(int u, int kv, int ki, int &A, int &B) {
    if (!u) { A = B = 0; return; }                     // 空树直接分完
    if (val[u] < kv || (val[u] == kv && idx[u] < ki)) { // u 属于左边
        split(rc[u], kv, ki, rc[u], B);                // 把 u 的右子树继续分
        A = u;                                         // u 归左边
    } else {                                           // u 属于右边
        split(lc[u], kv, ki, A, lc[u]);                // 把 u 的左子树继续分
        B = u;                                         // u 归右边
    }
    pull(u);                                           // 分完重算 u 的子树信息
}

// ---------------- 按优先级合并两棵树（要求 A 的键全部小于 B 的键） ----------------
int mergeTreap(int A, int B) {
    if (!A || !B) return A ? A : B;                    // 有一边为空就直接接上
    if (pri[A] > pri[B]) {                             // A 当根
        rc[A] = mergeTreap(rc[A], B);                  // B 接进 A 的右子树
        pull(A);
        return A;
    }
    lc[B] = mergeTreap(A, lc[B]);                      // B 当根，A 接进 B 的左子树
    pull(B);
    return B;
}

// ---------------- 把节点 u 重置成一个「值为 v、下标为 i」的新叶子 ----------------
void initNode(int u, int v, int i) {
    val[u] = v;                                        // 元素的值
    idx[u] = i;                                        // 元素的原下标（键的第二关键字）
    lc[u] = rc[u] = 0;                                 // 从树上摘下来之后是孤立叶子
    pri[u] = rnd();                                    // 重新抽一个随机优先级
    pull(u);                                           // 叶子信息：siz=1、fst=lst=v、dp 见 pull
}

int main() {
    ios::sync_with_stdio(false);                       // 关掉 cin/cout 与 stdio 的同步
    cin.tie(nullptr);                                  // 解除 cin 与 cout 的绑定，加速
    int T;
    cin >> T;                                          // 数据组数
    while (T--) {
        int n, q;
        cin >> n >> q;                                 // 序列长度、修改次数
        vector<int> a(n + 1);                          // a[1..n]：当前序列
        ll sum = 0;                                    // 当前序列的元素和
        for (int i = 1; i <= n; ++i) {
            cin >> a[i];
            sum += a[i];                               // 累加元素和
        }
        vector<int> ord(n);                            // 元素下标 1..n
        iota(ord.begin(), ord.end(), 1);
        sort(ord.begin(), ord.end(), [&](int p, int r) {   // 按 (值, 下标) 排好插入顺序：
            return a[p] != a[r] ? a[p] < a[r] : p < r;     // merge 要求左边键全小于右边
        });
        int root = 0;                                  // Treap 根
        for (int i : ord) {                            // 按键递增的顺序插入 → 建出合法的 Treap
            initNode(i, a[i], i);                      // 元素 i 固定使用节点 i
            root = mergeTreap(root, i);
        }
        // 输出初始答案：sum - max + min + W，W = 根的 dp[1][1]（首尾两个间隔都不许切）
        cout << (sum - lst[root] + fst[root] + dp[1][1][root]);
        for (int t = 0; t < q; ++t) {
            int x, y;
            cin >> x >> y;                             // 把 a[x] 改成 y
            sum += (ll)y - a[x];                       // 先更新元素和
            int A, B, M, C;                            // 删掉键为 (a[x], x) 的旧节点
            split(root, a[x], x, A, B);                // A：键更小；B：键 ≥ (a[x], x)
            split(B, a[x], x + 1, M, C);               // M：恰好是键 (a[x], x) 那个单节点
            root = mergeTreap(A, C);                   // 旧节点摘掉（M 与节点 x 是同一个）
            a[x] = y;                                  // 更新数组里的值
            initNode(x, y, x);                         // 把节点 x 重置成新值
            split(root, y, x, A, B);                   // 按新键找插入位置
            root = mergeTreap(mergeTreap(A, x), B);    // 插回去
            cout << ' ' << (sum - lst[root] + fst[root] + dp[1][1][root]);  // 本次答案
        }
        cout << '\n';                                  // 每组数据一行
    }
    return 0;
}
```

### 易错点

重复数值用原下标区分键。外部间隔状态只传递是否切开，其权值由连接处计入，不能在两边重复加。

## F. Mizuki and Mirror

### 题意

每个字母至多有一个镜面字母，允许自镜面。通过相邻交换，把字符串变成对应对称位置互为镜面的串，求最少交换数。

### 从零讲：最少相邻交换次数 = 逆序对数

目标串固定后，将重复字母按出现先后稳定匹配到目标同字母位置，得到一个目标下标序列。相邻交换每次只能改变一个逆序对；消掉全部逆序对后次序正确，所以最少次数等于逆序对数。

例如某个搭档要去当前最右位置，它必须越过右侧每个仍活跃字符，各花一次交换，这个数量可用树状数组的后缀计数查询。由外向内摘除已定字符，就把全局逆序对计数拆成一层层可计算的必要跨越。

### 思路

先检查数量：所有出现字母都有镜面；不同字母互镜面时，两者次数必须相等；自镜面字母的奇数次数种类数必须等于串长奇偶。否则无解。

由外向内构造。取剩余串最左字符 $x$，配上最靠右的镜面字符，把这对放在当前最外层；所需代价就是搭档右侧仍剩多少字符。存在这样安排的最优解：把最左字符所在对与外层对交换，不增加必须跨越的字符对；同字母搭档优先取最右出现，与稳定匹配一致。

若最左字符没有另一份搭档，它必是唯一的自镜面中位字符。将它与右邻交换一步，继续处理新队首，让中位字符逐层向中间移动。

用链表维护剩余次序，各字母栈找最右未删除位置，树状数组统计搭档右边的活跃字符数。时间 $O(n\log n)$，空间 $O(n)$。

### 参考代码

```cpp
// 牛客练习赛 154 F. Mizuki and Mirror
//
// 做法：可行性判定 + 从外向内逐层配对（链表 + 树状数组），O(n log n)
//
// 1) 镜面关系是对合：把字母按「互为镜面」分成若干连通块 —— 单点块 {c}（mir[c]=c）
//    和二元块 {p,q}（mir[p]=q）。镜面回文串的一对对称位置 (i, n-1-i)：
//      · 单点块里只能放 (c,c)；
//      · 二元块里只能放 (p,q) 或 (q,p)，即每对恰好用掉一个 p 和一个 q。
//    于是可行性：串里出现过的字母必须有镜面；二元块两侧出现次数必须相等；
//    自镜面字母里至多一个出现奇数次（n 为奇数时正好一个，它当中位字符）。
//
// 2) 相邻交换的最小次数 = 逆序对数。把目标串定下来后，同字母按「出现顺序一一对应」
//    做稳定匹配时逆序对最少；于是问题变成：选出使逆序对最少的目标镜面回文串。
//
// 3) 贪心：从最外圈往中间逐层决定。当前最左边的字符（记为 head）一定放在最外层左边
//    （它是原串里最靠前的元素，往左走不花代价；而它右边所有元素都要放在它右边或里面）。
//    于是只要把它该配的镜面字母里「最靠右的那个」挪到最外层右边，代价 = 它右边还剩下
//    多少个元素；两者一起从链表里摘掉。head 找不到搭档时，它只能当中位字符，
//    与右邻交换一格（代价 1）后继续——这正是经典「最少交换造回文」贪心的镜像版本。
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 200005;

int N;                        // 本组串长
int nxtPos[MAXN], prvPos[MAXN];   // 剩余元素的链表（按原串顺序）
bool alivePos[MAXN];              // 该位置是否还没被配对掉
int fen[MAXN + 2];                // 树状数组：统计还活着的位置个数

// 树状数组：位置 0..N-1 映射到下标 1..N
inline void fenAdd(int i, int v) {
    for (i++; i <= N; i += i & -i) fen[i] += v;
}
inline int fenSum(int i) {        // 统计 [0, i) 里还活着的位置个数
    int r = 0;
    for (; i > 0; i -= i & -i) r += fen[i];
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    if (!(cin >> T)) return 0;
    string s;
    vector<int> stk[26];          // 每个字母的剩余出现位置，从左往右存（栈顶 = 当前最靠右）
    while (T--) {
        int m;
        cin >> N >> m;
        int mir[26];
        fill(mir, mir + 26, -1);  // -1 表示这个字母没有镜面字符
        for (int i = 0; i < m; i++) {
            string p, q;
            cin >> p >> q;
            int a = p[0] - 'a', b = q[0] - 'a';
            mir[a] = b;           // 规则是对称的：p 的镜面是 q，q 的镜面是 p
            mir[b] = a;
        }
        cin >> s;

        // ---------- 第一步：数出现次数，判可行性 ----------
        int cnt[26] = {0};
        for (int i = 0; i < N; i++) cnt[s[i] - 'a']++;
        bool ok = true;
        int oddSelf = 0;              // 出现奇数次的「自镜面」字母个数
        // 二元块两侧个数必须相等 —— 这跟串里有没有出现这个字母无关：只出现一侧也配不成对
        for (int c = 0; c < 26; c++)
            if (mir[c] > c && cnt[c] != cnt[mir[c]]) ok = false;
        for (int c = 0; c < 26; c++) {
            if (cnt[c] == 0) continue;
            if (mir[c] < 0) {         // 串里有没镜面的字母：永远配不出
                ok = false;
            } else if (mir[c] == c) {
                if (cnt[c] & 1) oddSelf++;
            }
        }
        if (N % 2 == 0) {             // 偶数长度没有中位字符
            if (oddSelf != 0) ok = false;
        } else {                      // 奇数长度恰好要一个自镜面字母出现奇数次
            if (oddSelf != 1) ok = false;
        }
        if (!ok) {
            cout << -1 << '\n';
            continue;
        }

        // ---------- 第二步：建链表、栈、树状数组 ----------
        for (int i = 0; i < N; i++) {
            nxtPos[i] = (i + 1 < N) ? i + 1 : -1;
            prvPos[i] = i - 1;
            alivePos[i] = true;
        }
        for (int i = 1; i <= N; i++) fen[i] = i & (-i);   // 全 1 数组的树状数组
        for (int c = 0; c < 26; c++) stk[c].clear();
        for (int i = 0; i < N; i++) stk[s[i] - 'a'].push_back(i);   // 从左往右压，栈顶 = 最靠右

        // ---------- 第三步：从外向内贪心配对 ----------
        long long ans = 0;
        int rest = N, head = 0;       // rest = 还没处理的元素个数，head = 最左的存活位置
        while (rest > 1) {
            int d = mir[s[head] - 'a'];               // head 需要的搭档字母
            while (!stk[d].empty() && !alivePos[stk[d].back()]) stk[d].pop_back();
            int r = stk[d].empty() ? -1 : stk[d].back();   // 最靠右的搭档
            if (r != -1 && r != head) {
                // head 放最外层左边，r 放最外层右边：代价 = r 右边还活着的元素个数
                ans += (long long)(fenSum(N) - fenSum(r + 1));
                stk[d].pop_back();
                // 先摘掉 r（这样 head 的后继会自动跳过 r）
                alivePos[r] = false;
                fenAdd(r, -1);
                if (prvPos[r] >= 0) nxtPos[prvPos[r]] = nxtPos[r];
                if (nxtPos[r] >= 0) prvPos[nxtPos[r]] = prvPos[r];
                int nh = nxtPos[head];                // 新的最左存活位置
                alivePos[head] = false;
                fenAdd(head, -1);
                if (prvPos[head] >= 0) nxtPos[prvPos[head]] = nxtPos[head];
                if (nxtPos[head] >= 0) prvPos[nxtPos[head]] = prvPos[head];
                head = nh;
                rest -= 2;
            } else {
                // head 这个字母只剩它自己了 —— 它只能当中位字符，往右挪一格（代价 1）
                ans += 1;
                int t = nxtPos[head], u = nxtPos[t];
                nxtPos[t] = head;
                prvPos[t] = -1;
                prvPos[head] = t;
                nxtPos[head] = u;
                if (u >= 0) prvPos[u] = head;
                head = t;
            }
        }
        cout << ans << '\n';
    }
    return 0;
}
```

### 易错点

镜面规则中某侧没有出现时，也要检查两侧数量相等。自镜面且仅剩一份时不能拿自己配自己，只能放中间。

## A. 出题灵感：异或最大值

### 题意

日期按无闰年日历计算，求起始日期至 2026 年一月九日之间，使年月日编码的各十进制位异或最大的日期。

### 思路

所有询问右端相同，可以预处理整个日历的后缀最优日期。从第一年一月一日到终点只有 $2025\cdot365+9=739134$ 天，逐日算数位异或，再从后往前维护较优日期。

查询起点的零基天数为 $(a-1)365+\text{此前月份天数}+c-1$，直接查对应后缀答案。并列任取日期即可。预处理时间、空间 $O(D)$，每次查询 $O(1)$，其中 $D=739134$。

### 参考代码

```cpp
// A. 出题灵感：异或最大值
// 区间右端点固定（2026-1-9），且题面规定不讨论闰年（每年固定 365 天），
// 整张日历只有 739134 天 —— 一次性预处理「后缀最优」，每组询问 O(1) 查表。
#include <bits/stdc++.h>
using namespace std;

// 平年每个月的天数（下标 0 占位；2 月固定 28 天）
static const int MON[13] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
static const int MAX_YEAR = 2026;   // 年份上界
static const int END_MON = 1;       // 右端点的月份
static const int END_DAY = 9;       // 右端点的日期

// 灵感值：v 的十进制数位异或
static int digitXor(int v) {
    int r = 0;
    while (v > 0) { r ^= v % 10; v /= 10; }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // 1) 把整张日历摊平：第 i 天是 Y[i] 年 M[i] 月 D[i] 日
    vector<int> Y, M, D;
    for (int y = 1; y < MAX_YEAR; ++y)                       // 1 年 ~ 2025 年：整年 365 天
        for (int m = 1; m <= 12; ++m)
            for (int d = 1; d <= MON[m]; ++d) {
                Y.push_back(y); M.push_back(m); D.push_back(d);
            }
    for (int d = 1; d <= END_DAY; ++d) {                     // 2026 年只到 1 月 9 日
        Y.push_back(MAX_YEAR); M.push_back(END_MON); D.push_back(d);
    }
    const int n = (int)Y.size();                             // 739134

    // 2) 每天都按定义算灵感值：V = 10000x + 100y + z，取 V 的所有数位异或
    vector<int> sc(n);
    for (int i = 0; i < n; ++i) sc[i] = digitXor(10000 * Y[i] + 100 * M[i] + D[i]);

    // 3) 后缀最优：best[i] = 从第 i 天到末尾这段里灵感值最大的那一天（并列取更早的）
    vector<int> best(n);
    for (int i = n - 1; i >= 0; --i)
        best[i] = (i + 1 < n && sc[best[i + 1]] > sc[i]) ? best[i + 1] : i;

    // 4) 前缀天数：便于把 (a,b,c) 换算成日历下标（不讨论闰年，每年都是 365 天）
    int pre[13] = {0};
    for (int m = 1; m <= 12; ++m) pre[m] = pre[m - 1] + MON[m];

    int T;
    cin >> T;
    while (T--) {
        int a, b, c;
        cin >> a >> b >> c;
        int idx = (a - 1) * 365 + pre[b - 1] + (c - 1);      // 起始日在整张日历里的下标
        int j = best[idx];                                   // 从这天到 2026-1-9 的最优解
        cout << Y[j] << ' ' << M[j] << ' ' << D[j] << '\n';
    }
    return 0;
}
```

### 易错点

按题意二月永远二十八天，不使用真实闰年规则。数位异或是逐个十进制数字做异或，不是年份、月份、日期直接异或。

## B. 正负交锋：光与暗的能量序列

### 题意

两人轮流给空位填正一或负一，先手最大化终局最大子段和、后手最小化它，求最优结果。

### 思路

最大子段和对每个元素单调不减，因此先手总可填正一、后手总可填负一，只需争夺位置。

后手把位置按相邻两格配对，奇数长度时最后留一格。先手进入尚无负一的对子，后手立即填另一格；若该对已有负一或先手填末尾单格，则到另一个尚无负一的对子填负一。每对最后各有正负一，任意连续区间中间完整对子和为零，只有两端各至多贡献一，故结果不超过二。

![完整对子抵消，只需检查区间两端](assets/b-pairs.svg)

$n\ge3$ 时，先手先占内部位置，后手最多堵一个邻居，下一步先手再占另一个邻居，保证相邻两个正一，结果至少二。$n=1,2$ 时直接为一。每组时间、空间 $O(1)$。

### 参考代码

```cpp
// 练习赛 155 B. 正负交锋：光与暗的能量序列
// 结论：n = 1、2 时先手最多只能保证 1；n >= 3 时先手保证至少 2，后手也能压到不超过 2。
#include <bits/stdc++.h>   // 竞赛常用总头：一次引入全部标准库
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关闭 cin/cout 与 stdio 的同步，加快读入
    cin.tie(nullptr);              // 解除 cin 与 cout 的绑定

    int T;                         // 数据组数
    cin >> T;
    while (T--) {
        int n;                     // 本组的序列长度
        cin >> n;
        // n <= 2：后手用唯一一步把 -1 贴在先手的 +1 旁边，最大子段和只能是 1。
        // n >= 3：先手占一个内部位置，再贴着它补一个 +1 得到 2；
        //         后手按「成对贴 -1」的策略把任何区间的和压在 2 以内。
        cout << (n <= 2 ? 1 : 2) << '\n';
    }
    return 0;
}
```

### 易错点

奇数长度的未配对格应留在端点，才不会在区间中间额外产生第三份正贡献。最大子段要求非空，但先手总能放下一。

## C. 遗迹探索：不可重叠的频段

### 题意

每个信号源可贡献 $a_i$、$a_i-x$ 或不贡献；接收集合去重，求不同值之和的最小值与最大值。

### 思路

最大化时不必选负值，最小化时不必选正值。把后者的负权取反，两种任务都能化为选择有利节点的最大权和。

若 $x=0$，每个不同值可以独立选或不选，直接累加正值或负值。否则令 $d=|x|$，当 $x<0$ 时把坐标取反；每个源便统一为可服务本坐标或左边距离 $d$ 的坐标。按模 $d$ 的余数分成若干独立链，并补上可能被服务的空坐标。

沿链从小到大动态规划，状态只记左邻是否已借用当前位置的一份源。若本位置有 $c$ 份，先扣掉被借的零或一份；当前节点可以不选，或消耗剩余一份选中，或向右邻借一份选中。借用留作下一位置的状态，链尾不能再借。

每个源至多服务一个节点，选中节点只加一次权，因此该匹配式 DP 正好覆盖可实现集合。各链结果相加，排序时间 $O(n\log n)$，空间 $O(n)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

static const ll NEG = -(1LL << 60);   // 表示「该权值不允许被选中」

// 一条链上的可行性 DP：返回可选节点权值和的最大值
// nd[j] = (坐标, 该坐标上的信号源个数)，按坐标升序；w[j] = 节点 j 的权值（NEG = 不可选）
// dp0 / dp1 分别表示「前一个节点没有/有借用本坐标的源」两种状态下已得的最大权值和
static ll chain_dp(const vector<pair<ll, ll>>& nd, const vector<ll>& w) {
    int k = (int)nd.size();
    ll dp0 = 0, dp1 = NEG;                       // 起点：第一个节点下方没有借用的节点
    for (int j = 0; j < k; j++) {
        ll c = nd[j].second;                     // 本坐标上的信号源个数（幻影节点为 0）
        ll wj = w[j];                            // 本节点的权值
        bool can = (j + 1 < k);                  // 只有不是最后一个节点才可能向上借源
        ll n0 = NEG, n1 = NEG;                   // 本节点不借 / 借 之后的两种状态
        // ---- 前一个节点没有借用本坐标的源（dp0）
        n0 = max(n0, dp0);                       // 不选本节点
        if (c >= 1 && wj > NEG / 2) n0 = max(n0, dp0 + wj);   // 选本节点，用本坐标自己的源
        if (can && wj > NEG / 2)    n1 = max(n1, dp0 + wj);   // 选本节点，向上方坐标借源
        // ---- 前一个节点借用了本坐标的源（dp1），本坐标至少要留 1 个源给它
        if (dp1 > NEG / 2) {
            if (c >= 1) n0 = max(n0, dp1);                    // 不选本节点（源让给前一个）
            if (c >= 2 && wj > NEG / 2) n0 = max(n0, dp1 + wj);  // 选本节点并用自身源（要 2 个源）
            if (c >= 1 && can && wj > NEG / 2) n1 = max(n1, dp1 + wj);  // 也向上借源
        }
        dp0 = n0; n1 = (n1 > NEG / 2) ? n1 : NEG;
        dp1 = n1;
    }
    return dp0;                                  // 最后一个节点不能借源，故只取 dp0
}

int main() {
    ios::sync_with_stdio(false);                 // 关掉与 stdio 的同步（只用 cin/cout）
    cin.tie(nullptr);
    int n; ll x;
    if (!(cin >> n >> x)) return 0;
    vector<ll> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    if (x == 0) {                                // 频偏为 0：只能用 a_i 本身，屏蔽多余的重复值
        sort(a.begin(), a.end());
        a.erase(unique(a.begin(), a.end()), a.end());
        ll mn = 0, mx = 0;
        for (ll v : a) { if (v < 0) mn += v; else mx += v; }
        cout << mn << " " << mx << "\n";
        return 0;
    }

    ll d = (x > 0 ? x : -x);                     // 链上相邻两值的间距
    ll s = (x > 0 ? 1 : -1);                     // 符号：x<0 时 a_i-x 比 a_i 大
    // 把每个源映射成坐标 u = a_i * s，则它可供给 u（直接）或 u-d（降维），归一到同一方向
    map<ll, ll> cnt;
    for (int i = 0; i < n; i++) cnt[a[i] * s]++;

    map<ll, ll> node;                            // 坐标 -> 该坐标上的源数；幻影节点（只有降维能取到）记 0
    for (auto& p : cnt) {
        node[p.first] += p.second;               // 直接值本身一定是节点
        node[p.first - d] += 0;                  // 降维值也是节点（若不存在源则源数为 0）
    }

    map<ll, vector<pair<ll, ll>>> chain;         // 余数 -> 该链的节点（按坐标升序）
    for (auto& p : node) {
        ll u = p.first;
        ll r = ((u % d) + d) % d;                // 同余的数才可能通过反复 -d 走到一起
        chain[r].push_back({u, p.second});
    }

    ll bestMax = 0, bestMin = 0;                 // bestMin 存的是「负值取反后的和」的最大值
    for (auto& ch : chain) {
        const vector<pair<ll, ll>>& nd = ch.second;
        vector<ll> wMax(nd.size()), wMin(nd.size());
        for (size_t j = 0; j < nd.size(); j++) {
            ll val = nd[j].first * s;            // 该节点的真实数值
            wMax[j] = (val > 0 ? val : NEG);     // 求最大值：只值得选正数
            wMin[j] = (val < 0 ? -val : NEG);    // 求最小值：只值得选负数，取反后变成最大值
        }
        bestMax += chain_dp(nd, wMax);           // 各条链互相独立，直接相加
        bestMin += chain_dp(nd, wMin);
    }
    cout << -bestMin << " " << bestMax << "\n";
    return 0;
}
```

### 易错点

源是可重复的，但接收值去重；同坐标两份源可以分别服务自身和左邻，不能把输入直接去重丢掉数量。负坐标分组时规范模数余数。

## D. 期末危机：失灵的古董计算器

### 题意

两个计算器按键损坏，构造不含它们、从左到右求值等于给定 $[-100,100]$ 整数的算式，长度不超过二百五十六。

### 从零讲：左到右求值链

这里的计算器每遇到一个运算符，就对当前累计值执行下一步。例如二加六除二得到四，因为先得到八再除二。

因此“造出一个一”的片段不能随意接在后面：在已有和后接二除二，会把已有和也除掉。把除法造一放在整条链开头，或只使用加减链，就能精确控制累计结果。

对于纯减法链，首项 $A$ 后面的所有项只需总和为 $A-x$；这把表达式构造化为小整数凑和，而无需搜索任意语法树。

### 思路

只有两类显然无解：目标为负且减号坏；目标为零且减号、数字零同时坏。前者所有可写运算保持非负，后者甚至始终严格为正。

零可直接写零，或写可用数字减自身。正数先尝试直接写；若加号和一可用，用若干一相加；若一坏而减号可用，用相邻可用数字之差造一，再配合最小可用非零数字凑数。若坏键恰为一和减号，可先以二除二造一，再在后面加可用数字，避免左到右求值影响已有总和。

若加号坏且目标不能直接写，则至多另有一个数字坏，枚举短式 $A-B=x$；代码依次检查差、积、商等短模板，每个候选都按可用数字和精确等式筛选。目标与坏键种类均为固定小范围，模板覆盖可逐项有限检查。

负目标 $-m$ 写成 $A-t_1-\cdots-t_s$，要求后面数字之和为 $m+A$。将可用非零数字当硬币，用小规模最少硬币 DP 找最短减法链，并记录路径还原。

所有搜索只依赖固定的小目标范围，每组常数规模，输出前保持长度与禁用字符约束。

### 参考代码

```cpp
// 练习赛 155 D. 期末危机：失灵的古董计算器
// 思路：只有两种情形必定无解（见 buildZero/buildPos/buildNeg 前的注释），其余情形一律给出构造。
// 构造只由「整数 + 加减乘除」拼成，且除法处都保证整除，长度最大 203 < 256。
#include <bits/stdc++.h>
using namespace std;

static bool bad[256];   // bad[c] = true：按键 c 损坏，答案里绝对不能出现

// 数字键 d 是否可用
static bool digOK(int d) { return !bad[(unsigned char)('0' + d)]; }
// 运算符键 c 是否可用
static bool opOK(char c) { return !bad[(unsigned char)c]; }

// 能否把 v 原样写成一个合法数字：非负、无前导零、每一位都可按
static bool numOK(long long v) {
    if (v < 0) return false;                 // 算式以数字开头，写不出负号，负数不能直接写
    string s = to_string(v);
    for (char c : s) if (bad[(unsigned char)c]) return false;
    return true;
}

// 最小可用的非零数字（只坏两个键，一定存在）
static int minDig() {
    for (int d = 1; d <= 9; d++) if (digOK(d)) return d;
    return -1;
}

// 把若干「项」用 '+' 串成一条链：左到右求值恰好是各项之和
static string joinPlus(const vector<string>& t) {
    string s;
    for (size_t i = 0; i < t.size(); i++) { if (i) s += '+'; s += t[i]; }
    return s;
}

// 把若干「项」用 '-' 串成一条链：首项作被减数，结果 = t[0] - t[1] - t[2] - ...
static string joinMinus(const vector<string>& t) {
    string s;
    for (size_t i = 0; i < t.size(); i++) { if (i) s += '-'; s += t[i]; }
    return s;
}

// 把 v 拆成若干个「可用数字」之和（每个数字单独成项）；拆不出来时 ok = false
static vector<string> coinTerms(long long v, bool& ok) {
    vector<string> res;
    ok = true;
    if (v == 0) return res;                                   // 0 项就够
    vector<int> coins;                                        // 可用的数字硬币
    for (int d = 1; d <= 9; d++) if (digOK(d)) coins.push_back(d);
    const long long INF = (1LL << 60);
    vector<long long> dp(v + 1, INF);                         // dp[t]：拼出 t 最少要几个数字
    vector<int> pre(v + 1, 0);                                // pre[t]：最后一枚硬币
    dp[0] = 0;
    for (long long t = 1; t <= v; t++)
        for (int c : coins)
            if (t - c >= 0 && dp[t - c] + 1 < dp[t]) { dp[t] = dp[t - c] + 1; pre[t] = c; }
    if (dp[v] >= INF) { ok = false; return res; }             // 拼不出来，交给调用方换方案
    for (long long t = v; t > 0; t -= pre[t]) res.push_back(string(1, char('0' + pre[t])));
    return res;
}

// x = 0：有 0 键就写 "0"；否则必须靠 '-'，用 "d-d"
static string buildZero() {
    if (digOK(0)) return "0";
    int d = minDig();                                         // 0 坏了，非零数字一定还有
    string one(1, char('0' + d));
    return one + "-" + one;                                   // 值恒为 0
}

// x = n > 0
static string buildPos(long long n) {
    if (numOK(n)) return to_string(n);                        // 最省事：n 的十进制各位都能按
    if (opOK('+')) {                                          // 有加号：拆成若干项相加
        if (digOK(1)) {                                       // 有 1 就用 1+1+...+1（最多 199 字符）
            vector<string> t(n, string("1"));
            return joinPlus(t);
        }
        int d = minDig();                                     // 1 坏了，改用一个较大的数字 d 当砖块
        if (opOK('-')) {
            // 相邻两个可用数字 v+1、v 相减恒等于 1，把它当作「一块 1」
            int u = 0;
            for (int t = 2; t <= 9; t++) if (digOK(t) && digOK(t - 1)) { u = t; break; }
            string one = string(1, char('0' + u)) + "-" + string(1, char('0' + u - 1));
            long long q = n / d, r = n % d;                   // n = q 个 d 再加 r 个 1
            vector<string> terms;
            for (long long i = 0; i < r; i++) terms.push_back(one);
            for (long long i = 0; i < q; i++) terms.push_back(string(1, char('0' + d)));
            return joinPlus(terms);
        }
        // 只剩 '+'、'*'、'/'：此时坏键必然是 1 和 '-'，用 d/d 造出第一个 1
        string one = string(1, char('0' + d)) + "/" + string(1, char('0' + d));
        if (n == 1) return one;                               // 目标就是 1，直接 d/d
        bool ok = false;
        vector<string> rest = coinTerms(n - 1, ok);            // 剩下的 n-1 用可用数字相加
        if (ok) { rest.insert(rest.begin(), one); return joinPlus(rest); }
    }
    // '+' 不可用：只可能是「一个数字键 + 加号」同时坏掉，剩下的运算符是 '-'、'*'、'/'
    // 依次试几种短算式，第一个成立的就是答案
    for (long long b = 1; b <= 300; b++) {                     // 候补 1：A - B = n
        if (!numOK(b)) continue;
        long long a = n + b;
        if (numOK(a)) return to_string(a) + "-" + to_string(b);
    }
    for (long long b = 2; b * b <= n; b++) {                   // 候补 2：A * B = n
        if (n % b == 0 && numOK(b) && numOK(n / b)) return to_string(b) + "*" + to_string(n / b);
    }
    for (long long b = 2; b <= 120; b++) {                     // 候补 3：A / B = n（取 A = n*B）
        if (!numOK(b)) continue;
        long long a = n * b;
        if (numOK(a)) return to_string(a) + "/" + to_string(b);
    }
    for (long long a = 2; a <= 40; a++) {                      // 候补 4：A * B - C = n
        if (!numOK(a)) continue;
        for (long long b = 2; b <= 40; b++) {
            if (!numOK(b)) continue;
            long long c = a * b - n;
            if (c >= 0 && numOK(c)) return to_string(a) + "*" + to_string(b) + "-" + to_string(c);
        }
    }
    return string();                                           // 理论上到不了（穷举验证兜底）
}

// x = -m < 0：需要 '-' 可用（不可用时已经在 main 里判了 No）
static string buildNeg(long long m) {
    // 写成 A - t1 - t2 - ...，只要 t1..tk 之和等于 m + A，结果就是 -m
    vector<long long> cand;
    for (int d = 1; d <= 9; d++) if (digOK(d)) cand.push_back(d);      // 一位数优先，链最短
    for (long long v = 10; v <= 200; v++) if (numOK(v)) cand.push_back(v);  // 兜底：多位数开头
    for (long long a : cand) {
        bool ok = false;
        vector<string> t = coinTerms(m + a, ok);
        if (!ok) continue;
        t.insert(t.begin(), to_string(a));
        return joinMinus(t);                                   // a - (m+a) = -m
    }
    return string();                                           // 理论上到不了
}

int main() {
    ios::sync_with_stdio(false);                               // 只用 cin/cout，不与 stdio 混用
    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        string c;
        long long x;
        cin >> c >> x;                                         // 两个坏键 + 目标值
        memset(bad, 0, sizeof(bad));
        for (char ch : c) bad[(unsigned char)ch] = true;
        // 情形一：没有减号 → 所有数非负，负目标无解
        if (x < 0 && !opOK('-')) { cout << "No\n"; continue; }
        // 情形二：没有减号也没有 0 → 所有数严格为正，0 无解
        if (x == 0 && !digOK(0) && !opOK('-')) { cout << "No\n"; continue; }
        string ans;
        if (x == 0) ans = buildZero();
        else if (x > 0) ans = buildPos(x);
        else ans = buildNeg(-x);
        cout << "Yes\n" << ans.size() << "\n" << ans << "\n";  // 长度单独一行，再单独一行算式
    }
    return 0;
}
```

### 易错点

不能写前导负号，也不能把混合算式按通常乘除优先级求值。除数不能为零，多位数字不能有前导零。

## E. 苍蓝幻影的无尽增殖

### 题意

随机选择小写字母，在其每次出现后同时插入 Fantasy_Blue。询问区间内该模式出现次数；若全串次数超过 114514，此后询问输出固定文本。

### 思路

初串没有大写字母，模式唯一的 F 都来自插入块开头。若一个旧块内部插入新块，原模式在断点遇到额外的 F，立即失效；没有被切开的块恰好对应一次出现，因此可统计完整块数 $I$。

每次插入 $k$ 个新块，最多破坏 $k$ 个旧完整块，所以 $I$ 单调不减。一旦超过阈值，后续无需维护字符串。

设历史插块数为 $B$。命中模式中的小写字母时，至少插入 $B$ 个新块；操作后所有新块完整，故若仍未超阈值，$B$ 受到常数倍阈值的限制。命中模式外字母不会破坏旧块，插入多少就让 $I$ 增加多少，因此超阈值前串长为 $O(n+C)$，$C=114514$。

直接重建字符串并扫描出现起点。模式无非空前后缀重合，出现不会重叠；查询截断端点后，用二分统计起点落在 $[l-1,r-12]$ 的数量。某字母不存在则跳过重建。

若实际重建次数为 $J$，时间 $O(n+m+J(n+C)+q\log(n+C))$、空间 $O(n+C)$。题目随机字母保证下，命中块内字母会使历史块数至少翻倍，达到阈值前这类操作只有对数次；复杂度依赖此随机保证。

### 参考代码

```cpp
// 练习赛 155 E. 苍蓝幻影的无尽增殖
// 做法：字面模拟 + 阈值剪枝。
//   出现次数一旦超过 114514，之后所有询问都只能是 orz，于是完全不用再维护串；
//   而"字母等概率随机"保证每次插入量按几何级数涨，串长在越过阈值前有 O(n + 12*114514) 的上界。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;
    string s;                                  // 当前的完整字符串
    cin >> s;

    const string PAT = "Fantasy_Blue";         // 每次插入的整块，长度 12
    const int PL = (int)PAT.size();
    const long long LIMIT = 114514;            // 严格大于它就只能输出膜拜串
    const char* ORZ = "sto Fantasy_Blue orz";

    // add[x]：插入一个整块后，小写字母 x 的出现次数增加多少（'a' 有两个，n t s y l u e 各一个）
    int add[26] = {0};
    for (char ch : PAT)
        if (ch >= 'a' && ch <= 'z') add[ch - 'a']++;

    long long cnt[26] = {0};                   // 当前串里每个小写字母的出现次数
    for (char ch : s)
        if (ch >= 'a' && ch <= 'z') cnt[ch - 'a']++;

    // 收集当前串里所有 Fantasy_Blue 的出现起点（0 基、升序）。
    // 模式里只有一个 'F'（在下标 0），所以它没有非空 border、失败函数全 0，
    // KMP 退化成"匹配到就整段跳过"的线性扫描；也正因为无 border，各次出现互不重叠。
    vector<int> pos;
    auto collect = [&](const string& t) {
        pos.clear();
        int j = 0, L = (int)t.size();
        for (int i = 0; i < L; i++) {
            if (j > 0 && t[i] != PAT[j]) j = 0;     // 失败函数的每一项都是 0
            if (t[i] == PAT[j]) j++;
            if (j == PL) { pos.push_back(i - PL + 1); j = 0; }
        }
    };
    collect(s);

    bool over = (long long)pos.size() > LIMIT;  // 全局出现次数是否已经超过阈值
    string out;
    out.reserve(1 << 16);

    for (int qi = 0; qi < m; qi++) {
        int op;
        cin >> op;
        if (op == 1) {
            char c;
            cin >> c;
            if (over) continue;                 // 已超阈值：后面全是 orz，串不必再维护
            long long k = cnt[c - 'a'];         // 要插入的整块个数
            if (k == 0) continue;               // 串里没有 c：插入 0 个块，串原样不动
            string t;
            t.reserve(s.size() + (size_t)PL * (size_t)k);
            for (char ch : s) {
                t.push_back(ch);
                if (ch == c) t += PAT;          // 所有等于 c 的字符后面"同时"插入一个整块
            }
            s.swap(t);
            // 旧字符一个都没少，只是多了 k 个整块，所以计数可以直接加
            for (int x = 0; x < 26; x++) cnt[x] += k * add[x];
            collect(s);
            if ((long long)pos.size() > LIMIT) over = true;
        } else {
            long long l, r;
            cin >> l >> r;
            if (over) { out += ORZ; out += '\n'; continue; }
            long long len = (long long)s.size();
            if (l > len) l = len;               // 越界的左端点取 min(l, |s|)
            if (r > len) r = len;               // 越界的右端点取 min(r, |s|)
            long long lo = l - 1;               // 整段落在 [l, r] 内 <=> 0 基起点 >= l-1
            long long hi = r - PL;              //                   且 0 基起点 <= r-12
            long long ans = 0;
            if (hi >= lo)
                ans = upper_bound(pos.begin(), pos.end(), (int)hi)
                    - lower_bound(pos.begin(), pos.end(), (int)lo);
            out += to_string(ans);
            out.push_back('\n');
        }
    }
    cout << out;
    return 0;
}
```

### 易错点

插入同时发生，新插入字符不能在同一次操作继续触发。阈值判断看全串次数，不能只看查询区间。长度不足十二的区间答案为零。

## F. 无尽星阵：占星师的镜像试炼

### 题意

周期串复制后接成环，要求选出至少 $V$ 个互不相交的段，每段含指定字母集合全部种类，求最少额外复制次数。

### 思路

固定集合，令 $F(i)$ 为从无限周期串位置 $i$ 开始，收齐所有指定字母后的下一位置。贪心每段尽早结束最优，且 $F$ 单调不减、$F(i+n)=F(i)+n$。

只记起点模 $n$ 的相位，每相位有唯一后继。从零出发最终进环，设环上有 $\lambda$ 段、总前进 $qn$ 格，则长期每段平均前进 $qn/\lambda$。任意两起点可平移到相差不超过 $n$，单调性使任意步数后的距离仍不超过 $n$，所以所有相位拥有相同长期平均值。

![环上的三段覆盖两份原串，密度为三比二](assets/f-density.svg)

环长为 $Ln$ 时能放 $V$ 段，当且仅当存在整数起点 $i$ 满足 $F^V(i)\le i+Ln$。若存在，反复套用单调性与周期性，可知长期平均满足 $Vq/\lambda\le L$。反过来，若所有起点都失败，则 $F^V(i)-Ln\ge i+1$；反复迭代这个映射，每次至少前进一步，推出长期 $Vqn/\lambda-Ln>0$，与该不等式矛盾。因此精确答案为 $L=\lceil Vq/\lambda\rceil$，额外复制数为 $L-1$。

十二种字母最多 4095 个非空集合，同集合缓存环参数。代码沿轨道直接扫描最短窗口，设集合 $B$ 的累计扫描字符数为 $C_B$，总时间 $O(\sum_B C_B+m)$；每条轨道至多 $n$ 个相位、窗口长至多 $n$，保守上界为 $O(Sn^2+m)$，实际取决于轨道扫描量。空间 $O(n+m)$。

### 参考代码

```cpp
// 练习赛 155 F. 无尽星阵：占星师的镜像试炼
// 做法：对每个「目标字母集合」B，研究无限周期串上的贪心窗口映射
//       f(i) = (所有 B 中字母都出现过的最早位置) + 1（下标 mod n 看作相位）。
//       相位图是「出度为 1 的函数图」，从任意相位出发必进环；记环长 lam、
//       环上窗口长度之和 W = q*n，则该环给出密度 lam/q 个窗口/组。
//       环 L 组时能取到的最大不相交共鸣段数 = floor(L*lam/q)，
//       于是 V 点能量最少需要 L = ceil(V*q/lam) 组，答案 t = L-1。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    vector<unsigned> pre(2 * (size_t)n);             // 每格存该字母的位（省掉移位）
    for (int i = 0; i < n; ++i) {
        char c;
        cin >> c;
        pre[i] = 1u << (c - 'A');
    }
    for (int i = 0; i < n; ++i) pre[i + n] = pre[i]; // 双倍串：窗口最远伸到 i+n-1

    int m;
    cin >> m;
    vector<int> qmask(m);
    vector<long long> qv(m);
    vector<int> cntQuery(4096, 0);
    for (int i = 0; i < m; ++i) {
        int k;
        long long V;
        cin >> k >> V;
        int mask = 0;
        for (int j = 0; j < k; ++j) {
            char c;
            cin >> c;
            mask |= 1 << (c - 'A');
        }
        qmask[i] = mask;
        qv[i] = V;
        ++cntQuery[mask];
    }
    // 按集合（12 位掩码）归桶：同一集合只求一次环，之后每个任务 O(1)
    vector<int> head(4097, 0);
    for (int s = 0; s < 4096; ++s) head[s + 1] = head[s] + cntQuery[s];
    vector<int> fill = head;                 // head 保留桶起点
    vector<int> order(m);
    for (int i = 0; i < m; ++i) order[fill[qmask[i]]++] = i;

    vector<long long> ans(m, 0);
    vector<int> visVer(n, 0), visStep(n, 0);
    vector<long long> visU(n, 0);
    int ver = 0;

    for (int mask = 1; mask < 4096; ++mask) {
        if (!cntQuery[mask]) continue;
        unsigned inB = 0;                    // 该集合的字母掩码
        for (int x = 0; x < 12; ++x)
            if ((mask >> x) & 1) inB |= 1u << x;

        // 从相位 0 出发沿函数图走，直到撞上本轮访问过的相位 -> 找到环
        ++ver;
        int cur = 0, step = 0;
        long long u = 0;                     // 展开后的位置（不限 mod n）
        long long lam = 1, q = 1;
        for (;;) {
            if (visVer[cur] == ver) {        // 环闭合
                lam = step - visStep[cur];
                q = (u - visU[cur]) / n;     // 环上总步进必是 n 的倍数
                break;
            }
            visVer[cur] = ver;
            visStep[cur] = step;
            visU[cur] = u;
            // 从 cur 向后扫，扫到 B 中字母全部出现为止：扫过的长度就是窗口长度
            const unsigned *p = pre.data() + cur;
            unsigned seen = 0;
            do {
                unsigned b = *p++;
                if (b & inB) seen |= b;      // seen 只含 B 内字母，故可与 inB 直接比
            } while (seen != inB);
            u += (long long)(p - (pre.data() + cur));   // = T_B(cur) - cur + 1
            cur = (int)(u % n);              // 下一个相位
            ++step;
        }

        for (int t = head[mask]; t < head[mask + 1]; ++t) {
            int idx = order[t];
            long long V = qv[idx];
            // L = ceil(V*q/lam) = floor(V/lam)*q + ceil((V mod lam)*q/lam)
            // （q <= lam 保证第一项不超过 V，不会溢出）
            long long L = (V / lam) * q + (((V % lam) * q + lam - 1) / lam);
            ans[idx] = L - 1;
        }
    }

    string out;
    out.reserve(1 << 16);
    for (int i = 0; i < m; ++i) {
        out += to_string(ans[i]);
        out += '\n';
        if (out.size() >= (1u << 16)) {
            cout << out;
            out.clear();
        }
    }
    cout << out;
    return 0;
}
```

### 易错点

密度可能为分数，不能用最少出现字母的次数代替。$Vq$ 可能溢出 64 位，用商余分解计算上取整，最终还要减一才是复制次数。

## A. Flower_Rainbow_and_Honey

### 题意

已知两步左右移动指令，以及每步离原点变近或变远的提示，找一个 $[-10,10]$ 内的整数起点满足提示。

### 思路

候选只有二十一个，逐个模拟两步，比较移动前后绝对值。每一步的严格变近结果都与提示一致，就输出该起点；所有候选失败则输出 T_T。候选与步数均固定，时间、空间 $O(1)$。

### 参考代码

```cpp
// 练习赛 156 A. Flower_Rainbow_and_Honey
// 做法：初始坐标只有 21 种可能（-10 ~ 10 的整数），逐个模拟两步，输出第一个能对上 GPS 的。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 全程只用 cin/cout，不混用 stdio
    cin.tie(nullptr);

    string s, t;                          // s：2 步移动序列；t：GPS 的 2 个指示
    if (!(cin >> s >> t)) return 0;

    for (int x = -10; x <= 10; ++x) {     // 枚举初始坐标 X，从小到大
        int pos = x;                      // pos = 当前所在位置
        bool ok = true;                   // 这组候选 X = x 是否完全匹配
        for (int i = 0; i < 2; ++i) {
            int nxt = pos + (s[i] == 'R' ? 1 : -1);   // 第 i+1 次移动后的位置
            bool closer = abs(nxt) < abs(pos);        // 是否离糖果店更近（严格更近）
            if (closer != (t[i] == 'C')) {            // 与 GPS 的指示对不上
                ok = false;
                break;                                // 这个 x 废了，换下一个
            }
            pos = nxt;                                // 位置推进，供下一步判断
        }
        if (ok) {                         // 题目允许多解，取第一个（最小的合法 X）
            cout << x << "\n";
            return 0;
        }
    }
    cout << "T_T\n";                      // 21 个候选全不合法
    return 0;
}
```

### 易错点

比较的是每一步前后的距离，不是与最初距离比较。跨过原点后，左右移动对应的远近会改变。

## B. Flower_Rainbow_and_Victory

### 题意

两人轮流拿牌，数字零或蓝色对 Rainbow 有效，数字一或红色对 Flower 有效，求最优策略下有效牌数比较的结果。

### 从零讲：手牌张数不变量

先手最终固定拿 $K=\lceil n/2\rceil$ 张，后手拿 $L=\lfloor n/2\rfloor$ 张。设先手拿到只对自己有效牌 $r$ 张、双有效牌 $u$ 张，自己的得分是 $r+u$。

后手的无效牌只有剩下的 $a-r$ 张先手专属牌，所以后手得分为 $L-(a-r)$。相减得到 $D=a+u-L$，其中 $r$ 恰好消掉。于是单效牌的具体归属无须继续博弈，真正需要争夺的只有双有效牌。

### 思路

将牌分为只对 Rainbow 有效、双有效、只对 Flower 有效，数量分别为 $a,b,c$。基础小节说明终局分差只由 Rainbow 拿到的双有效牌数 $u$ 决定：$D=a+u-\lfloor n/2\rfloor$。

因此双方都优先拿双有效牌。Rainbow 这样做保证每张被对手拿走的双有效牌前，自己也拿过一张；Flower 这样做保证除先手第一张外，每张被 Rainbow 拿走的双有效牌前自己也拿过一张。上下界夹出 $u=\lceil b/2\rceil$。

代入分差，正、负、零分别对应 Rainbow、Flower、平局。扫描分类时间 $O(n)$，额外空间 $O(1)$。

### 参考代码

```cpp
// B. Flower_Rainbow_and_Victory
// 结论：把牌按「对谁有效」分四类——(0,B) 只对 Rainbow 有效；(0,R) 与 (1,B) 对双方都有效；(1,R) 只对 Flower 有效。
// 记 a = 只对 Rainbow 有效的牌数、m = 对双方都有效的牌数，n 为总牌数，则最优博弈下的分差恒为
//     D = Rainbow 有效牌数 - Flower 有效牌数 = a + ceil(m / 2) - floor(n / 2)，
// 正负零分别对应 Rainbow / Flower / Draw（推导见题解）。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);       // 关掉 cin/cout 与 stdio 的同步，加快读入
    cin.tie(nullptr);                  // 解除 cin 与 cout 的绑定
    int T;                             // 数据组数
    if (!(cin >> T)) return 0;         // 读不到组数就正常结束
    while (T--) {                      // 逐组处理
        int n;                         // 本组牌堆张数
        string s, t;                   // s 是数字串，t 是花色串
        cin >> n >> s >> t;
        int onlyR = 0;                 // 只对 Rainbow 有效的牌数
        int both = 0;                  // 对双方都有效的牌数
        for (int i = 0; i < n; i++) {  // 逐张牌分类
            if (s[i] == '0' && t[i] == 'B') {
                onlyR++;               // 数字 0 让 Rainbow 有效、花色 B 让 Flower 无效，故只归 Rainbow
            } else if ((s[i] == '0' && t[i] == 'R') || (s[i] == '1' && t[i] == 'B')) {
                both++;                // 一个条件偏向 Rainbow、另一个偏向 Flower，两边都有效
            }
            // 余下的 (1,R) 只对 Flower 有效，由 floor(n/2) 那一项隐含，无需单独统计
        }
        int diff = onlyR + (both + 1) / 2 - n / 2;   // ceil(both/2) = (both+1)/2，floor(n/2) = n/2（都是非负整数除法）
        if (diff > 0) cout << "Rainbow\n";           // 分差为正：Rainbow 手里的有效牌更多
        else if (diff < 0) cout << "Flower\n";       // 分差为负：Flower 更多
        else cout << "Draw\n";                       // 分差为零：平局
    }
    return 0;
}
```

### 易错点

条件中的“或”让两类交叉属性牌同时有效，不是每张牌只属于一人。先手总手牌数比后手可能多一。

## C. Flower_Rainbow_and_Firework

### 题意

构造 $n$ 点树，要求直径不超过 $d$、每点度数不超过 $k$，无解则输出负一。

### 从零讲：树的中心

树的最长路径称为直径，其正中间是中心：直径为偶数时中心是一个顶点，为奇数时是相邻两个顶点之间的一条边。

从顶点中心向外，所有点的距离不超过半径；从中心边两端分别向外，最深各走同样层数。否则某个过深分支与直径另一侧拼接，就会超过原最长路径。

因此限制直径，可以转成限制中心附近的层数；再按每点可用的孩子数量逐层展开，就能同时推导容量上界与达到上界的构造。

### 思路

题面保证 $n\ge2$，度数上限为一时只能容纳至多两点，代码的容量公式会直接覆盖这个边界。令 $A(h)=1+(k-1)+\cdots+(k-1)^h$，表示已有父边的一个根向下长 $h$ 层最多容纳的点数。

若 $d=2h$，取顶点中心，最多容纳 $1+kA(h-1)$ 点；若 $d=2h+1$，取中心边，两端各剩 $k-1$ 个分支名额，最多容纳 $2A(h)$ 点。按基础小节的中心性质，这也是对应直径限制的容量上界。

![中心边两侧的深度分别受限](assets/c-centers.svg)

按容量模型 BFS 添加节点，凑满 $n$ 即停。每个新点连向已存在父亲，提前停止仍连通，深度与度数也不会增加；若容量不足则无解。计算容量时达到 $n$ 就封顶，防止幂次溢出。输出时间、空间 $O(n)$。

### 参考代码

```cpp
// C. Flower_Rainbow_and_Firework
// 构造一棵 n 个点的树，使直径 <= d 且最大度数 <= k；不行输出 -1。
//
// 关键结论（最大可行点数 f）：
//   把树按「中心」分类：树心要么是一个点（直径是偶数），要么是一条边（直径是奇数），
//   且所有点到中心的距离 <= 直径/2。于是
//     · 顶点中心，高度限 h = floor(d/2)：最多 1 + k*A(h-1)
//     · 边中心，两侧各高 h = floor((d-1)/2)：最多 2*A(h)
//   其中 A(t) = 1 + (k-1) + (k-1)^2 + ... + (k-1)^t（根已占用一条父边，故只有 k-1 个儿子）。
//   偶数 d 时顶点中心更优，奇数 d 时边中心更优（严格占优，见题解）。
//   构造就用这两种形态做 BFS 分层贪心，取前 n 个点即为合法答案（前缀仍是树，直径只会更小）。
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    if (!(cin >> T)) return 0;
    while (T--) {
        int n;
        ll d, k;
        cin >> n >> d >> k;
        // 把 f 的中间量封顶到 n+1，避免 (k-1)^t 溢出；只要判断 n <= f 即可
        const ll CAP = (ll)n + 1;
        ll base = k - 1;
        // A(t) = sum_{i=0}^{t} (k-1)^i，t 可能为 -1（返回 0）
        auto A = [&](ll t) -> ll {
            if (t < 0) return 0;
            ll res = 1, term = 1;
            for (ll i = 0; i < t; i++) {
                if (term == 0) break;              // k==1 时后面全是 0
                term *= base;
                if (term > CAP) term = CAP;
                res += term;
                if (res > CAP) res = CAP;
            }
            return res;
        };
        ll f;
        bool odd = (d % 2 != 0);
        if (!odd) {
            ll h = d / 2;                          // 顶点中心，高度限 h
            f = 1 + k * A(h - 1);
        } else {
            ll h = (d - 1) / 2;                    // 边中心，两侧各高 h
            f = 2 * A(h);
        }
        if (f > CAP) f = CAP;
        if ((ll)n > f) {                           // 超过理论上限，无解
            cout << -1 << "\n";
            continue;
        }
        // ---- 构造：BFS 分层贪心 ----
        // allow[v]  = v 的子树最远能到根 1 的第几层（从根 1 数）
        // budget[v] = v 还能连几个儿子
        vector<int> par(n + 1, 0), dep(n + 1, 0), q;
        vector<ll> allow(n + 1, 0), budget(n + 1, 0);
        q.reserve(n + 1);
        int nextId;
        if (!odd) {
            ll h = d / 2;
            allow[1] = h; budget[1] = k;           // 根可以连 k 个儿子
            q.push_back(1);
            nextId = 2;
        } else {
            ll h = (d - 1) / 2;
            allow[1] = h; budget[1] = k - 1;       // 根要让出一条边连 2
            par[2] = 1; dep[2] = 1; allow[2] = h + 1; budget[2] = k - 1;
            q.push_back(1); q.push_back(2);        // 2 这一侧可以多探一层
            nextId = 3;
        }
        for (size_t head = 0; head < q.size() && nextId <= n; head++) {
            int v = q[head];
            while (budget[v] > 0 && nextId <= n && (ll)dep[v] < allow[v]) {
                int u = nextId++;
                par[u] = v;
                dep[u] = dep[v] + 1;
                allow[u] = allow[v];
                budget[u] = k - 1;
                budget[v]--;
                q.push_back(u);
            }
        }
        for (int i = 2; i <= n; i++) cout << par[i] << " " << i << "\n";
    }
    return 0;
}
```

### 易错点

要求直径至多 $d$，不必强行构造恰为 $d$ 的路径。非中心节点已被父边占去一度，只能再连 $k-1$ 个孩子。

## D. Flower_Rainbow_and_Cherish

### 题意

对每对祖先 $u$ 与其后代 $v$，贡献为距离乘 $(a_u\oplus a_v\oplus X)$；选择全树共用的 $X$ 使总和最小。

### 思路

异或逐位独立。记所有祖先后代对的距离和为 $W$，第 $b$ 位不同的那些对的距离和为 $S_b$。取 $X_b=0$ 时本位代价为 $2^bS_b$，取一时为 $2^b(W-S_b)$，因此取两者较小值。

固定一位，子树按本位零一分组，维护每组数量和到子树根的距离和。合并孩子时，其距离和加上数量，因为所有点多走一条父边。节点 $u$ 的贡献就是子树内与自己本位不同那组的距离和，累加得到 $S_b$；不分类地同样合并可求 $W$。

扫描三十一位，答案为 $\sum_b2^b\min(S_b,W-S_b)$，时间 $O(31n)$，空间 $O(n)$。

### 参考代码

```cpp
// 牛客练习赛 156 D. Flower_Rainbow_and_Cherish
//
// 核心：把「选一个 X」按二进制位拆开，每一位独立决策。
//   Sum = Σ_u F_u(X) = Σ_u Σ_{v∈subtree(u)} dist(u,v) · (a_u ⊕ a_v ⊕ X)
//       = Σ_k 2^k · Σ_u Σ_{v∈subtree(u)} dist(u,v) · bit_k(a_u ⊕ a_v ⊕ X)
//   第 k 位上 bit_k(a_u⊕a_v⊕X) = bit_k(a_u⊕a_v) ⊕ X_k，而 X_k 只有 0/1 两种取法：
//     记 W   = Σ_u Σ_{v∈subtree(u)} dist(u,v)                    （全部对的权重和）
//     记 S_k = 只统计「a_u 与 a_v 第 k 位不同」的那些对的权重和
//     则 X_k=0 的总代价是 S_k，X_k=1 的总代价是 W−S_k，各取小即可。
//   所以 ans = Σ_k min(S_k, W − S_k) · 2^k（最后对 998244353 取模）。
//   W、S_k 都不取模，用 64 位整数精确比较大小（W ≤ 约 1.7e14，不会溢出）。
// 每个 k 用一次树形 DP 求 S_k：按位把点分成 0/1 两类，统计子树内两类的个数与
// 「到当前点的距离和」，则 u 的贡献就是另一类的距离和。总复杂度 O(31n)。

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

static const ll MOD = 998244353;   // 题目要求的模数

int main() {
    ios::sync_with_stdio(false);   // 只用 cin/cout，关同步加速
    cin.tie(nullptr);

    int T;
    if (!(cin >> T)) return 0;     // 多组数据
    while (T--) {
        int n;
        cin >> n;
        vector<ll> a(n + 1);
        ll maxa = 0;               // 最大权值，用来确定最高需要处理的位
        for (int i = 1; i <= n; ++i) {
            cin >> a[i];
            if (a[i] > maxa) maxa = a[i];
        }
        vector<vector<int>> adj(n + 1);          // 邻接表（无向边，之后从 1 号点定根）
        for (int i = 0; i < n - 1; ++i) {
            int u, v;
            cin >> u >> v;
            adj[u].push_back(v);
            adj[v].push_back(u);
        }

        // 以 1 为根做 BFS：得到每个点的父亲 par[] 和 BFS 序 order[]
        // 逆着 BFS 序扫，就保证「儿子一定排在父亲前面」，可以当后序 DP 用（不用递归，避免爆栈）
        vector<int> par(n + 1, 0), order;
        order.reserve(n);
        order.push_back(1);
        for (size_t i = 0; i < order.size(); ++i) {
            int u = order[i];
            for (int w : adj[u])
                if (w != par[u]) {                 // 树上除父亲外的邻居都是儿子
                    par[w] = u;
                    order.push_back(w);
                }
        }

        // 第一步：求 W —— 所有 (u, v∈subtree(u)) 对的距离之和
        // cntAll[u] = |subtree(u)|，sumAll[u] = Σ_{v∈subtree(u)} dist(u,v)
        vector<ll> cntAll(n + 1, 0), sumAll(n + 1, 0);
        ll W = 0;
        for (int i = n - 1; i >= 0; --i) {         // 逆 BFS 序 = 儿子先于父亲
            int u = order[i];
            cntAll[u] += 1;                        // 先把自己算进子树
            ll s = sumAll[u];                      // 此刻它已收齐所有儿子上报的值
            if (par[u] > 0) {                      // 再上报给父亲：个数相加、距离全部 +1
                cntAll[par[u]] += cntAll[u];
                sumAll[par[u]] += s + cntAll[u];
            }
            W += s;                                // s 就是 u 到其子树内所有点的距离和
        }

        // 第二步：对每一位 k 求 S_k，累加 min(S_k, W−S_k)·2^k
        int bits = 0;                              // 需要处理的位数 = maxa 的最高位 +1
        for (ll x = maxa; x > 0; x >>= 1) ++bits;  // maxa=0 时 bits=0，答案直接为 0

        vector<ll> c0(n + 1, 0), c1(n + 1, 0);     // 子树内第 k 位为 0 / 1 的点的个数
        vector<ll> s0(n + 1, 0), s1(n + 1, 0);     // 子树内第 k 位为 0 / 1 的点到 u 的距离和
        ll ans = 0, pw = 1;                        // pw = 2^k mod MOD
        for (int k = 0; k < bits; ++k) {
            fill(c0.begin(), c0.end(), 0);         // 逐位重开一轮 DP
            fill(c1.begin(), c1.end(), 0);
            fill(s0.begin(), s0.end(), 0);
            fill(s1.begin(), s1.end(), 0);
            ll S = 0;                              // 本位「两类不同」的对的权重和
            for (int i = n - 1; i >= 0; --i) {
                int u = order[i];
                int b = (int)((a[u] >> k) & 1);    // u 自己属于哪一类
                if (b) c1[u] += 1; else c0[u] += 1;
                int p = par[u];
                if (p > 0) {                       // 把 u 这一支整体上报给父亲
                    c0[p] += c0[u];
                    c1[p] += c1[u];
                    s0[p] += s0[u] + c0[u];        // 父亲到这些点要各多走 1 条边
                    s1[p] += s1[u] + c1[u];
                }
                // u 的贡献：子树内与 u 本位不同的那些点，到 u 的距离和
                S += b ? s0[u] : s1[u];
            }
            ll best = min(S, W - S);               // 本位取 X_k=0 或 1 的较小代价（精确比较）
            ans = (ans + (best % MOD) * pw) % MOD; // 乘 2^k 后入账
            pw = pw * 2 % MOD;
        }
        cout << ans << '\n';
    }
    return 0;
}
```

### 易错点

必须先用真实 64 位距离和比较大小，再对结果取模；取模后的数不保序。统计的是祖先后代对，不是任意无序点对。

## E. Flower_Rainbow_and_Module

### 题意

选择模块和破解顺序，第 $j$ 个费用为 $j a_i$；若出现连续 $d$ 个同色模块，减免一次 $W$，费用不低于零。预算内先最大化模块数，再最小化实付并输出方案。

### 从零讲：重排不等式（大的配小系数）

固定某色占据的位置 $p<q$，有难度 $u<v$。把较大难度放较早位置，比反着放少

$$pu+qv-(pv+qu)=(q-p)(v-u)\ge0.$$

因此同色应按难度降序从左往右安排，较大的值乘较小的位置系数。由于颜色位置固定，这样交换不改变奖励是否触发。反过来从右往左填时，自然依次取该色最小、次小的难度。

### 思路

固定每种颜色选取数量时，总能选该色难度最小的若干模块：替换成更小值不改变颜色序列与奖励，费用不会增加。同色内部的安排则由基础小节确定。

枚举目标长度 $y$，从右向左补颜色串。状态记录每色已用数量，以及尚未触发奖励时最左颜色与连续长度；奖励已触发的状态只记各色数量，因为以后不再关心连续情况。

已放 $j$ 个后缀元素，下一位置为 $y-j$。接颜色 $h$ 时，用该色第 $k_h+1$ 小的模块，增加 $(y-j)a$；更新连续长度，达到 $d$ 就转入奖励状态。相同状态只留最小原费用并记录前驱。

终点比较未触发费用与已触发费用减 $W$ 后截到零的结果。长度从大到小尝试，首个预算可行长度即最大，再还原最小费用状态。

设颜色数为 $C$、数量状态数 $P=\prod_h(c_h+1)\le2^n$、连续状态上限 $R$，时间上界 $O(nPC^2R)$，空间 $O(PCR)$；$n\le15$ 使枚举可行。

### 参考代码

```cpp
// 练习赛 156 E. Flower_Rainbow_and_Module
//
// 关键结论（详见题解）：
//   1) 同一种颜色的模块被选中的个数一经确定，「取哪些」一定取该颜色里 a 最小的那几个
//      —— 把任意一个换成同色更小的，颜色序列不变（触发条件只看颜色），代价只会更小；
//   2) 颜色序列（破解顺序的颜色串）一定就成了：同一颜色在串中的第 i 次「从右往左」出现
//      放该颜色第 i 小的元素，这样同色内部代价最小（排序不等式）。
// 于是只需枚举「每种颜色取几个」的组合（混合进制编码），对颜色串做 DP。
// DP 从右往左构建后缀，分两态：A = 还没触发奖励（要记住最左端颜色与连续长度），
// B = 已经触发过奖励（后面随便排，只需记代价）。
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
static const ll INF = (ll)4e18;

int main() {
    ios::sync_with_stdio(false);   // 关同步，加快读入
    cin.tie(nullptr);

    int T;
    if (!(cin >> T)) return 0;
    while (T--) {
        int n, d;
        ll m, W;
        cin >> n >> m >> d >> W;                 // 模块数、预算、连续长度阈值、奖励额度
        vector<ll> a(n);
        for (int i = 0; i < n; ++i) cin >> a[i]; // 破解难度
        vector<int> col(n);
        for (int i = 0; i < n; ++i) cin >> col[i]; // 颜色

        // ---------- 按颜色分组，组内按 a 升序排好，只存原始下标 ----------
        map<int, vector<int>> bucket;
        for (int i = 0; i < n; ++i) bucket[col[i]].push_back(i);
        int C = (int)bucket.size();              // 颜色种数
        vector<vector<int>> id(C);               // id[g]：颜色 g 的元素下标，按 a 从小到大
        {
            int g = 0;
            for (auto &kv : bucket) {
                vector<int> v = kv.second;
                sort(v.begin(), v.end(), [&](int x, int y) { return a[x] < a[y]; });
                id[g++] = v;
            }
        }
        vector<int> sz(C);
        for (int g = 0; g < C; ++g) sz[g] = (int)id[g].size();

        // ---------- 把「每种颜色取 k_g 个」编码成混合进制整数 ----------
        vector<int> radix(C);
        int codes = 1;
        for (int g = 0; g < C; ++g) {            // radix[g] 是第 g 位的位权
            radix[g] = codes;
            codes *= sz[g] + 1;
        }
        // 按「已放置元素个数」给状态码分层，DP 只沿层数增大的方向走
        vector<vector<int>> layer(n + 1);
        for (int code = 0; code < codes; ++code) {
            int s = 0;
            for (int g = 0; g < C; ++g) s += (code / radix[g]) % (sz[g] + 1);
            layer[s].push_back(code);
        }
        int maxSz = 0;
        for (int g = 0; g < C; ++g) maxSz = max(maxSz, sz[g]);
        int Rmax = min(d - 1, maxSz);            // 未触发态要记的连续同色长度上限
        int stride = max(Rmax, 1);               // 长度维的步长（d=1 时该维退化为 1）

        // ---------- 对每个「破解总数 y」跑一遍 DP，从 n 往小找第一个可行的 ----------
        int ansY = 0;
        ll ansX = 0;
        vector<int> ansOrd;

        size_t Astep = (size_t)C * (size_t)stride;
        vector<ll> A((size_t)codes * Astep, INF);  // A[code][g][r]：未触发，最左端是 g、连续 r+1 个
        vector<int> pa((size_t)codes * Astep, 0);  // A 态的前驱（r+1=1 时用）：g*stride+r
        vector<ll> B(codes, INF);                  // B[code]：已触发过的后缀最小代价
        vector<int> pb(codes, 0);                  // B 态最左端颜色
        vector<int> pbk(codes, 0);                 // B 态前驱种类：0=A 态，1=B 态
        vector<int> pbv(codes, 0);                 // 前驱为 A 态时存的 g*stride+r

        for (int y = n; y >= 1; --y) {
            fill(A.begin(), A.end(), INF);
            fill(pa.begin(), pa.end(), 0);
            fill(B.begin(), B.end(), INF);
            fill(pb.begin(), pb.end(), 0);
            fill(pbk.begin(), pbk.end(), 0);
            fill(pbv.begin(), pbv.end(), 0);

            // 第 0 层：后缀只含 1 个元素，它落在第 y 位
            for (int g = 0; g < C; ++g) {
                int code = radix[g];
                ll base = (ll)y * a[id[g][0]];     // 该色取 1 个 → 取最小的那个
                if (d == 1) {                      // d=1：放下第 1 个就已经触发
                    if (base < B[code]) { B[code] = base; pb[code] = g; pbk[code] = 1; }
                } else {
                    size_t st = (size_t)code * Astep + (size_t)g * stride;
                    if (base < A[st]) { A[st] = base; pa[st] = -1; }
                }
            }

            // 逐层向左生长：后缀已有 j 个，新元素落在第 pos = y-j 位
            for (int j = 1; j <= y - 1; ++j) {
                int pos = y - j;
                for (int code : layer[j]) {
                    // --- 从 A 态扩展：可能继续保持未触发，也可能正好凑够 d 个而触发 ---
                    for (int g = 0; g < C; ++g) {
                        int kg = (code / radix[g]) % (sz[g] + 1);
                        if (kg == 0) continue;      // 该色此时不在后缀里，不可能是最左端
                        for (int r = 0; r < Rmax; ++r) {
                            size_t st = (size_t)code * Astep + (size_t)g * stride + r;
                            ll v = A[st];
                            if (v >= INF) continue;
                            int run = r + 1;        // 当前最左端的连续同色长度
                            for (int h = 0; h < C; ++h) {
                                int kh = (code / radix[h]) % (sz[h] + 1);
                                if (kh >= sz[h]) continue;             // 该色元素已取完
                                int nc = code + radix[h];              // 该色多取一个
                                ll nv = v + (ll)pos * a[id[h][kh]];    // 该色第 kh+1 小，落在第 pos 位
                                if (h == g && run + 1 >= d) {           // 同色接上正好凑够 d → 触发
                                    if (nv < B[nc]) {
                                        B[nc] = nv;
                                        pb[nc] = h;
                                        pbk[nc] = 0;
                                        pbv[nc] = g * stride + r;
                                    }
                                } else if (h == g) {                    // 同色但还没凑够 d
                                    size_t ns = (size_t)nc * Astep + (size_t)h * stride + run;
                                    if (nv < A[ns]) { A[ns] = nv; pa[ns] = -1; }
                                } else {                                // 换色，连续长度回到 1
                                    size_t ns = (size_t)nc * Astep + (size_t)h * stride;
                                    if (nv < A[ns]) { A[ns] = nv; pa[ns] = g * stride + r; }
                                }
                            }
                        }
                    }
                    // --- 从 B 态扩展：奖励已经拿过，后面怎么排都不再受限制 ---
                    ll vb = B[code];
                    if (vb < INF) {
                        for (int h = 0; h < C; ++h) {
                            int kh = (code / radix[h]) % (sz[h] + 1);
                            if (kh >= sz[h]) continue;
                            int nc = code + radix[h];
                            ll nv = vb + (ll)pos * a[id[h][kh]];
                            if (nv < B[nc]) {
                                B[nc] = nv;
                                pb[nc] = h;
                                pbk[nc] = 1;
                            }
                        }
                    }
                }
            }

            // ---------- 收集本 y 的最优解 ----------
            ll best = INF;
            int kind = -1, bcode = -1, bg = 0, br = 0;
            for (int code : layer[y]) {
                for (int g = 0; g < C; ++g) {
                    for (int r = 0; r < Rmax; ++r) {
                        ll v = A[(size_t)code * Astep + (size_t)g * stride + r];
                        if (v < best) { best = v; kind = 0; bcode = code; bg = g; br = r; }
                    }
                }
                if (B[code] < INF) {
                    ll f = B[code] - W;            // 触发过奖励：总代价减 W，但不小于 0
                    if (f < 0) f = 0;
                    if (f < best) { best = f; kind = 1; bcode = code; }
                }
            }
            if (best > m) continue;                // 这个 y 达不到，继续找更小的 y

            // ---------- 回溯出颜色串 ----------
            vector<int> kfin(C, 0);
            for (int g = 0; g < C; ++g) kfin[g] = (bcode / radix[g]) % (sz[g] + 1);
            vector<int> word(y + 1, -1);
            {
                int code = bcode, g = bg, r = br, kd = kind;
                for (int p = 1; p <= y; ++p) {
                    if (kd == 1) {                          // B 态：最左端颜色存在 pb 里
                        int h = pb[code];
                        word[p] = h;
                        int prv = pbk[code];
                        int pack = pbv[code];
                        int pc = code - radix[h];
                        code = pc;
                        if (pc == 0) break;                 // 前驱为空，回溯结束
                        if (prv == 1) { kd = 1; }           // 前驱还是 B 态
                        else { kd = 0; g = pack / stride; r = pack % stride; }
                    } else {                                // A 态：最左端颜色就是 g
                        int h = g;
                        word[p] = h;
                        size_t st = (size_t)code * Astep + (size_t)h * stride + r;
                        int pack = pa[st];
                        int pc = code - radix[h];
                        code = pc;
                        if (pc == 0) break;
                        if (r > 0) { r = r - 1; }           // 同色截掉一个，连续长度减一
                        else { g = pack / stride; r = pack % stride; }
                    }
                }
            }
            // ---------- 颜色串 → 具体模块：同色内第 i 次（从左）出现取第 k-i+1 小 ----------
            vector<int> seen(C, 0);
            ansOrd.clear();
            for (int p = 1; p <= y; ++p) {
                int h = word[p];
                ++seen[h];
                ansOrd.push_back(id[h][kfin[h] - seen[h]]);
            }
            ansY = y;
            ansX = best;
            break;
        }

        // ---------- 输出 ----------
        if (ansY == 0) {
            cout << -1 << "\n";                    // 一个都破解不起
        } else {
            cout << ansX << " " << ansY << "\n";
            for (int i = 0; i < ansY; ++i)
                cout << ansOrd[i] + 1 << (i + 1 == ansY ? '\n' : ' ');
        }
    }
    return 0;
}
```

### 易错点

奖励只减免一次，不按连续段个数重复减。逆向构造使同色模块按从小到大使用，还原正向序列时顺序相反。

## F. Flower_Rainbow_and_Serenity

### 题意

询问有多少区间包含四个依次出现的位置，其值 $A,B,C,D$ 满足 $A-B,D-A,C-D$ 都不小于 $K$。

### 从零讲：把瓶颈值拆成两半（二分交界点）

固定两端，在中间插入分割点 $s$，左边选最小值作第二点、右边选最大值作第三点，得到

$$h(L,R)=\max_{L+1\le s\le R-2}\min\left(a_L-\min_{[L+1,s]}a,\ \max_{[s+1,R-1]}a-a_R\right).$$

分割点向右移时，左项不减、右项不增。因此两者较小值在交界前由左项控制、交界后由右项控制，最大值只可能在交界两侧或边界取得。二分最后一个左项不超过右项的位置，再检查它及下一位置即可。代码固定左端后维护内部区间的前缀最小值，右侧区间最大值用稀疏表常数时间查询。

### 思路

给每个区间存可支持的最大阈值 $T(L,R)$，没有合法非负阈值则记负一。全部阈值排序后，每次查询只需二分数出不小于 $K$ 的数量。

先固定四元组两端为 $L,R$，中间两点的最优瓶颈为基础小节中的 $h(L,R)$；完整阈值还受两端差限制，所以 $g(L,R)=\min(a_R-a_L,h(L,R))$。长度不足四或该值为负时不可用。

![三项限制共同决定四元组阈值](assets/f-bottleneck.svg)

区间内的四元组未必顶满两端，因此递推 $T(L,R)=\max(g(L,R),T(L+1,R),T(L,R-1))$。按左端递减、右端递增计算，恰好把所有内含端点对的阈值汇总。

区间最值预处理后，每个端点对花 $O(\log n)$，总时间 $O(n^2\log n+q\log n)$，空间 $O(n^2)$。

### 参考代码

```cpp
// F. Flower_Rainbow_and_Serenity
// 题意：多测。给 a[1..n] 和 q 个 K，问有多少个区间 [L,R] 里存在 i1<i2<i3<i4 满足
//       a[i1]-a[i2] >= K, a[i4]-a[i1] >= K, a[i3]-a[i4] >= K。
//
// 记这四个位置为 p1<p2<p3<p4（i1..i4 就是它们的位置序），值记 A,B,C,D：
//   三条约束 = A-B>=K, D-A>=K, C-D>=K，即值的大小是 B < A < D < C，相邻差都 >=K。
//   注意它是"之字形"：位置上是 A,B,C,D，值时却是 B,A,D,C —— 不是单调台阶。
//   一个四元组能被哪些区间装下，只取决于它的最小下标 L 和最大下标 R。
//
// 分解（关键）：
//   g(L,R) = 端点下标恰为 L、R 的四元组的最优阈值
//          = min( a_R-a_L, h(L,R) )，  h(L,R) = max_{L<q<r<R} min(a_L-a_q, a_r-a_R)；
//   h 再按分割点 m 拆成两半：
//          h(L,R) = max_{L<m<R} min( a_L - min(a[L+1..m]), max(a[m+1..R-1]) - a_R )；
//   随 m 增大左半不减、右半不增，所以"左半<=右半"关于 m 单调成立，
//   二分出交界点，最优值只可能在交界点 m* 与 m*+1 上 —— 单个 (L,R) 只要 O(log n)。
//   T(L,R) = max{ g(L',R') : L<=L', R'<=R }，用 L 倒序、R 正序的二维前缀 max 滚一行求。
// 最后把所有 T(L,R)>=0 收进数组排序，每个询问二分数"有多少个 T>=K"。
#include <bits/stdc++.h>
using namespace std;

static const int MAXN = 2505;    // n 上限（单文件 sum n <= 2500）
static const int LOGN = 12;      // 2^11 = 2048 < 2500 <= 4096

int n, qn;                       // 数组长度、本组询问数
int a[MAXN];                     // 数组元素（1 下标，1 <= a[i] <= 1e9）
int pmin_[MAXN];                 // pmin_[m] = min(a[L+1..m])，对每个 L 现算
int st_[LOGN][MAXN];             // 稀疏表：区间最大值
int lg_[MAXN];                   // 区间长度的 log2 下取整
int rowCur[MAXN], rowNxt[MAXN];  // 二维前缀 max DP 的两行；-1 表示"不存在"

// 闭区间最大值（调用前保证 lo <= hi）
static inline int rangeMax(int lo, int hi) {
    int k = lg_[hi - lo + 1];
    int x = st_[k][lo], y = st_[k][hi - (1 << k) + 1];
    return x > y ? x : y;
}

int main() {
    ios::sync_with_stdio(false);   // 多测 + 5e5 询问，关同步加速
    cin.tie(nullptr);
    for (int i = 2; i < MAXN; i++) lg_[i] = lg_[i >> 1] + 1;   // 预处理 log2
    int T;
    cin >> T;
    string out;                    // 攒输出，最后一次吐出
    vector<int> vals;              // 各区间阈值 T(L,R)（只收 >= 0 的）
    while (T--) {
        cin >> n >> qn;
        for (int i = 1; i <= n; i++) cin >> a[i];
        for (int i = 1; i <= n; i++) st_[0][i] = a[i];         // 稀疏表第 0 层
        for (int k = 1; (1 << k) <= n; k++)
            for (int i = 1; i + (1 << k) - 1 <= n; i++)
                st_[k][i] = max(st_[k - 1][i], st_[k - 1][i + (1 << (k - 1))]);
        vals.clear();
        vals.reserve((size_t)n * n / 2 + 8);
        for (int i = 1; i <= n; i++) rowNxt[i] = -1;           // T(n+1, R) = 不存在
        for (int L = n; L >= 1; L--) {                         // 左端点从大到小滚
            for (int i = 1; i <= n; i++) rowCur[i] = -1;       // 这一行先放 g(L,R)
            if (L + 3 <= n) {                                  // 至少 4 个数才可能有四元组
                int pm = INT_MAX;
                for (int m = L + 1; m <= n; m++) {             // 前缀最小值
                    if (a[m] < pm) pm = a[m];
                    pmin_[m] = pm;
                }
                for (int R = L + 3; R <= n; R++) {
                    const int lo = L + 1, hi = R - 2;          // 分割点 m 的范围
                    int l = lo, r = hi, mstar = lo - 1;        // 最大的"左半<=右半"的 m
                    while (l <= r) {
                        int mid = (l + r) >> 1;
                        int lv = a[L] - pmin_[mid];                    // 左半：a_L - min(a[L+1..m])
                        int rv = rangeMax(mid + 1, R - 1) - a[R];      // 右半：max(a[m+1..R-1]) - a_R
                        if (lv <= rv) { mstar = mid; l = mid + 1; } else r = mid - 1;
                    }
                    int h = INT_MIN;                           // max_m min(左半, 右半)
                    for (int c = 0; c < 2; c++) {              // 只需查交界点两侧
                        int m = mstar + c;
                        if (m < lo) m = lo;
                        if (m > hi) m = hi;
                        int f = min(a[L] - pmin_[m], rangeMax(m + 1, R - 1) - a[R]);
                        if (f > h) h = f;
                    }
                    int g = min(a[R] - a[L], h);               // 再夹上"D-A>=K"那一项
                    if (g >= 0) rowCur[R] = g;                 // 阈值 < 0 的四元组对 K>=0 无用
                }
            }
            int run = -1;                                      // = 更新后的 rowCur[R-1]
            for (int R = 1; R <= n; R++) {                     // 二维前缀 max
                int v = rowCur[R];
                if (rowNxt[R] > v) v = rowNxt[R];              // 左端点更靠右的四元组
                if (run > v) v = run;                          // 右端点更靠左的四元组
                rowCur[R] = v;
                run = v;
            }
            for (int R = L + 3; R <= n; R++)                   // 收集本行所有区间的阈值
                if (rowCur[R] >= 0) vals.push_back(rowCur[R]);
            swap(rowCur, rowNxt);                              // 滚到下一行
        }
        sort(vals.begin(), vals.end());                        // 排序后询问二分
        for (int i = 0; i < qn; i++) {
            int K;
            cin >> K;
            int ge = (int)(vals.end() - lower_bound(vals.begin(), vals.end(), K));
            out += to_string(ge);
            out += '\n';
        }
    }
    cout << out;
    return 0;
}
```

### 易错点

$K=0$ 允许数值相等，不能把三条不等式强行解释成严格大小顺序。统计区间存在性，不是区间内四元组数量。

## A. 橙子汽水

### 题意

两堆硬币各有 $x,y$ 枚，每次从至少两枚的一堆取走两枚，给另一堆添一枚，不能操作的人输，求胜者。

### 思路

每步总数减一，而差值只会加三或减三。因此终局的总数奇偶性由差值模三决定：差值不是三的倍数，终局是一枚；差值是三的倍数，终局总数为偶数。

总步数等于初始总数减终局总数。步数为奇数时先手 Alice 获胜，故差值整除三时检查 $x+y$ 为奇数，否则检查 $x+y$ 为偶数。双方的选择不会改变胜负，每组时间、空间 $O(1)$。

### 参考代码

```cpp
// A. 橙子汽水：结论题——总局数的奇偶性被初始两堆数量完全决定，先手胜负与策略无关。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);          // 关闭 cin 与 stdio 的同步，加快读入
    cin.tie(nullptr);                     // 解除 cin 与 cout 的绑定，避免每次读入都刷输出

    int T;
    cin >> T;                             // 测试数据组数
    while (T--) {
        long long x, y;
        cin >> x >> y;                    // 两堆硬币的初始数量（最大 10^9，用 long long 存）
        long long sum = x + y;            // 总硬币数：每回合「拿走 2 枚、加入 1 枚」必使总数减 1
        long long r = ((x - y) % 3 + 3) % 3;  // (x - y) mod 3 是不变量，先取成 0/1/2 的非负余数
        // 终局时两堆都不足 2 枚，即每堆只可能是 0 或 1：r=1 时终局必为 (1,0)、r=2 时必为 (0,1)，
        // 两种情况总数都是 1；r=0 时终局是 (0,0) 或 (1,1)，总数 0 或 2，奇偶性一致。
        long long moves = (r == 0) ? sum : sum - 1;  // 总局数（想怎么走都改不了它的奇偶）
        cout << (moves % 2 == 1 ? "Alice" : "Bob") << '\n';  // 奇数回合打完则先手 Alice 胜
    }
    return 0;
}
```

### 易错点

只需判断差值能否被三整除，负差值无须手工转成非负余数。

## B. 啊！美丽卡洛

### 题意

为每个 $a_i$ 选择互不相同的整数 $b_i$，要求 $|a_i-b_i|\le k$，求最小非负整数 $k$。

### 思路

例如三个数都为五，半径零只有一个可选值，半径一可以取四、五、六。半径增大只会增加选择，因此二分答案。

固定 $k$，将 $a$ 排序，依次取 $b_i=\max(a_i-k,b_{i-1}+1)$。若超过 $a_i+k$，本次判定失败。排序后左右端点均递增；一组可行分配中若两个值逆序，交换后仍分别位于各自区间，所以可以只考虑递增分配。贪心始终取最小合法值，给后续留下的空间最大，失败时任何递增分配都无法完成。

代码二分范围为零到 $10^9$：在上界处取 $b_i=i$ 必定合法。时间 $O(n\log n+n\log V)$，其中 $V=10^9$；空间 $O(n)$。

### 参考代码

```cpp
// B. 啊！美丽卡洛
// 题意：给定 n 个整数 a_i，求最小的非负整数 k，使得存在 n 个互不相同的整数 b_i，
//       满足 b_i ∈ [a_i - k, a_i + k]。
// 做法：k 越大，每个区间只会变宽，可行性关于 k 单调不降 —— 于是二分 k。
//       判定 k 是否可行：把 a 升序排序，依次给每个元素挑「尽量小的、且没被占用过的」b 值，
//       即 b_i = max(a_i - k, 上一个 b + 1)；一旦这个值超过 a_i + k 就说明无解。
#include <bits/stdc++.h>
using namespace std;

int n;                      // 数组长度
vector<long long> a;        // 排序后的数组

// 判定：k 给定时，能否选出互不相同的 b_i，使 b_i ∈ [a_i - k, a_i + k]
bool feasible(long long k) {
    long long prev = LLONG_MIN / 4;         // 上一个选定的 b 值，第一个元素没有前驱约束
    for (int i = 0; i < n; i++) {
        long long lo = a[i] - k;            // 第 i 个元素能取的左端
        long long hi = a[i] + k;            // 第 i 个元素能取的右端
        long long cur = max(lo, prev + 1);  // 贪心：在合法范围内取最小的、且严格大于 prev 的值
        if (cur > hi) return false;         // 区间里已经没有可用整数，k 不够大
        prev = cur;                         // 把这个值占掉，继续看下一个元素
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);            // 关闭与 stdio 的同步，加速读入
    cin.tie(nullptr);                       // 解除 cin 与 cout 的绑定
    int T;                                  // 数据组数
    cin >> T;
    while (T--) {
        cin >> n;
        a.resize(n);
        for (int i = 0; i < n; i++) cin >> a[i];
        sort(a.begin(), a.end());           // 贪心必须按升序处理
        long long lo = 0, hi = 1000000000LL; // k = 1e9 一定可行（取 b_i = i 即可），作为二分上界
        while (lo < hi) {                   // 二分最小的可行 k
            long long mid = lo + (hi - lo) / 2;
            if (feasible(mid)) hi = mid;    // mid 可行，答案不超过 mid
            else lo = mid + 1;              // mid 不可行，答案至少是 mid + 1
        }
        cout << lo << '\n';
    }
    return 0;
}
```

### 易错点

允许 $b_i$ 为负数，不要额外限制其取值范围。首次选择不受前一个值限制。

## C. 繁华唱遍

### 题意

重排数组，使每个非空真前缀的和与剩余后缀的和模三不同，输出一种排列或报告无解。

### 思路

记总和模三为 $S$、当前前缀和模三为 $P$，条件是 $P\ne S-P$，即禁止 $P=2S\bmod3$。把元素按余数分桶，只需要安排余数一、二的行走次序，余数零不会改变位置。

- $S=1$ 时禁止二，只能按一、二交替，从一开始并以一结束。因此必须 $c_1=c_2+1$。
- $S=2$ 时对称，必须 $c_2=c_1+1$，从二开始交替。
- $S=0$ 时禁止中途回零。第一步任选非零余数，此后当前位置是一就只能加一、是二就只能加二，最后一步才回零。

![模三前缀和的行走](assets/c-residues.svg)

第三种情况下，设非零元素数 $m=c_1+c_2$，必须 $m\ge2$。若 $m$ 为偶数，固定行走要求两类数量相等；若为奇数，要求两类数量相差三，较多者作为第一步。按这个过程模拟即可，无须额外搜索。

$S\ne0$ 时余数零可放在开头或末尾；$S=0$ 时只能放在首个非零元素之后、末个非零元素之前，因为首尾对应的前缀零都不允许提前出现。分桶和构造均为 $O(n)$ 时间、$O(n)$ 空间。

### 参考代码

```cpp
// 繁华唱遍：重排数组，使每个真前缀和与对应后缀和模 3 不同余
// 记总和 S = sum(a) mod 3、前缀和 P_i。题目条件 P_i != S - P_i (mod 3)
// 等价于 2*P_i != S (mod 3)，即每种 S 只禁掉前缀和的一个取值：
//   S = 0 -> P_i != 0；S = 1 -> P_i != 2；S = 2 -> P_i != 1
// 只有余数非 0 的元素会推动前缀和，所以答案只跟各余数的个数有关。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);           // 输出量最大 2e5 个数，关同步提速
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        vector<vector<int>> bucket(3);      // bucket[r]：所有 a_i % 3 == r 的原值
        for (int i = 0; i < n; ++i) {
            int x;
            cin >> x;
            bucket[x % 3].push_back(x);
        }
        int c1 = (int)bucket[1].size();     // 余数 1 的个数
        int c2 = (int)bucket[2].size();     // 余数 2 的个数
        int m = c1 + c2;                    // 会推动前缀和的元素个数
        int S = (c1 + 2 * c2) % 3;          // 总和 mod 3，也就是前缀和的终点

        // 第一步：只看计数判有没有解
        bool ok;
        if (S == 0) {
            // 禁止前缀和 0：首元素与末元素都必须非零（首元素非零才离开 0，
            // 末元素非零才能从 1/2 踩回 0），故 m >= 2
            ok = (m >= 2) && ((m % 2 == 0 && c1 == c2) ||
                              (m % 2 == 1 && abs(c1 - c2) == 3));
        } else if (S == 1) {
            // 禁止前缀和 2：非零元素被逼成 1,2,1,2,...,1
            ok = (c1 == c2 + 1);
        } else {
            // 禁止前缀和 1：非零元素被逼成 2,1,2,1,...,2
            ok = (c2 == c1 + 1);
        }
        if (!ok) {
            cout << "NO\n";
            continue;
        }

        // 第二步：按被逼出来的顺序取非零元素，余数只由「当前位置 + 剩余个数」决定
        vector<int> order;                  // 非零元素的余数出现顺序
        int p = 0;                          // 当前前缀和 mod 3
        if (S == 1 || S == 2) {
            int first = (S == 1 ? 1 : 2);   // 从位置 0 出发只能迈这一步
            int other = 3 - first;          // 迈完之后只剩这一种走法
            for (int k = 0; k < m; ++k) {
                int r = (p == 0 ? first : other);
                order.push_back(r);
                p = (p + r) % 3;
            }
        } else {
            // S == 0：中途一步都不许踩 0，所以每步余数只能是当前位置的值；
            // 首步在位置 0 上二选一，取数量较多的那一类（偶数个时两类一样多）
            int t = (c1 >= c2 ? 1 : 2);
            for (int k = 0; k < m; ++k) {
                int r = (k == m - 1) ? (3 - p) % 3 : (p == 0 ? t : p);
                order.push_back(r);
                p = (p + r) % 3;
            }
        }

        // 第三步：把余数 0 的元素插进空位（它们不改变前缀和，插哪都安全）
        vector<int> ptr(3, 0), res;
        res.reserve(n);
        auto take = [&](int r) { res.push_back(bucket[r][ptr[r]++]); };
        if (S == 0) {
            // 首末都必须是非零元素：第一个非零元素打头，余数 0 的全塞中间
            take(order[0]);
            for (int i = 0; i < (int)bucket[0].size(); ++i) take(0);
            for (int k = 1; k < m; ++k) take(order[k]);
        } else {
            // 禁止的值不是 0，所以余数 0 的元素垫在最前面或最后面都行，这里垫末尾
            for (int k = 0; k < m; ++k) take(order[k]);
            for (int i = 0; i < (int)bucket[0].size(); ++i) take(0);
        }

        cout << "YES\n";
        for (int i = 0; i < n; ++i) cout << res[i] << " \n"[i + 1 == n];
    }
    return 0;
}
```

### 易错点

最后一个前缀不受限制，不能把它也判成非法。全为三的倍数时，任意第一个切口都失败。

## D. 闭眼，我触碰幻想的边界

### 题意

在零值格上放任意多个木桩。每个正数格要求自身所在的两桩之间的格数恰好等于其数值，求合法放法数。边界视为第零和第 $n+1$ 根虚拟木桩。

### 思路

一段两桩之间若有数字，所有数字必须相等，并等于这段长度。令 $H_i$ 表示把木桩放在 $i$、此前各段均合法的方案数，初始 $H_0=1$；正数位置不能放桩，其状态为零。

计算 $H_i$ 时，令 $q$ 为左侧最近的正数位置。枚举上一根木桩 $j$ 可以分成两类：

- $j\ge q$：新段内没有正数，贡献为 $\sum_{j=q}^{i-1}H_j$，用前缀和取得；没有正数时令 $q=0$。
- $j<q$：长度必须是 $a_q$，上一根桩唯一可能为 $j_0=i-1-a_q$。它必须满足 $0\le j_0<q$，且段内不存在与 $a_q$ 不同的数字。

记 $d_q$ 为 $q$ 左侧最近的、数值不同的正数位置，没有则为零。第二类只需再检查 $d_q\le j_0$，通过后加入 $H_{j_0}$。维护最近出现的两个不同数值及其位置，便可在线得到 $d_q$。

最后将 $i=n+1$ 作为一定放置的虚拟桩执行同样转移，其状态就是答案。每个位置只做常数次运算，时间、空间 $O(n)$。

### 参考代码

```cpp
// 牛客练习赛 157 D. 闭眼，我触碰幻想的边界
// 思路：放木桩 = 把连续的非木桩格切成若干「块」，每块两端是木桩（边界 0 和 n+1 也算）。
//       块内每个写了数字的格子都必须等于块长。于是按「块」线性 DP。
#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 998244353;   // 题目要求的模数

int main() {
    ios::sync_with_stdio(false);          // 关掉与 stdio 的同步，读入更快
    cin.tie(nullptr);

    int n;
    cin >> n;                             // 网格长度
    vector<int> a(n + 2, 0);              // 1 下标，a[i] == 0 表示空格
    for (int i = 1; i <= n; ++i) cin >> a[i];

    // prevDiff[q]：q 左边最近的、数值不等于 a[q] 的有数字格子下标（没有就是 0）
    // 只要维护「最后出现的两个不同数值」就够：某个数值只需记住它最后一次出现在哪
    vector<int> prevDiff(n + 2, 0);
    {
        int v1 = 0, i1 = 0;               // 最后一次出现位置最靠后的那个数值（0 表示还没有）
        int v2 = 0, i2 = 0;               // 数值与 v1 不同、位置次靠后的那个
        for (int q = 1; q <= n; ++q) {
            if (a[q] == 0) continue;      // 空格不参与
            int z = 0;                    // 默认：左边没有「数值不同」的格子
            if (v1 != 0 && v1 != a[q]) {
                z = i1;                   // 最靠后的那个数值就不同，直接用它的位置
            } else if (v2 != 0) {
                z = i2;                   // 否则只能退到第二靠后的数值
            }
            prevDiff[q] = z;
            // 把「数值 a[q] 最后出现在 q」记进两个槽
            if (v1 == a[q]) {
                i1 = q;                                   // 老数值，刷新位置
            } else if (v2 == a[q]) {
                i2 = q;                                   // 命中第二槽
                if (i2 > i1) { swap(i1, i2); swap(v1, v2); }   // q 最大，换到第一槽
            } else {
                v2 = v1; i2 = i1; v1 = a[q]; i1 = q;      // 全新数值顶到第一槽
            }
        }
    }

    // H[i]：第 i 格放木桩、且 1..i 号格全部满足要求的方案数；H[0] = 1 表示左边界虚拟木桩
    vector<long long> H(n + 1, 0), pre(n + 1, 0);
    H[0] = 1;                             // 虚拟木桩，空前缀算一种方案
    pre[0] = 1;                           // pre[k] = H[0] + ... + H[k]（模 MOD）
    int last = 0;                         // i 左边最近的有数字格子（0 表示没有）
    for (int i = 1; i <= n; ++i) {
        long long cur = 0;
        if (a[i] == 0) {                  // 只有空格能放木桩
            int q = last;                 // 待定块 (j, i) 里最靠右的有数字格子
            // 情况一：上一根木桩 j 落在 [q, i-1]，块里一个数字都没有，长度随便
            long long sA = pre[i - 1] - (q >= 1 ? pre[q - 1] : 0);
            cur = ((sA % MOD) + MOD) % MOD;
            // 情况二：块里有数字，那只能是 q，块长被锁成 a[q]，于是 j 只能是 i-1-a[q]
            if (q >= 1) {
                int j0 = i - 1 - a[q];
                // j0 要落在 [0, q)（否则块里就没数字、属于情况一），
                // 还要保证 (j0, q) 之间没有别的「数值不等于 a[q]」的数字格子
                if (j0 >= 0 && j0 < q && prevDiff[q] <= j0) cur += H[j0];
            }
            cur %= MOD;
        }
        H[i] = cur;
        pre[i] = (pre[i - 1] + cur) % MOD;
        if (a[i] > 0) last = i;           // 有数字，刷新「最近的有数字格子」
    }

    long long ans;
    int q = last;                         // 全局最靠右的有数字格子
    if (q == 0) {
        ans = pre[n];                     // 一个数字都没有：2^n 种放法全合法
    } else {
        // 情况一：最后一根木桩 j 落在 [q, n]，末块里没有数字
        ans = ((pre[n] - pre[q - 1]) % MOD + MOD) % MOD;
        // 情况二：末块最靠右的数字是 q，块长锁成 a[q]，于是 j 只能是 n-a[q]
        int j0 = n - a[q];
        if (j0 >= 0 && j0 < q && prevDiff[q] <= j0) ans = (ans + H[j0]) % MOD;
    }
    cout << ans << "\n";
    return 0;
}
```

### 易错点

相邻木桩之间允许空段。两类必须用 $j\ge q$ 与 $j<q$ 分开，否则固定候选可能重复计数。

## E. 入秋的第一场雨真让人矫情

### 题意

枚举所有满足 $1\le b_i\le c_i$ 的数组。一次可以给一个两侧为零的正数连续段整体减去正整数，求全部数组最少清零次数之和。

### 从零讲：为什么 $f(b)$ 等于「特殊区间」的个数

正数段中不能跨过零来减正数，所以每次操作必须选一个当前极长正数段。对它减去最小值，会立刻消去至少一格；减得更少只会保留同一个段，后续同段操作可合并，因此最优方案总能先减至出现零，再递归处理剩余子段。

![三个被处理的连通块](assets/e-components.svg)

原数组中的区间 $[l,r]$ 恰好会成为一次这样的处理对象，当且仅当其最小值严格大于左右邻居：它在高度达到自身最小值之前保持连通，而两侧已断开。相反，每个递归处理段也必然满足这个边界条件。于是 $f(b)$ 等于这些特殊区间的个数；相等的最小值会一起清零，不需要拆成多次操作。

### 思路

由特殊区间的刻画，交换“数组”和“区间”的求和次序，枚举区间最小值 $V$。令

$$p_i=\max(0,c_i-V+1),\qquad q_i=\max(0,c_i-V).$$

它们分别是位置 $i$ 取至少 $V$、严格大于 $V$ 的选择数，因此区间 $[l,r]$ 的最小值恰好为 $V$ 有 $\prod_{i=l}^r p_i-\prod_{i=l}^r q_i$ 种取法。

区间左邻居必须小于 $V$，有 $\min(c_{l-1},V-1)$ 种取法；再乘更左侧各位置自由取值的前缀积，得到左权重 $x_l$。右边同理得到 $y_r$。如果邻居在数组外，其值固定为零，对应权重直接为一，不参与自由取值。

固定 $V$，维护 $T_r=\sum_{l\le r}x_l\prod_{i=l}^r p_i$。上一轮所有区间扩展一格，再新开区间 $[r,r]$，所以

$$T_r=p_r(T_{r-1}+x_r).$$

将 $T_ry_r$ 加入答案，再用 $q$ 做同样递推并减去贡献。每个特殊区间只在其唯一最小值处计数。枚举 $1\le V\le\max c_i$，时间 $O(n\max c_i)$、空间 $O(n)$。

### 参考代码

```cpp
// 牛客练习赛 157 E. 入秋的第一场雨真让人矫情
// 关键结论（下面注释里推）：一次操作 = 把一个「极大正段」整体减 x；
//   最优操作次数 f(b) 恰好等于满足下面条件的区间 [l,r] 的个数：
//       min(b_l..b_r) > b_{l-1} 且 min(b_l..b_r) > b_{r+1}   （越界位置按 b_0 = b_{n+1} = 0 算）
//   于是把「求和的 f」换成「对每个区间数有多少个 b 满足条件」，按阈值 V = 区间最小值 分层统计。
#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 998244353;   // 题目要求的模数

int main() {
    ios::sync_with_stdio(false);          // 关掉与 stdio 的同步，读入更快
    cin.tie(nullptr);

    int n;
    cin >> n;                             // 数组长度
    vector<int> c(n + 2, 0);              // 1 下标；c[0] 与 c[n+1] 是数组外的位置，恒为 0
    int maxC = 0;                         // 上界里的最大值，决定阈值 V 的枚举范围
    for (int i = 1; i <= n; ++i) {
        cin >> c[i];
        maxC = max(maxC, c[i]);
    }

    // pre[i] = c_1 * ... * c_i，suf[i] = c_i * ... * c_n（均取模）；越界时按 1 算（空乘积）
    vector<long long> pre(n + 3, 1), suf(n + 4, 1);
    for (int i = 1; i <= n; ++i) pre[i] = pre[i - 1] * c[i] % MOD;
    for (int i = n; i >= 1; --i) suf[i] = suf[i + 1] * c[i] % MOD;
    auto PRE = [&](int k) -> long long { return k <= 0 ? 1LL : pre[min(k, n)]; };
    auto SUF = [&](int k) -> long long { return k >= n + 1 ? 1LL : suf[max(k, 1)]; };

    vector<long long> x(n + 2, 0), y(n + 2, 0);   // 区间的左权重、右权重
    long long ans = 0;
    for (int V = 1; V <= maxC; ++V) {             // 枚举区间的「最小值阈值」V
        int w = V - 1;                            // 邻居的值必须落在 1..w 里才小于 V
        for (int l = 1; l <= n; ++l) {
            // b_{l-1} < V 的取法数；l == 1 时左边是数组外的 0，没有自由度
            long long leftChoices = (l == 1) ? 1LL : min<long long>(c[l - 1], w);
            x[l] = PRE(l - 2) * leftChoices % MOD;      // 左侧远处格子随便取：乘前缀积
        }
        for (int r = 1; r <= n; ++r) {
            long long rightChoices = (r == n) ? 1LL : min<long long>(c[r + 1], w);
            y[r] = SUF(r + 2) * rightChoices % MOD;     // 右侧远处格子随便取：乘后缀积
        }
        long long tA = 0, tB = 0, sA = 0, sB = 0;
        for (int r = 1; r <= n; ++r) {
            long long p = c[r] >= V     ? (c[r] - V + 1) : 0;   // b_r >= V 的取法数
            long long q = c[r] >= V + 1 ? (c[r] - V)     : 0;   // b_r >  V 的取法数
            tA = p * (tA + x[r]) % MOD;   // 以 r 结尾、区间内全部 >= V 的加权区间数
            tB = q * (tB + x[r]) % MOD;   // 以 r 结尾、区间内全部 >  V 的加权区间数
            sA = (sA + tA * y[r]) % MOD;
            sB = (sB + tB * y[r]) % MOD;
        }
        ans = (ans + sA - sB) % MOD;      // sA - sB：区间内全部 >= V 且至少一个恰好 = V
    }
    cout << (ans % MOD + MOD) % MOD << "\n";   // 取模后转成正数输出
    return 0;
}
```

### 易错点

邻居取值上界是 $V-1$，不能写成 $V$。数组外的零只有一种取法；前后缀积不能把邻居再次乘入。

## F. 单向地铁

### 题意

图含前进边 $i\to i+1$ 和左跳边 $i\to p_i$，其中 $p_i\le i$。每次修改一条左跳边后，求所有起点的可达结点数之和。

### 从零讲：好点与坏段

把位置 $l$ 看作“$l-1$ 与 $l$ 之间的切口”。如果某条左跳边从右侧跨到左侧，这个切口是坏点；否则是好点。一条边 $i\to p_i$ 跨过的恰是 $p_i+1,\ldots,i$。

从 $i$ 最左能走到的位置，正是“不大于 $i$ 的最大好点”。好点阻止继续左移；在到它之前，每遇到一个坏切口，都存在右侧结点的左跳边跨过它，而前进边让我们能够先到这个结点。因此可以逐个越过中间所有坏切口，最终抵达这个好点。这个刻画把动态可达性变成了动态区间覆盖。

### 思路

若没有左跳边，从 $i$ 可达 $i,i+1,\ldots,n$，基础答案为 $n(n+1)/2$。一段连续坏点为 $[a,b]$ 时，段内位置 $i$ 最左可到 $a-1$，比基础多出 $i-a+1$ 个结点，因此长度 $h$ 的坏段额外贡献

$$1+2+\cdots+h=\frac{h(h+1)}2.$$

![覆盖切口与坏段贡献](assets/f-cuts.svg)

每条左跳边覆盖区间 $[p_i+1,i]$，修改就是删除旧区间、加入新区间。用线段树维护覆盖次数是否为正，以及连续覆盖段的三角数之和。

代码的每个结点保存整段覆盖计数、被覆盖前缀长度、后缀长度、完全在内部的坏段贡献。整段计数为正时前后缀均为全长、内部贡献为零；否则合并两个孩子，拼接左后缀和右前缀，只有拼接段不接触当前区间两端时才计入内部贡献。根的内部贡献加两端坏段贡献就是额外答案。

整段覆盖计数采用区间并的维护方式，不下传：删除区间时走与添加时相同的分解，孩子保留自身覆盖状态。建树与修改共 $O((n+q)\log n)$ 时间、$O(n)$ 空间。

### 参考代码

```cpp
// F. 单向地铁（牛客练习赛 157 F）
// 结论一：从 i 出发能到达的结点恰好是编号连续的一段 [L_i, n]。
// 结论二：L_i = i 左边最近的「好点」，而 l 是好点当且仅当没有一条边
//         u -> p_u (u >= l) 跨过它，等价于 l 不被任何区间 [p_u + 1, u] 盖住。
// 结论三：答案 = n(n+1)/2 + Σ_极长坏段 len(len+1)/2，坏段 = 被覆盖的极长连续段。
// 于是只需一棵「覆盖计数 + 极长段信息」的线段树，支持区间 +1 / -1。
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 500005;                 // 结点数上限
int n, q;                                // 结点数、修改次数
int p[MAXN];                             // p[i]：i 的跳跃边指向 p[i]（保证 p[i] <= i）

// 线段树下标从 1 开始，开四倍空间
// cnt[v]：把 v 管辖的整个区间都盖住的区间条数（懒标记，直接 +/-1，不下传）
// pre[v]：v 区间内「从左端点开始」连续被覆盖的长度
// suf[v]：v 区间内「到右端点结束」连续被覆盖的长度
// val[v]：完全落在 v 内部（左右两端都不贴）的极长坏段的 Σ len(len+1)/2
int cnt[4 * MAXN], pre[4 * MAXN], suf[4 * MAXN];
long long val[4 * MAXN];

inline long long tri(long long x) { return x * (x + 1) / 2; }   // 长 x 的坏段的贡献

// 用两个孩子重算 v；l、r 是 v 管辖的区间端点
inline void pull(int v, int l, int r) {
    int len = r - l + 1;                              // v 的区间长度
    if (cnt[v] > 0) {                                 // 整段被盖住
        pre[v] = suf[v] = len;                        // 左右两端都连续覆盖满
        val[v] = 0;                                   // 内部没有「完整的」坏段
        return;
    }
    if (l == r) {                                     // 叶子而且没被盖住
        pre[v] = suf[v] = 0;                          // 两端连续覆盖长度都是 0
        val[v] = 0;                                   // 内部没有坏段
        return;
    }
    int L = v << 1, R = L | 1;                        // 左、右孩子编号
    int lenL = ((r - l) >> 1) + 1;                    // 左孩子长度（mid = (l+r)>>1）
    int lenR = len - lenL;                            // 右孩子长度
    // 先处理「贴在中点上的那一条或两条坏段」：它们没被任何孩子算进 val，
    // 但除了变成 v 的前缀段 / 后缀段以外，都要在这里补算一次。
    long long s = val[L] + val[R];                    // 两个孩子内部本来就完整的坏段
    if (suf[L] > 0 && pre[R] > 0) {                   // 左右各有一条在中点处接上
        if (suf[L] < lenL && pre[R] < lenR)           // 两端都不贴 v 的边界才是完整段
            s += tri((long long)suf[L] + pre[R]);
    } else if (suf[L] > 0) {                          // 只有左边那条正好在中点收尾
        if (suf[L] < lenL) s += tri(suf[L]);          // 它没盖满左孩子，所以是完整段
    } else if (pre[R] > 0) {                          // 只有右边那条从中点右边起步
        if (pre[R] < lenR) s += tri(pre[R]);          // 它没盖满右孩子，所以是完整段
    }
    val[v] = s;                                       // 写回完整坏段的贡献
    pre[v] = (pre[L] == lenL) ? lenL + pre[R] : pre[L];   // 左孩子整段盖满才接着往右伸
    suf[v] = (suf[R] == lenR) ? lenR + suf[L] : suf[R];   // 右孩子整段盖满才接着往左伸
}

// 区间 [ql, qr] 整体加 d（d = +1 加一条边对应的区间，-1 删一条）
void update(int v, int l, int r, int ql, int qr, int d) {
    if (ql <= l && r <= qr) {                         // 完全被更新区间包含
        cnt[v] += d;                                  // 只动懒标记
        pull(v, l, r);                                // 立刻按懒标记刷新
        return;
    }
    int mid = (l + r) >> 1;                           // 否则必须下探（cnt 不下传）
    if (ql <= mid) update(v << 1, l, mid, ql, qr, d);         // 左半边有交
    if (qr > mid) update(v << 1 | 1, mid + 1, r, ql, qr, d);  // 右半边有交
    pull(v, l, r);                                    // 回溯时重算自己
}

int main() {
    ios::sync_with_stdio(false);                      // 关掉与 stdio 的同步
    cin.tie(nullptr);                                 // 解除 cin 与 cout 的绑定
    cin >> n >> q;                                    // 读入 n、q
    for (int i = 1; i <= n; i++) {
        cin >> p[i];                                  // 读入初始 p
        if (p[i] < i)                                 // p_i = i 的边是自环，区间为空
            update(1, 1, n, p[i] + 1, i, 1);          // 初始把区间 [p_i+1, i] 盖上
    }
    long long base = (long long)n * (n + 1) / 2;      // 公式里与坏段无关的那一半
    while (q--) {
        int x, y;
        cin >> x >> y;                                // 读一次修改
        if (p[x] < x)                                 // 旧边不是自环才有旧区间
            update(1, 1, n, p[x] + 1, x, -1);         // 删掉旧区间
        if (y < x)                                    // 新边不是自环才有新区间
            update(1, 1, n, y + 1, x, 1);             // 盖上新区间
        p[x] = y;                                     // 同步 p
        long long bad;                                // 所有极长坏段的 Σ len(len+1)/2
        if (pre[1] == n) bad = tri(n);                // 整条数组就是一条坏段
        else bad = val[1] + tri(pre[1]) + tri(suf[1]); // 内部完整段 + 贴左右两端的段
        cout << base + bad << "\n";                    // 输出本次答案
    }
    return 0;
}
```

### 易错点

位置一永远不被任何合法左跳边覆盖。空区间 $p_i=i$ 不更新；覆盖次数可大于一，删除一条边不等于将区间清零。
